css:
.apo-register {
  --apo-register-bg: oklch(0.975 0.007 85);
  --apo-register-ink: oklch(0.22 0.014 60);
  --apo-register-accent: oklch(0.61 0.19 33);
  --apo-register-go: oklch(0.55 0.13 155);
  --apo-register-panel: color-mix(in oklch, var(--apo-register-bg), white 55%);
  --apo-register-sunk: color-mix(in oklch, var(--apo-register-bg), var(--apo-register-ink) 4%);
  --apo-register-line: color-mix(in oklch, var(--apo-register-ink) 11%, transparent);
  --apo-register-line2: color-mix(in oklch, var(--apo-register-ink) 22%, transparent);
  --apo-register-mute: color-mix(in oklch, var(--apo-register-ink) 56%, var(--apo-register-bg));
  --apo-register-tint: color-mix(in oklch, var(--apo-register-accent) 10%, var(--apo-register-panel));
  --apo-register-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --apo-register-ease: cubic-bezier(.2, .8, .2, 1);
  --apo-register-spring: linear(0, .09 4%, .32 10%, .65 17%, .9 25%, 1.03 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  position: relative; width: 100%; height: var(--apo-register-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apo-register;
  overflow: clip; isolation: isolate; border-radius: 14px;
  background: var(--apo-register-bg); color: var(--apo-register-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: light; accent-color: var(--apo-register-accent);
  border: 1px solid var(--apo-register-line);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .38; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apo-register-accent); outline-offset: 2px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & .apo-register-num { font-variant-numeric: tabular-nums; }
  & .apo-register-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apo-register-mute); }
  & kbd { font: 600 10px/1 var(--apo-register-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apo-register-line2); border-bottom-width: 2px; color: var(--apo-register-mute); background: var(--apo-register-panel); }

  & .apo-register-ghost { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 11px; border-radius: 8px; font-size: 13px; font-weight: 600; color: var(--apo-register-ink); border: 1px solid var(--apo-register-line2); background: var(--apo-register-panel); transition: background .18s, border-color .18s, transform .12s var(--apo-register-ease);
    & svg { width: 16px; height: 16px; }
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--apo-register-ink) 5%, var(--apo-register-panel)); border-color: color-mix(in oklch, var(--apo-register-ink) 34%, transparent); }
    &:active:not(:disabled) { transform: scale(.97); }
  }
  & .apo-register-solid { height: 36px; padding: 0 16px; border-radius: 9px; font-weight: 700; color: white; background: var(--apo-register-ink); transition: background .2s, transform .12s var(--apo-register-ease);
    &:hover { background: color-mix(in oklch, var(--apo-register-ink), var(--apo-register-accent) 30%); }
    &:active { transform: scale(.97); }
  }

  & .apo-register-app { height: 100%; display: grid; grid-template: "head head" auto "main side" minmax(0, 1fr) "keys keys" auto / minmax(0, 1fr) clamp(320px, 36cqi, 420px); }

  /* ── header ── */
  & .apo-register-head { grid-area: head; display: flex; align-items: center; gap: 18px; padding: 10px 16px; border-bottom: 1px solid var(--apo-register-line); background: var(--apo-register-panel); }
  & .apo-register-brand { display: flex; align-items: center; gap: 10px; min-width: 0;
    & svg { width: 30px; height: 30px; padding: 5px; border-radius: 8px; color: white; background: var(--apo-register-accent); flex: none; }
    & b { display: block; font-size: 15px; font-weight: 800; letter-spacing: -.015em; white-space: nowrap; }
    & span { display: block; font-size: 12px; color: var(--apo-register-mute); white-space: nowrap; }
  }
  & .apo-register-saleno { display: grid; line-height: 1.15; margin-left: auto; text-align: right;
    & b { font: 650 14px/1.2 var(--apo-register-mono); }
  }
  & .apo-register-clock { font-size: 22px; font-weight: 300; letter-spacing: -.02em; padding-left: 16px; border-left: 1px solid var(--apo-register-line); }
  & .apo-register-headacts { display: flex; gap: 6px; }

  & .apo-register-nav { display: none; }

  /* ── catalog ── */
  & .apo-register-cat { grid-area: main; display: grid; grid-template-rows: auto auto minmax(0, 1fr); min-height: 0; }
  & .apo-register-tools { display: flex; align-items: center; gap: 10px; padding: 14px 16px 10px; }
  & .apo-register-search { flex: 1; display: flex; align-items: center; gap: 8px; height: 40px; padding: 0 10px 0 12px; border-radius: 10px; background: var(--apo-register-panel); border: 1px solid var(--apo-register-line2); transition: border-color .2s, box-shadow .2s;
    & svg { width: 18px; height: 18px; color: var(--apo-register-mute); flex: none; }
    & input { flex: 1; min-width: 0; height: 100%; border: 0; outline: none; background: none; font-size: 14.5px; }
    & input::-webkit-search-cancel-button { appearance: none; }
    &:has(input:focus-visible) { border-color: var(--apo-register-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apo-register-accent) 18%, transparent); }
  }
  & .apo-register-mult { min-width: 0; font-size: 13px; font-weight: 800; padding: 0 12px; height: 40px; display: grid; place-items: center; border-radius: 10px; color: white; background: var(--apo-register-accent); transform-origin: right center; transition: opacity .2s, scale .35s var(--apo-register-spring);
    &:empty { opacity: 0; scale: .6; padding: 0; width: 0; }
  }
  & .apo-register-cats { display: flex; gap: 6px; padding: 0 16px 12px; overflow-x: auto; scrollbar-width: none; }
  & .apo-register-cats button { --h: var(--hue, 60); flex: none; height: 30px; padding: 0 12px; border-radius: 99px; font-size: 12.5px; font-weight: 650; color: var(--apo-register-mute); border: 1px solid var(--apo-register-line); background: transparent; display: inline-flex; align-items: center; gap: 7px; transition: color .2s, background .2s, border-color .2s;
    & i { width: 8px; height: 8px; border-radius: 50%; background: oklch(0.72 0.12 var(--h)); }
    &:hover { color: var(--apo-register-ink); border-color: var(--apo-register-line2); }
    &[aria-selected="true"] { color: white; background: var(--apo-register-ink); border-color: var(--apo-register-ink); }
  }
  & .apo-register-grid { overflow: auto; padding: 2px 16px 16px; display: grid; gap: 10px; align-content: start;
    grid-template-columns: repeat(auto-fill, minmax(clamp(122px, 15cqi, 156px), 1fr)); scrollbar-width: thin; }
  & .apo-register-tile { --h: 60; position: relative; display: grid; grid-template-rows: auto 1fr auto; gap: 4px; min-height: 104px; padding: 12px 12px 10px; text-align: left; border-radius: 12px; background: var(--apo-register-panel);
    border: 1px solid var(--apo-register-line); box-shadow: inset 0 3px 0 oklch(0.74 0.12 var(--h)), 0 1px 0 var(--apo-register-line);
    transition: transform .18s var(--apo-register-ease), box-shadow .2s, border-color .2s;
    & .plu { font: 600 10.5px/1 var(--apo-register-mono); color: var(--apo-register-mute); letter-spacing: .04em; }
    & .nm { font-size: 13.5px; font-weight: 650; line-height: 1.22; text-wrap: balance; }
    & .pr { font-size: 15px; font-weight: 750; letter-spacing: -.01em; display: flex; align-items: baseline; gap: 3px; }
    & .pr small { font-size: 11px; font-weight: 600; color: var(--apo-register-mute); }
    & .badge { position: absolute; top: 8px; right: 8px; min-width: 22px; height: 22px; padding: 0 6px; border-radius: 99px; display: grid; place-items: center; font-size: 11.5px; font-weight: 800; color: white; background: var(--apo-register-accent); }
    & .badge:empty { display: none; }
    &:hover { transform: translateY(-2px); border-color: var(--apo-register-line2); box-shadow: inset 0 3px 0 oklch(0.74 0.12 var(--h)), 0 8px 18px -10px color-mix(in oklch, var(--apo-register-ink) 40%, transparent); }
    &:active { transform: translateY(0) scale(.97); transition-duration: .06s; }
    &[data-pop] .badge { animation: apo-register-pop .45s var(--apo-register-spring); }
  }
  & .apo-register-none { grid-column: 1 / -1; padding: 40px 12px; text-align: center; color: var(--apo-register-mute); }

  /* ── basket ── */
  & .apo-register-basket { grid-area: side; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto auto auto; border-left: 1px solid var(--apo-register-line); background: var(--apo-register-panel); }
  & .apo-register-bhead { display: flex; align-items: baseline; justify-content: space-between; padding: 14px 16px 10px;
    & h2 { font-size: 13px; font-weight: 750; letter-spacing: .1em; text-transform: uppercase; }
  }
  & .apo-register-count { font-size: 12.5px; color: var(--apo-register-mute); }
  & .apo-register-lines { list-style: none; margin: 0; padding: 0 8px 8px; overflow: auto; scrollbar-width: thin; }
  & .apo-register-empty { display: none; grid-row: 2; align-self: center; justify-items: center; gap: 10px; padding: 24px 32px; text-align: center; color: var(--apo-register-mute); font-size: 13px;
    & svg { width: 34px; height: 34px; stroke-width: 1.4; }
  }
  &:has(.apo-register-lines:empty) .apo-register-empty { display: grid; }
  & .apo-register-line { border-radius: 10px; transition: background .2s, opacity .3s, translate .4s var(--apo-register-spring);
    @starting-style { opacity: 0; translate: 18px 0; }
    &:has(> .row[aria-expanded="true"]) { background: var(--apo-register-tint); }
    & .row { width: 100%; display: grid; grid-template-columns: 2.4em minmax(0, 1fr) auto; gap: 2px 10px; padding: 9px 8px; text-align: left; border-radius: 10px; }
    & .row:hover { background: color-mix(in oklch, var(--apo-register-ink) 4%, transparent); }
    & .q { grid-row: span 2; font-weight: 800; font-size: 14px; color: var(--apo-register-mute); }
    & .q svg { width: 18px; height: 18px; stroke-width: 1.6; margin-top: 1px; }
    & .n { font-weight: 650; font-size: 13.5px; line-height: 1.25; min-width: 0; }
    & .a { font-weight: 700; text-align: right; font-size: 14px; }
    & .d { grid-column: 2 / -1; display: flex; justify-content: space-between; gap: 8px; font-size: 11.5px; color: var(--apo-register-mute); }
    & .d .off { color: var(--apo-register-accent); font-weight: 650; }
    & s { color: var(--apo-register-mute); font-weight: 500; font-size: 12px; margin-right: 5px; }
    & .edit { display: grid; grid-template-rows: 0fr; transition: grid-template-rows .35s var(--apo-register-ease); }
    & .edit > div { overflow: hidden; display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 0 8px; }
    & .row[aria-expanded="true"] + .edit { grid-template-rows: 1fr; }
    & .row[aria-expanded="true"] + .edit > div { padding: 2px 8px 10px; }
  }
  & .apo-register-step { display: inline-flex; align-items: center; border: 1px solid var(--apo-register-line2); border-radius: 8px; background: var(--apo-register-panel); height: 30px;
    & button { width: 30px; height: 28px; display: grid; place-items: center; }
    & button:hover:not(:disabled) { color: var(--apo-register-accent); }
    & svg { width: 14px; height: 14px; stroke-width: 2.2; }
    & b { min-width: 26px; text-align: center; font-size: 13px; }
  }
  & .apo-register-chips { display: inline-flex; gap: 3px; padding: 2px; border-radius: 8px; background: color-mix(in oklch, var(--apo-register-ink) 6%, transparent);
    & button { height: 26px; padding: 0 8px; border-radius: 6px; font-size: 12px; font-weight: 650; color: var(--apo-register-mute); }
    & button[aria-checked="true"] { color: white; background: var(--apo-register-accent); }
    & button:hover:not([aria-checked="true"]):not(:disabled) { color: var(--apo-register-ink); }
  }
  & .apo-register-x { margin-left: auto; width: 30px; height: 30px; display: grid; place-items: center; border-radius: 8px; color: var(--apo-register-mute);
    & svg { width: 16px; height: 16px; }
    &:hover { color: var(--apo-register-accent); background: color-mix(in oklch, var(--apo-register-accent) 10%, transparent); }
  }
  & .apo-register-disc { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; padding: 10px 16px; border-top: 1px solid var(--apo-register-line); font-size: 12px;
    & > span { color: var(--apo-register-mute); font-weight: 650; margin-right: auto; }
    & button { height: 26px; padding: 0 9px; border-radius: 99px; font-weight: 650; white-space: nowrap; border: 1px solid var(--apo-register-line2); color: var(--apo-register-mute); transition: background .2s, color .2s; }
    & button[aria-checked="true"] { color: white; background: var(--apo-register-ink); border-color: var(--apo-register-ink); }
    & button:hover:not([aria-checked="true"]):not(:disabled) { color: var(--apo-register-ink); }
  }
  & .apo-register-totals { margin: 0; padding: 6px 16px 10px; display: grid; grid-template-columns: 1fr auto; gap: 3px 12px; font-size: 13px;
    & dt { color: var(--apo-register-mute); }
    & dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }
    & .off { color: var(--apo-register-accent); }
    & .big { font-size: 13px; font-weight: 800; color: var(--apo-register-ink); text-transform: uppercase; letter-spacing: .1em; align-self: end; padding-top: 6px; border-top: 1px solid var(--apo-register-line); }
    & dd.big { font-size: clamp(22px, 2.6cqi, 30px); letter-spacing: -.03em; text-transform: none; padding-top: 4px; line-height: 1.1; }
  }
  & .apo-register-pay { margin: 0 12px 12px; height: 56px; border-radius: 12px; display: flex; align-items: center; gap: 12px; padding: 0 18px; color: white; font-size: 16px; font-weight: 800;
    background: var(--apo-register-accent); box-shadow: 0 10px 22px -12px var(--apo-register-accent), inset 0 -2px 0 color-mix(in oklch, black 18%, transparent);
    transition: transform .14s var(--apo-register-ease), background .2s, box-shadow .2s;
    & b { margin-left: auto; font-size: 18px; letter-spacing: -.01em; }
    & kbd { color: white; border-color: color-mix(in oklch, white 40%, transparent); background: color-mix(in oklch, white 14%, transparent); }
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--apo-register-accent), black 8%); }
    &:active:not(:disabled) { transform: scale(.985); }
  }

  /* ── tender ── */
  & .apo-register-tender { grid-area: main; min-height: 0; overflow: auto; display: none; grid-auto-rows: max-content; padding: 18px 20px 20px; gap: 16px; align-content: start; grid-template-columns: minmax(0, 1fr) minmax(220px, 260px); grid-template-areas: "due due" "rib rib" "meth pad" "list pad"; }
  &[data-mode="tender"] .apo-register-cat { display: none; }
  &[data-mode="tender"] .apo-register-tender { display: grid; }
  &[data-mode="tender"] .apo-register-pay, &[data-mode="tender"] .apo-register-disc { display: none; }
  & .apo-register-body { display: contents; }
  & .apo-register-done ~ .apo-register-tlist { grid-column: 1 / -1; grid-row: 4; }
  & .apo-register-line .row:disabled { opacity: 1; cursor: default; }
  & .apo-register-due { grid-area: due; display: flex; align-items: end; gap: 16px; flex-wrap: wrap;
    & .lbl { font-size: 12px; font-weight: 700; letter-spacing: .14em; text-transform: uppercase; color: var(--apo-register-mute); }
    & .amt { font-size: clamp(40px, 6.4cqi, 68px); font-weight: 800; letter-spacing: -.045em; line-height: .95; }
    & .sub { color: var(--apo-register-mute); font-size: 13px; padding-bottom: 6px; }
    & .back { margin-left: auto; align-self: start; }
  }
  & .apo-register-ribbon { grid-area: rib; display: grid; gap: 8px; }
  & .apo-register-bar { display: flex; height: 22px; border-radius: 7px; overflow: hidden; gap: 2px; background: var(--apo-register-sunk);
    & span { flex: var(--g) 1 0; min-width: 0; transition: flex-grow .7s var(--apo-register-spring); @starting-style { flex-grow: 0; } }
    & .cash { background: var(--apo-register-go); }
    & .card { background: var(--apo-register-ink); }
    & .gift { background: oklch(0.72 0.13 75); }
    & .rest { background: repeating-linear-gradient(135deg, color-mix(in oklch, var(--apo-register-accent) 26%, transparent) 0 6px, transparent 6px 12px); }
  }
  & .apo-register-legend { display: flex; flex-wrap: wrap; gap: 4px 16px; font-size: 12px; color: var(--apo-register-mute);
    & i { display: inline-block; width: 9px; height: 9px; border-radius: 3px; margin-right: 6px; vertical-align: -1px; }
  }
  & .apo-register-meth { grid-area: meth; display: grid; gap: 12px; align-content: start; }
  & .apo-register-amtrow { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; padding: 12px 14px; border-radius: 12px; background: var(--apo-register-panel); border: 1px solid var(--apo-register-line);
    & .lbl { font-size: 12px; font-weight: 650; color: var(--apo-register-mute); }
    & output { font-size: 26px; font-weight: 800; letter-spacing: -.02em; margin-right: auto; }
    & output[data-fresh] { color: var(--apo-register-mute); }
  }
  & .apo-register-methods { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
  & .apo-register-method { display: grid; gap: 4px; justify-items: start; padding: 12px; min-height: 84px; border-radius: 12px; text-align: left; border: 1px solid var(--apo-register-line2); background: var(--apo-register-panel); transition: border-color .2s, transform .14s var(--apo-register-ease), background .2s;
    & svg { width: 22px; height: 22px; }
    & b { font-size: 14px; display: flex; align-items: center; gap: 6px; }
    & small { font-size: 11.5px; color: var(--apo-register-mute); }
    &:hover:not(:disabled) { border-color: var(--apo-register-ink); }
    &:active:not(:disabled) { transform: scale(.97); }
  }
  & .apo-register-quick { display: flex; flex-wrap: wrap; gap: 6px; align-items: center;
    & > span { font-size: 12px; color: var(--apo-register-mute); font-weight: 650; margin-right: 4px; }
    & button { height: 34px; padding: 0 12px; border-radius: 9px; font-weight: 750; color: var(--apo-register-go); border: 1px solid color-mix(in oklch, var(--apo-register-go) 40%, transparent); background: color-mix(in oklch, var(--apo-register-go) 7%, var(--apo-register-panel)); transition: background .2s, transform .12s; }
    & button:hover { background: color-mix(in oklch, var(--apo-register-go) 15%, var(--apo-register-panel)); }
    & button:active { transform: scale(.96); }
  }
  & .apo-register-pad { grid-area: pad; display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; align-content: start;
    & button { height: 48px; border-radius: 10px; font-size: 19px; font-weight: 650; background: var(--apo-register-panel); border: 1px solid var(--apo-register-line); font-variant-numeric: tabular-nums; transition: background .15s, transform .1s; }
    & button:hover { background: color-mix(in oklch, var(--apo-register-ink) 5%, var(--apo-register-panel)); }
    & button:active { transform: scale(.95); background: var(--apo-register-tint); }
    & .wide { grid-column: span 3; font-size: 13px; font-weight: 700; height: 38px; color: var(--apo-register-mute); }
  }
  & .apo-register-tlist { grid-area: list; list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; align-content: start;
    & li { display: grid; grid-template-columns: 28px 1fr auto auto; align-items: center; gap: 10px; padding: 9px 10px; border-radius: 10px; background: var(--apo-register-panel); border: 1px solid var(--apo-register-line); transition: opacity .3s, translate .45s var(--apo-register-spring); @starting-style { opacity: 0; translate: 0 -8px; } }
    & svg { width: 20px; height: 20px; }
    & .t b { display: block; font-size: 13px; }
    & .t small { font-size: 11.5px; color: var(--apo-register-mute); }
    & .v { font-weight: 750; }
  }
  & .apo-register-proc { display: flex; align-items: center; gap: 14px; padding: 14px; border-radius: 12px; color: white; background: var(--apo-register-ink);
    & .rings { position: relative; width: 36px; height: 36px; flex: none; }
    & .rings i { position: absolute; inset: 0; border-radius: 50%; border: 2px solid white; opacity: 0; animation: apo-register-ping 1.4s var(--apo-register-ease) infinite; animation-delay: calc(var(--i) * 280ms); }
    & b { display: block; }
    & small { opacity: .7; font-size: 12px; }
    & button { margin-left: auto; height: 32px; padding: 0 12px; border-radius: 8px; border: 1px solid color-mix(in oklch, white 30%, transparent); font-weight: 650; }
    & button:hover { background: color-mix(in oklch, white 12%, transparent); }
  }
  & .apo-register-done { grid-column: 1 / -1; grid-row: 3; display: grid; justify-items: start; gap: 14px; padding: 22px; border-radius: 16px; background: color-mix(in oklch, var(--apo-register-go) 9%, var(--apo-register-panel)); border: 1px solid color-mix(in oklch, var(--apo-register-go) 30%, transparent);
    @starting-style { opacity: 0; scale: .98; }
    transition: opacity .35s, scale .5s var(--apo-register-spring);
    & .lbl { font-size: 12px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apo-register-go); }
    & .chg { font-size: clamp(36px, 5.4cqi, 56px); font-weight: 800; letter-spacing: -.04em; line-height: 1; }
    & .acts { display: flex; flex-wrap: wrap; gap: 8px; }
    & .acts .apo-register-solid { display: inline-flex; align-items: center; gap: 8px; }
    & .acts kbd { color: inherit; background: transparent; border-color: color-mix(in oklch, white 35%, transparent); }
    & .note { color: var(--apo-register-mute); font-size: 13px; }
  }

  /* ── footer + toast + sheet ── */
  & .apo-register-keys { grid-area: keys; display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 8px 16px; font-size: 11.5px; color: var(--apo-register-mute); border-top: 1px solid var(--apo-register-line); background: var(--apo-register-panel);
    & span { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
  }
  & .apo-register-toast { position: absolute; left: 16px; bottom: 48px; z-index: 5; display: flex; align-items: center; gap: 14px; padding: 10px 10px 10px 14px; border-radius: 10px; color: var(--apo-register-bg); background: var(--apo-register-ink); font-size: 13px; box-shadow: 0 14px 30px -14px color-mix(in oklch, var(--apo-register-ink) 70%, transparent);
    opacity: 0; translate: 0 10px; pointer-events: none; transition: opacity .25s, translate .45s var(--apo-register-spring);
    & button { height: 28px; padding: 0 10px; border-radius: 7px; font-weight: 750; color: oklch(0.84 0.12 45); }
    & button:hover { background: color-mix(in oklch, white 10%, transparent); }
    &[data-on] { opacity: 1; translate: 0 0; pointer-events: auto; }
    &:not([data-undo]) button { display: none; }
  }
  & .apo-register-sheet { position: absolute; inset: 0; z-index: 8; display: grid; place-items: center; padding: 16px; background: color-mix(in oklch, var(--apo-register-ink) 30%, transparent); backdrop-filter: blur(2px);
    transition: opacity .25s; @starting-style { opacity: 0; }
  }
  & .apo-register-mail { width: min(400px, 100%); display: grid; gap: 12px; padding: 20px; border-radius: 14px; background: var(--apo-register-panel); box-shadow: 0 30px 60px -20px color-mix(in oklch, var(--apo-register-ink) 50%, transparent);
    transition: scale .45s var(--apo-register-spring), opacity .25s; @starting-style { scale: .94; opacity: 0; }
    & h3 { font-size: 18px; letter-spacing: -.01em; }
    & p { font-size: 13px; color: var(--apo-register-mute); }
    & label { display: grid; gap: 5px; font-size: 12px; font-weight: 650; }
    & input { height: 40px; padding: 0 12px; border-radius: 9px; border: 1px solid var(--apo-register-line2); background: var(--apo-register-bg); outline: none; font-size: 14px; }
    & input:focus-visible { border-color: var(--apo-register-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apo-register-accent) 18%, transparent); }
    & input[aria-invalid="true"] { border-color: var(--apo-register-accent); }
    & .apo-register-err { color: var(--apo-register-accent); font-weight: 600; min-height: 1.2em; }
  }
  & .apo-register-mailacts { display: flex; justify-content: flex-end; gap: 8px; }

  @supports (animation-timeline: scroll()) {
    & .apo-register-lines { animation: apo-register-edge linear both; animation-timeline: scroll(self); }
  }
}

@keyframes apo-register-pop { 0% { scale: .4; } 60% { scale: 1.25; } 100% { scale: 1; } }
@keyframes apo-register-ping { 0% { opacity: .9; scale: .35; } 100% { opacity: 0; scale: 1.15; } }
@keyframes apo-register-edge { from { box-shadow: inset 0 0 0 transparent; } 8%, to { box-shadow: inset 0 10px 10px -10px color-mix(in oklch, black 28%, transparent); } }

@container apo-register (width < 960px) {
  .apo-register .apo-register-tender { grid-template-columns: minmax(0, 1fr); grid-template-areas: "due" "rib" "meth" "pad" "list"; }
  .apo-register .apo-register-pad { grid-template-columns: repeat(6, 1fr); }
  .apo-register .apo-register-pad .wide { grid-column: span 6; }
  .apo-register .apo-register-headacts span { display: none; }
  .apo-register .apo-register-headacts kbd { display: none; }
