}
@container apo-register (width < 760px) {
  .apo-register .apo-register-app { grid-template: "head" auto "nav" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
  .apo-register .apo-register-keys { display: none; }
  .apo-register .apo-register-clock { display: none; }
  .apo-register .apo-register-brand span { display: none; }
  .apo-register .apo-register-head { padding: 8px 12px; gap: 10px; }
  .apo-register .apo-register-headacts { margin-left: auto; }
  .apo-register .apo-register-nav { grid-area: nav; display: flex; gap: 4px; padding: 6px 12px; border-bottom: 1px solid var(--apo-register-line); background: var(--apo-register-panel);
    & button { flex: 1; height: 36px; border-radius: 9px; font-weight: 700; font-size: 13.5px; color: var(--apo-register-mute); }
