  }
  .apo-register .apo-register-basket { grid-area: main; border-left: 0; }
  .apo-register[data-view="items"] .apo-register-basket, .apo-register[data-view="sale"] .apo-register-cat, .apo-register[data-view="sale"] .apo-register-tender { display: none; }
  .apo-register[data-mode="tender"][data-view="items"] .apo-register-basket { display: none; }
  .apo-register .apo-register-tools, .apo-register .apo-register-cats { padding-inline: 12px; }
  .apo-register .apo-register-grid { padding-inline: 12px; grid-template-columns: repeat(auto-fill, minmax(118px, 1fr)); }
  .apo-register .apo-register-tender { padding: 14px 12px; }
  .apo-register .apo-register-methods { grid-template-columns: 1fr 1fr 1fr; }
  .apo-register .apo-register-pad { grid-template-columns: repeat(3, 1fr); }
  .apo-register .apo-register-pad .wide { grid-column: span 3; }
  .apo-register .apo-register-toast { bottom: 12px; left: 12px; right: 12px; }
}

@media (prefers-reduced-motion: reduce) {
  .apo-register *, .apo-register *::before, .apo-register *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
  .apo-register .apo-register-proc .rings i { opacity: .5; scale: .8; }
  .apo-register .apo-register-lines { animation: none; }
}

