/* Fernhill register. All money is integer cents. Line discounts come off first, a basket
   discount is then allocated across eligible lines by largest remainder, and tax is charged
   per tax class on what is left, so the receipt always adds up to the cent. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const money = c => (c < 0 ? '−' : '') + '$' + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const IC = {
  minus: '<path d="M6 12h12"/>', plus: '<path d="M12 6v12M6 12h12"/>', x: '<path d="M7 7l10 10M17 7 7 17"/>',
  cash: '<rect x="2.5" y="6.5" width="19" height="11" rx="2"/><circle cx="12" cy="12" r="2.6"/><path d="M6 9.5v5M18 9.5v5"/>',
  card: '<rect x="2.5" y="5.5" width="19" height="13" rx="2.2"/><path d="M2.5 10h19M6.5 15h4"/>',
  gift: '<rect x="3.5" y="9" width="17" height="11" rx="1.5"/><path d="M3.5 13h17M12 9v11M12 9c-1.5-3.5-5.5-4-5.5-1.5S10 9 12 9Zm0 0c1.5-3.5 5.5-4 5.5-1.5S14 9 12 9Z"/>',
  back: '<path d="M10 6 4 12l6 6M4.5 12H20"/>', scale: '<path d="M4 20h16M6 20l1.5-9h9L18 20M12 11V6M8 6h8"/>', print: '<path d="M7 9V3.5h10V9M7 17H4.5V9.5h15V17H17"/><rect x="7" y="13.5" width="10" height="7"/>',
  mail: '<rect x="3" y="5.5" width="18" height="13" rx="2"/><path d="m3.5 7 8.5 6.5L20.5 7"/>', next: '<path d="M5 12h13M13 6l6 6-6 6"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';

const TAX = { G: 0.0825, F: 0, X: 0 };
const CATS = [['all', 'All', 30], ['bakery', 'Bakery', 70], ['produce', 'Produce', 140], ['dairy', 'Dairy', 235], ['pantry', 'Pantry', 45], ['hardware', 'Hardware', 255], ['garden', 'Garden', 120], ['counter', 'Counter', 15]];
const HUE = Object.fromEntries(CATS.map(c => [c[0], c[2]]));
// plu, name, department, cents (per lb when weighed), tax class, flags (w = weighed, n = not discountable)
const P = [
  ['1101', 'Sourdough Boule', 'bakery', 680, 'F'], ['1102', 'Seeded Rye Loaf', 'bakery', 595, 'F'], ['1103', 'Cardamom Bun', 'bakery', 375, 'F'], ['1104', 'Oat Cookies, 6', 'bakery', 450, 'F'],
  ['4011', 'Honeycrisp Apples', 'produce', 249, 'F', 'w'], ['4062', 'Lacinato Kale', 'produce', 299, 'F'], ['4087', 'Heirloom Tomatoes', 'produce', 399, 'F', 'w'], ['4225', 'Hass Avocado', 'produce', 175, 'F'],
  ['2201', 'Cultured Butter 8 oz', 'dairy', 725, 'F'], ['2202', 'Whole Milk ½ gal', 'dairy', 489, 'F'], ['2203', 'Aged Cheddar 7 oz', 'dairy', 899, 'F'], ['2204', 'Greek Yogurt, quart', 'dairy', 649, 'F'],
  ['3301', 'Wildflower Honey 12 oz', 'pantry', 1150, 'F'], ['3302', 'Stone-Ground Grits', 'pantry', 675, 'F'], ['3303', 'Cold Brew Concentrate', 'pantry', 1095, 'F'], ['3304', 'Dark Chocolate Bar', 'pantry', 425, 'G'],
  ['5501', 'Brass Hose Nozzle', 'hardware', 1899, 'G'], ['5502', 'Utility Knife', 'hardware', 1249, 'G'], ['5503', 'Leather Work Gloves', 'hardware', 2299, 'G'], ['5504', 'Beeswax Tapers, pair', 'hardware', 1400, 'G'],
  ['6601', 'Potting Mix 16 qt', 'garden', 1149, 'G'], ['6602', 'Tomato Seedling 4"', 'garden', 450, 'G'], ['6603', 'Pruning Snips', 'garden', 2699, 'G'], ['6604', 'Jute Twine 250 ft', 'garden', 699, 'G'],
  ['9901', 'Forever Stamps, 20', 'counter', 1460, 'X', 'n'], ['9902', 'Gift Card $25', 'counter', 2500, 'X', 'n'], ['9903', 'Canvas Market Bag', 'counter', 299, 'G'], ['9904', 'Firewood Bundle', 'counter', 899, 'G']
].map(([plu, name, cat, price, tax, f = '']) => ({ plu, name, cat, price, tax, w: f.includes('w'), nd: f.includes('n') }));
const BY = Object.fromEntries(P.map(p => [p.plu, p]));
const WEIGHTS = [1.36, 2.08, 0.94, 1.72, 1.15, 0.68, 1.49];
const DISC = [0, 10, 15, 20];
const BASKET = [[0, 'None'], [5, '5%'], [10, '10%'], [15, 'Staff 15%']];

let uid = 10;
const S = {
  cat: 'all', q: '', mult: 1, sel: null, bPct: 0, mode: 'sale', view: 'items', saleNo: 4188, wi: 1,
  lines: [{ id: 'l1', plu: '1101', qty: 1, pct: 0 }, { id: 'l2', plu: '4011', qty: 1, w: 1.36, pct: 0 }, { id: 'l3', plu: '2201', qty: 2, pct: 0 },
    { id: 'l4', plu: '5501', qty: 1, pct: 15 }, { id: 'l5', plu: '3304', qty: 3, pct: 0 }, { id: 'l6', plu: '9901', qty: 1, pct: 0 }],
  tenders: [], amt: 0, fresh: true, proc: null, gift: 2500, done: false
};
const hist = [];
const snap = () => JSON.stringify({ lines: S.lines, bPct: S.bPct, sel: S.sel });
function remember(label) { hist.push({ s: snap(), label }); if (hist.length > 40) hist.shift(); }

/* ── pricing ─────────────────────────────────────────────── */
function calc() {
  const rows = S.lines.map(l => {
    const p = BY[l.plu];
    const gross = p.w ? Math.round(l.w * p.price) * l.qty : p.price * l.qty;
    const ld = p.nd ? 0 : Math.round(gross * l.pct / 100);
    return { l, p, gross, ld, net1: gross - ld, bd: 0 };
  });
  const elig = rows.filter(r => !r.p.nd && r.net1 > 0);
  const base = elig.reduce((a, r) => a + r.net1, 0);
  const bd = Math.round(base * S.bPct / 100);
  if (bd && base) { // largest remainder: shares always sum to the basket discount
    const parts = elig.map(r => { const x = r.net1 * bd / base; return { r, f: Math.floor(x), rem: x - Math.floor(x) }; });
    let left = bd - parts.reduce((a, x) => a + x.f, 0);
    parts.sort((a, b) => b.rem - a.rem).forEach(x => { x.r.bd = x.f + (left-- > 0 ? 1 : 0); });
  }
  rows.forEach(r => { r.net = r.net1 - r.bd; });
  const taxBase = { G: 0, F: 0, X: 0 };
  rows.forEach(r => { taxBase[r.p.tax] += r.net; });
  const tax = Math.round(taxBase.G * TAX.G);
  const sub = rows.reduce((a, r) => a + r.gross, 0);
  const lineD = rows.reduce((a, r) => a + r.ld, 0);
  const items = S.lines.reduce((a, l) => a + l.qty, 0);
  return { rows, sub, lineD, bd, tax, taxBase: taxBase.G, total: sub - lineD - bd + tax, items };
}
const paid = () => S.tenders.reduce((a, t) => a + t.amt, 0);

/* ── focus survives re-renders: controls carry a data-k key ── */
function keep(fn) {
  const a = root.contains(document.activeElement) ? document.activeElement : null;
  const k = a && a.dataset.k;
  fn();
  if (k) { const n = root.querySelector('[data-k="' + CSS.escape(k) + '"]'); if (n && n !== document.activeElement && !n.disabled) n.focus({ preventScroll: true }); }
}

/* ── catalog ─────────────────────────────────────────────── */
function renderCats() {
  $('.apo-register-cats').innerHTML = CATS.map(([id, label, h]) =>
    `<button type="button" role="tab" data-act="cat" data-id="${id}" data-k="cat-${id}" aria-selected="${S.cat === id}" style="--hue:${h}" tabindex="${S.cat === id ? 0 : -1}">${id === 'all' ? '' : '<i></i>'}${label}</button>`).join('');
}
function visibleProducts() {
  const q = S.q.trim().toLowerCase();
  return P.filter(p => (S.cat === 'all' || p.cat === S.cat) && (!q || p.name.toLowerCase().includes(q) || p.plu.startsWith(q)));
}
function renderGrid() {
  const list = visibleProducts();
  const grid = $('.apo-register-grid');
  grid.innerHTML = list.length ? list.map(p => `<button type="button" class="apo-register-tile" data-act="add" data-plu="${p.plu}" data-k="t-${p.plu}" style="--h:${HUE[p.cat]}">
      <span class="plu">PLU ${p.plu}${p.w ? ' · scale' : ''}</span><span class="nm">${esc(p.name)}</span>
      <span class="pr apo-register-num">${money(p.price)}${p.w ? '<small>/lb</small>' : ''}</span><span class="badge apo-register-num" aria-label="in basket"></span></button>`).join('')
    : `<p class="apo-register-none">No item matches “${esc(S.q)}”. Try a PLU such as 4011.</p>`;
  badges();
}
function badges() {
  const n = {};
  S.lines.forEach(l => { n[l.plu] = (n[l.plu] || 0) + l.qty; });
  $$('.apo-register-tile').forEach(t => { const v = n[t.dataset.plu] || ''; const b = $('.badge', t); if (b.textContent !== String(v)) b.textContent = v; });
}

/* ── basket (keyed: rows persist, so only new lines play their entry) ── */
function lineInner(r) {
  const { l, p } = r, open = S.sel === l.id, locked = S.mode === 'tender';
  const qtyTxt = p.w ? (l.w.toFixed(2) + ' lb') : l.qty;
  const detail = p.w ? `${l.w.toFixed(2)} lb @ ${money(p.price)}/lb` : (l.qty > 1 ? `${l.qty} @ ${money(p.price)}` : `PLU ${p.plu}`);
  const off = r.ld + r.bd;
  const offTxt = off ? `<span class="off">−${money(off).slice(1)}${r.ld ? ' · ' + l.pct + '% line' : ''}${r.bd ? ' · basket' : ''}</span>` : (p.nd ? '<span>no discounts</span>' : '');
  return `<button type="button" class="row" data-act="sel" data-id="${l.id}" data-k="row-${l.id}" aria-expanded="${open && !locked}" ${locked ? 'disabled title="Payment in progress"' : ''}>
      <span class="q apo-register-num" ${p.w ? 'title="Weighed on the scale"' : ''}>${p.w ? svg('scale') : l.qty + '×'}</span><span class="n">${esc(p.name)}</span>
      <span class="a apo-register-num">${off ? '<s>' + money(r.gross) + '</s>' : ''}${money(r.gross - off)}</span>
      <span class="d apo-register-num"><span>${detail}${p.tax === 'G' ? ' · T' : ''}</span>${offTxt}</span></button>
    <div class="edit"><div>${open && !locked ? `
      ${p.w ? `<span class="apo-register-num" style="font-size:12px;color:var(--apo-register-mute)">Weighed ${qtyTxt}</span>` : `<span class="apo-register-step" role="group" aria-label="Quantity">
        <button type="button" data-act="qty" data-d="-1" data-id="${l.id}" data-k="qm-${l.id}" aria-label="${l.qty === 1 ? 'Remove line' : 'One fewer'}">${svg('minus')}</button><b class="apo-register-num">${l.qty}</b>
        <button type="button" data-act="qty" data-d="1" data-id="${l.id}" data-k="qp-${l.id}" aria-label="One more">${svg('plus')}</button></span>`}
      <span class="apo-register-chips" role="radiogroup" aria-label="Line discount">${DISC.map(d => `<button type="button" role="radio" data-act="ldisc" data-pct="${d}" data-id="${l.id}" data-k="ld-${l.id}-${d}" aria-checked="${l.pct === d}" ${p.nd ? 'disabled title="Stamps and gift cards cannot be discounted"' : ''}>${d ? d + '%' : 'No disc.'}</button>`).join('')}</span>
      <button type="button" class="apo-register-x" data-act="rm" data-id="${l.id}" data-k="rm-${l.id}" aria-label="Remove ${esc(p.name)}" title="Remove line (Del)">${svg('x')}</button>` : ''}</div></div>`;
}
function renderLines(c) {
  const ol = $('.apo-register-lines');
  const want = new Set(S.lines.map(l => l.id));
  $$(':scope > li', ol).forEach(li => { if (!want.has(li.dataset.id) && !li.dataset.out) leave(li); });
  let prev = null;
  c.rows.forEach(r => {
    let li = ol.querySelector(':scope > li[data-id="' + r.l.id + '"]:not([data-out])');
    if (!li) { li = document.createElement('li'); li.className = 'apo-register-line'; li.dataset.id = r.l.id; }
    const html = lineInner(r);
    if (li.__h !== html) { li.innerHTML = html; li.__h = html; }
    const after = prev ? prev.nextElementSibling : ol.firstElementChild;
    if (after !== li) ol.insertBefore(li, after);
    prev = li;
  });
}
function leave(li) {
  li.dataset.out = '1';
  const h = li.offsetHeight;
  if (RM.matches || !li.animate) { li.remove(); return; }
  li.style.overflow = 'hidden';
  li.animate([{ opacity: 1, height: h + 'px', transform: 'none' }, { opacity: 0, height: '0px', transform: 'translateX(-24px)' }],
    { duration: 280, easing: 'cubic-bezier(.4,0,.2,1)' }).finished.then(() => li.remove(), () => li.remove());
}
function renderTotals(c) {
  const t = $('.apo-register-totals');
  t.innerHTML = `<dt>Subtotal · ${c.items} item${c.items === 1 ? '' : 's'}</dt><dd>${money(c.sub)}</dd>
    ${c.lineD ? `<dt>Line discounts</dt><dd class="off">−${money(c.lineD).slice(1)}</dd>` : ''}
    ${c.bd ? `<dt>Basket ${S.bPct}% off</dt><dd class="off">−${money(c.bd).slice(1)}</dd>` : ''}
    <dt>Tax 8.25% on ${money(c.taxBase)}</dt><dd>${money(c.tax)}</dd>
    <dt class="big">Total</dt><dd class="big" data-total>${money(c.total)}</dd>`;
  $('[data-count]').textContent = S.lines.length ? `${S.lines.length} line${S.lines.length === 1 ? '' : 's'}` : '';
  $('.apo-register-disc').innerHTML = '<span>Basket discount</span>' + BASKET.map(([p, lab]) =>
    `<button type="button" role="radio" data-act="bdisc" data-pct="${p}" data-k="bd-${p}" aria-checked="${S.bPct === p}">${lab}</button>`).join('');
  const pay = $('.apo-register-pay');
  pay.disabled = !S.lines.length;
  pay.title = S.lines.length ? 'Take payment (P)' : 'Add an item before taking payment';
  tween($('[data-paytotal]'), c.total, 'pay');
}
const TW = {};
function tween(el, to, key = 'pay') {
  const from = TW[key] == null ? to : TW[key];
  TW[key] = to; el.__v = to;
  if (from === to || RM.matches) { el.textContent = money(to); return; }
  const t0 = performance.now(), d = 420;
  const step = now => {
    if (!root.isConnected) return;
    const k = Math.min(1, (now - t0) / d), e = 1 - Math.pow(1 - k, 3);
    el.textContent = money(Math.round(from + (to - from) * e));
    if (k < 1 && el.__v === to) requestAnimationFrame(step);
  };
  requestAnimationFrame(step);
}

/* ── tender ──────────────────────────────────────────────── */
function cashSuggestions(due) {
  const out = new Set([due]);
  [100, 500, 1000, 2000, 5000, 10000].forEach(n => { const v = Math.ceil(due / n) * n; if (v > due) out.add(v); });
  return [...out].sort((a, b) => a - b).slice(0, 5);
}
const KCOL = { cash: 'var(--apo-register-go)', card: 'var(--apo-register-ink)', gift: 'oklch(0.72 0.13 75)' };
const KLAB = { cash: 'Cash', card: 'Card', gift: 'Gift card' };
function syncBar(bar, items) {
  const want = new Set(items.map(x => x.k));
  $$(':scope > span', bar).forEach(s => {
    if (!want.has(s.dataset.key) && !s.dataset.out) { s.dataset.out = '1'; s.style.setProperty('--g', 0); setTimeout(() => s.remove(), RM.matches ? 0 : 700); }
  });
  let prev = null;
  items.forEach(x => {
    let s = bar.querySelector(':scope > span[data-key="' + x.k + '"]:not([data-out])');
    if (!s) { s = document.createElement('span'); s.dataset.key = x.k; s.className = x.cls; }
    if (s.style.getPropertyValue('--g') !== String(x.g)) s.style.setProperty('--g', x.g);
    const after = prev ? prev.nextElementSibling : bar.firstElementChild;
    if (after !== s) bar.insertBefore(s, after);
    prev = s;
  });
}
function renderTender(c) {
  const box = $('.apo-register-tender');
  if (S.mode !== 'tender') { if (box.firstChild) box.innerHTML = ''; return; }
  if (!box.firstChild) box.innerHTML = '<div class="apo-register-due"></div><div class="apo-register-ribbon"><div class="apo-register-bar" role="img"></div><div class="apo-register-legend"></div></div><div class="apo-register-body"></div>';
  const due = Math.max(0, c.total - paid());
  if (S.fresh) S.amt = due;
  const change = S.tenders.reduce((a, t) => a + (t.change || 0), 0);
  const bar = $('.apo-register-bar', box);
  syncBar(bar, S.tenders.map(t => ({ k: t.id, cls: t.kind, g: t.amt })).concat([{ k: 'rest', cls: 'rest', g: due }]));
  bar.setAttribute('aria-label', money(paid()) + ' paid of ' + money(c.total));
  $('.apo-register-legend', box).innerHTML = S.tenders.map(t => `<span><i style="background:${KCOL[t.kind]}"></i>${KLAB[t.kind]} ${money(t.amt)}</span>`).join('') +
    (due ? `<span><i style="background:color-mix(in oklch, var(--apo-register-accent) 30%, transparent)"></i>Remaining ${money(due)}</span>` : '');
  const dueBox = $('.apo-register-due', box);
  dueBox.innerHTML = `<div><div class="lbl">${S.done ? 'Paid in full' : 'Amount due'}</div><div class="amt apo-register-num" data-due></div></div>
      <div class="sub">of ${money(c.total)} · ${S.tenders.length ? S.tenders.length + ' tender' + (S.tenders.length > 1 ? 's' : '') + ' applied' : 'split across any tenders'}</div>
      ${S.done ? '' : `<button type="button" class="apo-register-ghost back" data-act="back" data-k="back" ${S.tenders.length || S.proc ? 'disabled title="Void the applied tenders before editing the sale"' : 'title="Back to the basket (Esc)"'}>${svg('back')}Edit sale <kbd>Esc</kbd></button>`}`;
  tween($('[data-due]', dueBox), due, 'due');
  const tl = S.tenders.map(t => `<li><span>${svg(t.kind)}</span><span class="t"><b>${KLAB[t.kind]}${t.meta ? ' · ' + t.meta : ''}</b><small>${t.kind === 'cash' ? 'Tendered ' + money(t.given) + (t.change ? ' · change ' + money(t.change) : '') : t.auth}</small></span>
      <span class="v apo-register-num">${money(t.amt)}</span>${S.done ? '<span></span>' : `<button type="button" class="apo-register-x" data-act="untender" data-tid="${t.id}" data-k="ut-${t.id}" aria-label="Void ${KLAB[t.kind]} tender" title="Void this tender">${svg('x')}</button>`}</li>`).join('');
  const lock = S.proc ? 'disabled title="Waiting for the card reader"' : '';
  const sugg = cashSuggestions(due).map(v => `<button type="button" class="apo-register-num" data-act="cash" data-v="${v}" data-k="cs-${v}">${v === due ? 'Exact ' : ''}${money(v)}</button>`).join('');
  $('.apo-register-body', box).innerHTML = S.done ? `<div class="apo-register-done" role="status">
      <span class="lbl">Sale complete · ${money(c.total)}</span>
      <span class="chg apo-register-num">${change ? 'Change ' + money(change) : 'No change due'}</span>
      <p class="note">${S.tenders.length} tender${S.tenders.length === 1 ? '' : 's'} · ${c.items} items · sale #2-0${S.saleNo}${S.printed ? ' · receipt printed' + (S.printed > 1 ? ' ×' + S.printed : '') : ''}${S.mailed ? ' · emailed to ' + esc(S.mailed) : ''}</p>
      <div class="acts"><button type="button" class="apo-register-ghost" data-act="print" data-k="print">${svg('print')}${S.printed ? 'Reprint receipt' : 'Print receipt'}</button>
      <button type="button" class="apo-register-ghost" data-act="mail" data-k="mail-open">${svg('mail')}Email receipt</button>
      <button type="button" class="apo-register-solid" data-act="new" data-k="new">New sale <kbd>N</kbd></button></div></div>
      <ul class="apo-register-tlist" aria-label="Tenders applied">${tl}</ul>`
    : `<div class="apo-register-meth">
      <div class="apo-register-amtrow"><span class="lbl">Amount to apply</span><output class="apo-register-num" ${S.fresh ? 'data-fresh' : ''} aria-live="polite">${money(S.amt)}</output>
        <button type="button" class="apo-register-ghost" data-act="half" data-k="half" ${S.proc ? lock : due < 2 ? 'disabled title="Too little left to split"' : ''}>Half</button>
        <button type="button" class="apo-register-ghost" data-act="rest" data-k="rest" ${S.proc ? lock : S.fresh ? 'disabled title="Already set to the remaining balance"' : ''}>Remaining</button></div>
      ${S.proc ? `<div class="apo-register-proc" role="status"><span class="rings"><i style="--i:0"></i><i style="--i:1"></i><i style="--i:2"></i></span><span><b>Tap, insert or swipe · ${money(S.proc.amt)}</b><small>Waiting for the card reader…</small></span><button type="button" data-act="cancelcard" data-k="cancelcard">Cancel</button></div>` : `
      <div class="apo-register-methods">
        <button type="button" class="apo-register-method" data-act="tcash" data-k="tcash" ${S.amt <= 0 ? 'disabled title="Enter an amount first"' : ''}>${svg('cash')}<b>Cash <kbd>C</kbd></b><small>${S.amt > due ? 'Change ' + money(S.amt - due) : 'Apply ' + money(S.amt)}</small></button>
        <button type="button" class="apo-register-method" data-act="tcard" data-k="tcard" ${S.amt <= 0 || S.amt > due ? `disabled title="${S.amt > due ? 'A card cannot be charged more than the balance due' : 'Enter an amount first'}"` : ''}>${svg('card')}<b>Card <kbd>K</kbd></b><small>Charge ${money(Math.min(S.amt, due))}</small></button>
        <button type="button" class="apo-register-method" data-act="tgift" data-k="tgift" ${S.gift <= 0 || S.amt <= 0 ? `disabled title="${S.gift <= 0 ? 'Gift card ••8821 has no balance left' : 'Enter an amount first'}"` : ''}>${svg('gift')}<b>Gift card <kbd>G</kbd></b><small>••8821 · ${money(S.gift)} left</small></button>
      </div>`}
      <div class="apo-register-quick"><span>Cash received</span>${S.proc ? '<span>Card in progress…</span>' : sugg}</div></div>
    <div class="apo-register-pad" role="group" aria-label="Amount keypad">${['7', '8', '9', '4', '5', '6', '1', '2', '3', '00', '0', '⌫'].map(k => `<button type="button" data-act="key" data-key="${k}" data-k="key-${k}" aria-label="${k === '⌫' ? 'Delete digit' : k}" ${lock}>${k}</button>`).join('')}<button type="button" class="wide" data-act="key" data-key="C" data-k="key-C" ${S.proc ? lock : S.amt === 0 && !S.fresh ? 'disabled title="Amount is already zero"' : ''}>Clear amount</button></div>
    <ul class="apo-register-tlist" aria-label="Tenders applied">${tl}</ul>`;
}
function applyTender(kind, amt, extra = {}) {
  const c = calc(), due = c.total - paid();
  const use = Math.min(amt, due);
  if (use <= 0) return;
  const t = Object.assign({ id: 't' + (++uid), kind, amt: use }, extra);
  if (kind === 'cash') { t.given = amt; t.change = Math.max(0, amt - due); }
  S.tenders.push(t);
  S.fresh = true;
  if (paid() >= c.total) { S.done = true; toast(kind === 'cash' && t.change ? 'Drawer open · give ' + money(t.change) + ' change' : 'Paid in full'); }
  render();
}

/* ── render ──────────────────────────────────────────────── */
function renderNav(c) {
  const v = S.mode === 'tender' ? [['items', 'Pay'], ['sale', 'Sale · ' + c.items]] : [['items', 'Items'], ['sale', 'Sale · ' + c.items]];
  $('.apo-register-nav').innerHTML = v.map(([id, lab]) => `<button type="button" role="tab" data-act="view" data-id="${id}" data-k="nav-${id}" aria-selected="${S.view === id}">${lab}</button>`).join('');
}
function render() {
  keep(() => {
    const c = calc();
    root.dataset.mode = S.mode; root.dataset.view = S.view;
    renderLines(c); renderTotals(c); renderTender(c); renderNav(c); badges();
    $('[data-saleno]').textContent = '#2-0' + S.saleNo;
    const u = $('[data-act="undo"]');
    u.disabled = !hist.length || S.mode === 'tender';
    u.title = S.mode === 'tender' ? 'Leave payment to undo basket changes' : hist.length ? 'Undo: ' + hist[hist.length - 1].label + ' (' + MOD + 'Z)' : 'Nothing to undo yet';
    const vd = $('[data-act="void"]');
    vd.disabled = !S.lines.length || S.mode === 'tender';
    vd.title = S.done ? 'Sale is complete; start a new sale instead' : S.mode === 'tender' ? 'Leave payment before voiding the sale' : S.lines.length ? 'Clear every line (undoable)' : 'Basket is already empty';
    const m = $('.apo-register-mult');
    m.textContent = S.mult > 1 ? S.mult + ' ×' : '';
  });
}

let tt = 0;
function toast(msg, undo) {
  const t = $('.apo-register-toast');
  $('[data-msg]', t).textContent = msg;
  t.toggleAttribute('data-undo', !!undo);
  t.setAttribute('data-on', '');
  clearTimeout(tt);
  tt = setTimeout(() => t.removeAttribute('data-on'), 3200);
}

/* ── actions ─────────────────────────────────────────────── */
function add(plu) {
  const p = BY[plu];
  if (S.mode === 'tender') return;
  remember('add ' + p.name);
  const q = S.mult; S.mult = 1;
  let l;
  if (p.w) { l = { id: 'l' + (++uid), plu, qty: 1, w: WEIGHTS[S.wi++ % WEIGHTS.length], pct: 0 }; S.lines.push(l); toast('Scale read ' + l.w.toFixed(2) + ' lb · ' + p.name); }
  else {
    l = S.lines.find(x => x.plu === plu && !x.pct);
    if (l) l.qty += q; else { l = { id: 'l' + (++uid), plu, qty: q, pct: 0 }; S.lines.push(l); }
  }
  S.sel = l.id;
  render();
  const tile = root.querySelector('.apo-register-tile[data-plu="' + plu + '"]');
  if (tile) { tile.removeAttribute('data-pop'); void tile.offsetWidth; tile.setAttribute('data-pop', ''); }
  const li = root.querySelector('.apo-register-line[data-id="' + l.id + '"]');
  if (li) li.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
}
function setQty(id, d) {
  const l = S.lines.find(x => x.id === id); if (!l) return;
  if (l.qty + d <= 0) return removeLine(id);
  remember((d > 0 ? 'add one ' : 'remove one ') + BY[l.plu].name);
  l.qty += d; render();
}
function removeLine(id) {
  const i = S.lines.findIndex(x => x.id === id); if (i < 0) return;
  remember('remove ' + BY[S.lines[i].plu].name);
  const name = BY[S.lines[i].plu].name;
  S.lines.splice(i, 1);
  S.sel = S.lines[Math.min(i, S.lines.length - 1)] ? S.lines[Math.min(i, S.lines.length - 1)].id : null;
  render(); toast('Removed ' + name, true);
}
function undo() {
  const h = hist.pop(); if (!h || S.mode === 'tender') return;
  const o = JSON.parse(h.s); S.lines = o.lines; S.bPct = o.bPct; S.sel = o.sel;
  render(); toast('Undid ' + h.label);
}
function enterTender() {
  if (!S.lines.length) return;
  S.mode = 'tender'; S.fresh = true; S.view = 'items'; S.sel = null; render();
  const f = $('[data-act="tcash"]'); if (f) f.focus({ preventScroll: true });
}
function leaveTender() {
  if (S.tenders.length || S.proc) return;
  S.mode = 'sale'; render();
}
function newSale() {
  S.lines = []; S.tenders = []; S.done = false; S.mode = 'sale'; S.bPct = 0; S.sel = null; S.saleNo++; S.printed = false; S.mailed = ''; S.fresh = true; S.view = 'items';
  hist.length = 0; render(); toast('Sale #2-0' + S.saleNo + ' started');
  $('.apo-register-search input').focus({ preventScroll: true });
}
function key(k) {
  if (S.fresh) { S.amt = 0; S.fresh = false; }
  if (k === 'C') { S.amt = 0; }
  else if (k === '⌫') S.amt = Math.floor(S.amt / 10);
  else if (k === '00') S.amt = Math.min(9999999, S.amt * 100);
  else S.amt = Math.min(9999999, S.amt * 10 + Number(k));
  render();
}
function chargeCard() {
  const due = calc().total - paid(), amt = Math.min(S.amt, due);
  if (amt <= 0) return;
  S.proc = { amt, t: setTimeout(() => {
    if (!root.isConnected || !S.proc) return;
    const auth = 'Visa ••4417 · auth ' + (0x5A3F1 + uid * 7919).toString(36).toUpperCase().slice(-6);
    S.proc = null; applyTender('card', amt, { auth, meta: '••4417' });
  }, 1300) };
  render();
}

root.addEventListener('click', e => {
  const b = e.target.closest('[data-act]'); if (!b || !root.contains(b) || b.disabled) return;
  const a = b.dataset.act, id = b.dataset.id;
  if (a === 'add') add(b.dataset.plu);
  else if (a === 'cat') { S.cat = id; keep(() => { renderCats(); renderGrid(); }); }
  else if (a === 'sel') { S.sel = S.sel === id ? null : id; render(); }
  else if (a === 'qty') setQty(id, +b.dataset.d);
  else if (a === 'rm') removeLine(id);
  else if (a === 'ldisc') { const l = S.lines.find(x => x.id === id); if (l && l.pct !== +b.dataset.pct) { remember('line discount'); l.pct = +b.dataset.pct; render(); } }
  else if (a === 'bdisc') { if (S.bPct !== +b.dataset.pct) { remember('basket discount'); S.bPct = +b.dataset.pct; render(); } }
  else if (a === 'pay') enterTender();
  else if (a === 'back') leaveTender();
  else if (a === 'undo' || a === 'toast-undo') { undo(); if (a === 'toast-undo') $('.apo-register-toast').removeAttribute('data-on'); }
  else if (a === 'void') { if (S.lines.length) { remember('void sale'); S.lines = []; S.sel = null; S.bPct = 0; render(); toast('Sale voided', true); } }
  else if (a === 'key') key(b.dataset.key);
  else if (a === 'half') { const due = calc().total - paid(); S.amt = Math.ceil(due / 2); S.fresh = false; render(); }
  else if (a === 'rest') { S.fresh = true; render(); }
  else if (a === 'cash') { S.amt = +b.dataset.v; applyTender('cash', +b.dataset.v); }
  else if (a === 'tcash') applyTender('cash', S.amt);
  else if (a === 'tcard') chargeCard();
  else if (a === 'cancelcard') { if (S.proc) { clearTimeout(S.proc.t); S.proc = null; render(); toast('Card payment cancelled'); } }
  else if (a === 'tgift') { const use = Math.min(S.gift, S.amt, calc().total - paid()); S.gift -= use; applyTender('gift', use, { auth: 'Balance left ' + money(S.gift), meta: '••8821' }); }
  else if (a === 'untender') { const i = S.tenders.findIndex(t => t.id === b.dataset.tid); if (i > -1) { const t = S.tenders.splice(i, 1)[0]; if (t.kind === 'gift') S.gift += t.amt; S.fresh = true; render(); toast('Voided ' + t.kind + ' tender ' + money(t.amt)); } }
  else if (a === 'print') { S.printed = (S.printed || 0) + 1; render(); toast(S.printed > 1 ? 'Receipt reprinted (copy ' + S.printed + ')' : 'Receipt sent to printer'); }
  else if (a === 'mail') openMail();
  else if (a === 'mail-cancel') closeMail();
  else if (a === 'new') newSale();
  else if (a === 'view') { S.view = id; render(); }
});

/* email sheet */
function openMail() {
  const sh = $('.apo-register-sheet');
  $('[data-mailsale]', sh).textContent = 'sale #2-0' + S.saleNo;
  $('[data-err]', sh).textContent = '';
  sh.hidden = false;
  const i = $('input', sh); i.removeAttribute('aria-invalid'); i.focus({ preventScroll: true });
}
function closeMail() { $('.apo-register-sheet').hidden = true; const n = $('[data-act="mail"]'); if (n) n.focus({ preventScroll: true }); }
$('.apo-register-mail').addEventListener('submit', e => {
  e.preventDefault();
  const i = $('.apo-register-mail input'), v = i.value.trim();
  if (!/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(v)) { i.setAttribute('aria-invalid', 'true'); $('[data-err]').textContent = v ? 'That address is missing part of the domain.' : 'Enter the customer’s email address.'; i.focus(); return; }
  S.mailed = v; i.value = ''; closeMail(); render(); toast('Receipt emailed to ' + v);
});
$('.apo-register-sheet').addEventListener('click', e => { if (e.target === e.currentTarget) closeMail(); });

/* search */
const search = $('.apo-register-search input');
search.addEventListener('input', () => { S.q = search.value; renderGrid(); });
search.addEventListener('keydown', e => {
  if (e.key === 'Enter') { const p = visibleProducts()[0]; if (p) { add(p.plu); search.select(); } e.preventDefault(); }
  else if (e.key === 'Escape') { if (search.value) { search.value = ''; S.q = ''; renderGrid(); } else search.blur(); e.stopPropagation(); }
  else if (e.key === 'ArrowDown') { const t = $('.apo-register-tile'); if (t) { t.focus(); e.preventDefault(); } }
});

/* keyboard */
function gridMove(el, k) {
  const tiles = $$('.apo-register-tile'), i = tiles.indexOf(el);
  const cols = getComputedStyle($('.apo-register-grid')).gridTemplateColumns.split(' ').length;
  const n = { ArrowRight: i + 1, ArrowLeft: i - 1, ArrowDown: i + cols, ArrowUp: i - cols, Home: 0, End: tiles.length - 1 }[k];
  if (n == null) return false;
  if (n < 0 && k === 'ArrowUp') { search.focus(); return true; }
  const t = tiles[Math.max(0, Math.min(tiles.length - 1, n))]; if (t) t.focus();
  return true;
}
root.addEventListener('keydown', e => {
  const tag = e.target.tagName, typing = tag === 'INPUT';
  const mod = e.metaKey || e.ctrlKey;
  if (!$('.apo-register-sheet').hidden) { if (e.key === 'Escape') { closeMail(); e.preventDefault(); } return; }
  if (mod && e.key.toLowerCase() === 'z') { if (!typing) { undo(); e.preventDefault(); } return; }
  if (typing || mod || e.altKey) return;
  if (e.target.classList.contains('apo-register-tile') && gridMove(e.target, e.key)) { e.preventDefault(); return; }
  if (e.target.getAttribute('role') === 'tab' && (e.key === 'ArrowRight' || e.key === 'ArrowLeft') && e.target.closest('.apo-register-cats')) {
    const tabs = $$('.apo-register-cats [role=tab]'), i = tabs.indexOf(e.target), n = tabs[(i + (e.key === 'ArrowRight' ? 1 : -1) + tabs.length) % tabs.length];
    n.click(); const f = $('.apo-register-cats [aria-selected="true"]'); if (f) f.focus(); e.preventDefault(); return;
  }
  const k = e.key;
  if (S.mode === 'tender') {
    if (/^[0-9]$/.test(k) && !S.done) { key(k); e.preventDefault(); }
    else if (k === 'Backspace' && !S.done) { key('⌫'); e.preventDefault(); }
    else if (k === 'Escape') { if (S.proc) { clearTimeout(S.proc.t); S.proc = null; render(); } else leaveTender(); e.preventDefault(); }
    else if ((k === 'n' || k === 'N') && S.done) { newSale(); e.preventDefault(); }
    else if (!S.done && !S.proc && /^[ckg]$/i.test(k)) { const b = $('[data-act="t' + { c: 'cash', k: 'card', g: 'gift' }[k.toLowerCase()] + '"]'); if (b && !b.disabled) b.click(); e.preventDefault(); }
    return;
  }
  if (k === '/') { search.focus(); search.select(); e.preventDefault(); }
  else if (/^[2-9]$/.test(k)) { S.mult = S.mult === Number(k) ? 1 : Number(k); render(); e.preventDefault(); }
  else if (k === 'ArrowDown' || k === 'ArrowUp') {
    if (!S.lines.length) return;
    const i = S.lines.findIndex(l => l.id === S.sel);
    const n = i < 0 ? (k === 'ArrowDown' ? 0 : S.lines.length - 1) : Math.max(0, Math.min(S.lines.length - 1, i + (k === 'ArrowDown' ? 1 : -1)));
    S.sel = S.lines[n].id; render();
    const r = root.querySelector('[data-k="row-' + S.sel + '"]'); if (r) { r.focus({ preventScroll: true }); r.scrollIntoView({ block: 'nearest' }); }
    e.preventDefault();
  }
  else if ((k === '+' || k === '=') && S.sel) { setQty(S.sel, 1); e.preventDefault(); }
  else if ((k === '-' || k === '_') && S.sel) { setQty(S.sel, -1); e.preventDefault(); }
  else if ((k === 'Delete' || k === 'Backspace') && S.sel) { removeLine(S.sel); e.preventDefault(); }
  else if ((k === 'd' || k === 'D') && S.sel) {
    const l = S.lines.find(x => x.id === S.sel);
    if (l && !BY[l.plu].nd) { remember('line discount'); l.pct = DISC[(DISC.indexOf(l.pct) + 1) % DISC.length]; render(); toast(l.pct ? l.pct + '% off ' + BY[l.plu].name : 'Line discount removed'); }
    e.preventDefault();
  }
  else if (k === 'p' || k === 'P' || k === 'F12') { enterTender(); e.preventDefault(); }
  else if (k === 'Escape') { if (S.mult > 1) { S.mult = 1; render(); } else if (S.sel) { S.sel = null; render(); } }
});

/* clock */
const clock = $('[data-clock]');
const tick = () => { clock.textContent = new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }); };
tick();
const iv = setInterval(() => { if (!root.isConnected) { clearInterval(iv); return; } tick(); }, 20000);

renderCats(); renderGrid(); render();

