  --apo-scan-accent: oklch(0.66 0.22 27);
  --apo-scan-ok: oklch(0.8 0.14 152);
  --apo-scan-warn: oklch(0.84 0.14 82);
  --apo-scan-paper: oklch(0.97 0.006 85);
  --apo-scan-g: color-mix(in oklch, var(--apo-scan-accent) 72%, black);
  --apo-scan-r: color-mix(in oklch, var(--apo-scan-ok) 52%, black);
  --apo-scan-panel: color-mix(in oklch, var(--apo-scan-bg), var(--apo-scan-ink) 5%);
  --apo-scan-card: color-mix(in oklch, var(--apo-scan-bg), var(--apo-scan-ink) 8%);
  --apo-scan-line: color-mix(in oklch, var(--apo-scan-ink) 10%, transparent);
  --apo-scan-line2: color-mix(in oklch, var(--apo-scan-ink) 20%, transparent);
  --apo-scan-mute: color-mix(in oklch, var(--apo-scan-ink) 58%, var(--apo-scan-bg));
  --apo-scan-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --apo-scan-ease: cubic-bezier(.2, .8, .2, 1);
  --apo-scan-spring: linear(0, .09 4%, .32 10%, .65 17%, .9 25%, 1.03 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  position: relative; width: 100%; height: var(--apo-scan-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apo-scan;
