    & .step { display: inline-flex; align-items: center; border: 1px solid var(--apo-scan-line2); border-radius: 9px; }
    & .step button { width: 34px; height: 34px; display: grid; place-items: center; }
    & .step svg { width: 15px; height: 15px; stroke-width: 2.2; }
    & .step b { min-width: 28px; text-align: center; color: var(--apo-scan-ink); }
    & .apo-scan-btn { margin-left: auto; }
  }
  & .apo-scan-blist { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px;
    & li { display: grid; grid-template-columns: 1fr auto auto; gap: 10px; align-items: center; padding: 9px 10px; border-radius: 9px; background: var(--apo-scan-bg); font-size: 13px; }
    & small { display: block; font: 500 10.5px var(--apo-scan-mono); color: var(--apo-scan-mute); }
  }
  & .apo-scan-toast { position: absolute; left: 50%; bottom: 48px; z-index: 9; display: flex; align-items: center; gap: 14px; padding: 10px 10px 10px 14px; border-radius: 10px; color: var(--apo-scan-bg); background: var(--apo-scan-ink); font-size: 13px; font-weight: 550;
    opacity: 0; translate: -50% 10px; pointer-events: none; transition: opacity .25s, translate .45s var(--apo-scan-spring); white-space: nowrap; max-width: calc(100% - 24px);
    & span { overflow: hidden; text-overflow: ellipsis; }
    & button { height: 28px; padding: 0 10px; border-radius: 7px; font-weight: 750; color: var(--apo-scan-accent); }
    &[data-on] { opacity: 1; translate: -50% 0; pointer-events: auto; }
    &:not([data-undo]) button { display: none; }
  }

  @supports (animation-timeline: view()) {
    & .apo-scan-ritem { animation: apo-scan-fade linear both; animation-timeline: view(); animation-range: entry 0% entry 60%; }
  }
}

@keyframes apo-scan-bar { from { opacity: 0; transform: scaleY(.2); } to { opacity: 1; transform: none; } }
@keyframes apo-scan-bump { 0% { scale: 1; } 40% { scale: 1.35; } 100% { scale: 1; } }
@keyframes apo-scan-in { from { opacity: 0; translate: 0 6px; } }
@keyframes apo-scan-grow { from { transform: scaleX(0); } }
@keyframes apo-scan-rise { from { transform: scaleY(0); } }
@keyframes apo-scan-draw { to { stroke-dashoffset: 0; } }
@keyframes apo-scan-fade { from { opacity: 0; transform: translateY(8px); } }

@container apo-scan (width < 960px) {
  .apo-scan .apo-scan-app { grid-template: "head head" auto "nav nav" auto "left item" minmax(0, 1fr) "keys keys" auto / clamp(280px, 40cqi, 340px) minmax(0, 1fr); }
  .apo-scan .apo-scan-nav { grid-area: nav; display: flex; gap: 4px; padding: 6px 12px; border-bottom: 1px solid var(--apo-scan-line);
    & button { flex: 0 1 auto; height: 30px; padding: 0 14px; border-radius: 8px; font-weight: 700; font-size: 12.5px; color: var(--apo-scan-mute); }
    & button[aria-selected="true"] { color: var(--apo-scan-bg); background: var(--apo-scan-ink); }
    & button[data-id="item"] { display: none; }
  }
  .apo-scan .apo-scan-scanner, .apo-scan .apo-scan-recent { grid-area: left; border-left: 0; border-right: 1px solid var(--apo-scan-line); }
  .apo-scan[data-view="recent"] .apo-scan-scanner, .apo-scan:not([data-view="recent"]) .apo-scan-recent { display: none; }
}
@container apo-scan (width < 760px) {
  .apo-scan .apo-scan-app { grid-template: "head" auto "nav" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
  .apo-scan .apo-scan-keys { display: none; }
  .apo-scan .apo-scan-brand span { display: none; }
  .apo-scan .apo-scan-nav {
    & button { flex: 1; height: 34px; }
    & button[data-id="item"] { display: block; }
  }
  .apo-scan .apo-scan-scanner, .apo-scan .apo-scan-item, .apo-scan .apo-scan-recent { grid-area: main; border: 0; }
  .apo-scan .apo-scan-recent { display: grid; }
  .apo-scan[data-view="scan"] .apo-scan-item, .apo-scan[data-view="scan"] .apo-scan-recent,
  .apo-scan[data-view="item"] .apo-scan-scanner, .apo-scan[data-view="item"] .apo-scan-recent,
  .apo-scan[data-view="recent"] .apo-scan-scanner, .apo-scan[data-view="recent"] .apo-scan-item { display: none; }
  .apo-scan .apo-scan-item { padding: 14px 14px 18px; }
  .apo-scan .apo-scan-top { grid-template-columns: 1fr; }
  .apo-scan .apo-scan-top .price { grid-row: auto; grid-column: 1; text-align: left; }
  .apo-scan .apo-scan-stock .r { grid-template-columns: minmax(90px, 34%) minmax(0, 1fr) 3.5em; }
}

@media (prefers-reduced-motion: reduce) {
  .apo-scan *, .apo-scan *::before, .apo-scan *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-delay: 0s !important; }
  .apo-scan .apo-scan-ritem { animation: none; }
  .apo-scan .apo-scan-hist .step { stroke-dashoffset: 0; }
}

