/* Larkspur item lookup. The barcode is genuine EAN-13: the leading digit picks an L/G parity
   pattern for the left six digits, the right six use R codes, and 95 modules sit between
   101 / 01010 / 101 guards. In-store items use the GS1 restricted-circulation 2xx prefix. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const money = c => '$' + (c / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const IC = {
  cart: '<path d="M4 5h2l2 10h10l2-7H7.2"/><circle cx="9.5" cy="19" r="1.3"/><circle cx="16.5" cy="19" r="1.3"/>',
  tag: '<path d="M3.5 12.5V4.5h8l9 9-8 8-9-9Z"/><circle cx="8" cy="9" r="1.4"/>', hold: '<path d="M7 11V7a5 5 0 0 1 10 0v4"/><rect x="4.5" y="11" width="15" height="9.5" rx="2"/>',
  x: '<path d="M7 7l10 10M17 7 7 17"/>', minus: '<path d="M6 12h12"/>', plus: '<path d="M12 6v12M6 12h12"/>', print: '<path d="M7 9V3.5h10V9M7 17H4.5V9.5h15V17H17"/><rect x="7" y="13.5" width="10" height="7"/>',
  q: '<path d="M4 7V4.5h3M17 4.5h3V7M20 17v2.5h-3M7 19.5H4V17"/><path d="M9.5 9.5a2.5 2.5 0 1 1 3.4 2.3c-.6.3-.9.8-.9 1.4v.3M12 16.2v.1"/>', send: '<path d="M4 12 20 4l-6 16-3-7-7-1Z"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';

/* ── EAN-13 ── */
const L = ['0001101', '0011001', '0010011', '0111101', '0100011', '0110001', '0101111', '0111011', '0110111', '0001011'];
const G = L.map(c => [...c].map(b => b === '1' ? '0' : '1').reverse().join(''));
const R = L.map(c => [...c].map(b => b === '1' ? '0' : '1').join(''));
const PAR = ['LLLLLL', 'LLGLGG', 'LLGGLG', 'LLGGGL', 'LGLLGG', 'LGGLLG', 'LGGGLL', 'LGLGLG', 'LGLGGL', 'LGGLGL'];
const check = d12 => { let s = 0; for (let i = 0; i < 12; i++) s += +d12[i] * (i % 2 ? 3 : 1); return (10 - s % 10) % 10; };
const full = stem => stem + check(stem);
const fmt = c => c.length === 13 ? c[0] + ' ' + c.slice(1, 7) + ' ' + c.slice(7) : c;

/* ── catalog ── */
const C = [
  { stem: '204417032118', name: 'Copper Watering Can', size: '2 gal · 7.6 L', brand: 'Fieldstone Tools', dept: 'Garden tools', loc: 'Aisle 3 · Bay A · Shelf 2', price: 4800, unit: null, shelf: 4, back: 6, order: null, hist: [['May 2', 5200], ['Jun 14', 5200], ['Jul 1', 4600], ['Aug 9', 4800], ['Sep 3', 4800], ['Sep 28', 4800]], near: [['Millbrook', 4.2, 7], ['Ashford Commons', 9.8, 2], ['Riverside', 14.1, 0]] },
  { stem: '210058840029', name: 'Cedar Raised Bed Kit', size: '4 × 8 ft · 11 in deep', brand: 'Hollow Grove', dept: 'Seasonal', loc: 'Seasonal · Pad 2', price: 12900, unit: null, shelf: 2, back: 0, order: { qty: 12, po: 'PO-55102', eta: 'Oct 9' }, hist: [['Mar 1', 13900], ['Apr 12', 13900], ['May 20', 12900], ['Jul 4', 11900], ['Aug 1', 12900], ['Sep 15', 12900]], near: [['Millbrook', 4.2, 1], ['Ashford Commons', 9.8, 5], ['Riverside', 14.1, 3]] },
  { stem: '231190470035', name: 'Organic Bone Meal', size: '4 lb bag', brand: 'Meadowroot', dept: 'Soil & feed', loc: 'Aisle 6 · Bay C · Shelf 1', price: 1149, unit: [1149, 4, 'lb'], promo: '2 for $20.00 through Oct 12', shelf: 18, back: 24, order: null, hist: [['Apr 2', 1049], ['May 6', 1099], ['Jun 3', 1099], ['Jul 15', 1149], ['Aug 26', 1149], ['Sep 30', 1149]], near: [['Millbrook', 4.2, 30], ['Ashford Commons', 9.8, 12], ['Riverside', 14.1, 22]] },
  { stem: '240336127704', name: 'Ceramic Planter, Sage', size: '10 in · drainage hole', brand: 'Kiln & Leaf', dept: 'Pots & planters', loc: 'Aisle 2 · Bay D · Shelf 3', price: 3400, clear: 2380, shelf: 5, back: 0, order: null, hist: [['Feb 9', 3400], ['Apr 1', 3400], ['Jun 1', 3600], ['Jul 20', 3400], ['Sep 1', 3400], ['Sep 25', 2380]], near: [['Millbrook', 4.2, 0], ['Ashford Commons', 9.8, 3], ['Riverside', 14.1, 6]] },
  { stem: '261402253302', name: 'Hand Trowel, Ash Handle', size: 'Forged steel · 12 in', brand: 'Fieldstone Tools', dept: 'Garden tools', loc: 'Aisle 3 · Bay B · Hook 14', price: 1650, shelf: 11, back: 8, order: null, hist: [['Mar 3', 1500], ['Apr 8', 1500], ['May 12', 1650], ['Jul 7', 1650], ['Aug 18', 1650], ['Sep 22', 1650]], near: [['Millbrook', 4.2, 9], ['Ashford Commons', 9.8, 14], ['Riverside', 14.1, 4]] },
  { stem: '277025190087', name: 'Galvanized Hose Reel', size: 'Holds 150 ft of ⅝ in hose', brand: 'Brookline Yard', dept: 'Watering', loc: 'Aisle 4 · Endcap', price: 6400, disc: true, shelf: 1, back: 2, order: null, hist: [['Jan 5', 6900], ['Mar 9', 6900], ['May 1', 6900], ['Jun 22', 6400], ['Aug 3', 6400], ['Sep 12', 6400]], near: [['Millbrook', 4.2, 0], ['Ashford Commons', 9.8, 1], ['Riverside', 14.1, 0]] },
  { stem: '291867400019', name: 'Neem Oil Spray', size: '24 fl oz · ready to use', brand: 'Meadowroot', dept: 'Pest & disease', loc: 'Aisle 6 · Bay A · Shelf 4', price: 1299, unit: [1299, 24, 'fl oz'], shelf: 9, back: 12, order: { qty: 24, po: 'PO-55117', eta: 'Oct 6' }, hist: [['Apr 4', 1199], ['May 2', 1199], ['Jun 6', 1299], ['Jul 11', 1299], ['Aug 15', 1299], ['Sep 19', 1299]], near: [['Millbrook', 4.2, 4], ['Ashford Commons', 9.8, 0], ['Riverside', 14.1, 11]] }
].map(x => Object.assign(x, { code: full(x.stem) }));
const WK = [[1, 0, 2, 1, 0, 3, 2], [0, 1, 0, 0, 2, 1, 0], [3, 5, 2, 4, 6, 8, 5], [1, 2, 0, 1, 3, 4, 2], [2, 1, 1, 3, 2, 4, 3], [0, 0, 1, 0, 0, 1, 0], [2, 3, 1, 2, 4, 5, 3]];
C.forEach((x, i) => { x.wk = WK[i]; });
const DAYS = ['Fri', 'Sat', 'Sun', 'Mon', 'Tue', 'Wed', 'Thu'];
const BY = Object.fromEntries(C.map(x => [x.code, x]));
const UNKNOWN = full('236620018845');
const BADCHK = (() => { const c = C[2].code; return c.slice(0, 12) + ((+c[12] + 4) % 10); })();
const QUEUE = [C[0].code, C[3].code, C[2].code, UNKNOWN, C[5].code, BADCHK, C[1].code, C[6].code, C[4].code];

const S = { code: '', item: null, tab: 'over', recent: [], status: null, view: 'scan', basket: [], q: 0, scanning: false, holds: {}, labels: {} };
let uid = 0, lastCleared = null;

/* ── barcode drawing ── */
function modules(code) {
  // returns [{bits, digit, part}] for the 12 encoded digits (digit 0 is implied by parity)
  const d = code.padEnd(13, ' ');
  const lead = d[0] === ' ' ? null : +d[0];
  const out = [];
  for (let i = 1; i < 13; i++) {
    const ch = d[i];
    if (ch === ' ') { out.push({ bits: null, i }); continue; }
    const n = +ch;
    if (i <= 6) { const p = lead == null ? 'L' : PAR[lead][i - 1]; out.push({ bits: (p === 'L' ? L : G)[n], i, p }); }
    else out.push({ bits: R[n], i, p: 'R' });
  }
  return out;
}
function barsSVG(code, opts = {}) {
  const Q = 9, H = opts.h || 52, GH = H + 7, W = Q + 95 + 7;
  const typed = code.replace(/\D/g, '');
  let x = Q, bars = [], k = 0, ghosts = [];
  const run = (bits, h, cls) => {
    let start = -1;
    for (let j = 0; j <= bits.length; j++) {
      if (bits[j] === '1' && start < 0) start = j;
      if (bits[j] !== '1' && start >= 0) { bars.push(`<rect class="${cls}" x="${x + start}" y="0" width="${j - start}" height="${h}" style="--i:${k++}"/>`); start = -1; }
    }
    x += bits.length;
  };
  run('101', GH, 'bar');
  const mods = modules(typed);
  const chk = typed.length >= 12 ? String(check(typed.slice(0, 12))) : null;
  mods.forEach((m, idx) => {
    if (idx === 6) run('01010', GH, 'bar');
    if (m.bits) run(m.bits, H, 'bar');
    else if (m.i === 12 && chk != null) { run(R[+chk], H, 'chk'); }
    else { ghosts.push(`<rect class="ghost" x="${x + .5}" y="0" width="6" height="${H}" rx="1"/>`); x += 7; }
  });
  run('101', GH, 'bar');
  if (opts.bare) return `<svg viewBox="0 0 ${W} ${GH}" preserveAspectRatio="none" aria-hidden="true">${bars.join('')}</svg>`;
  const t = [], dg = typed.padEnd(13, '·');
  t.push(`<text x="${Q - 4.5}" y="${H + 9}" text-anchor="middle" class="${typed[0] ? '' : 'q'}">${dg[0]}</text>`);
  for (let i = 1; i < 13; i++) {
    const cx = Q + 3 + (i - 1) * 7 + (i > 6 ? 5 : 0) + 3.5;
    const isChk = i === 12 && typed.length === 12;
    t.push(`<text x="${cx}" y="${H + 9}" text-anchor="middle" class="${isChk ? 'c' : typed[i] ? '' : 'q'}">${isChk ? chk : dg[i]}</text>`);
  }
  return `<svg viewBox="0 0 ${W} ${H + 11}" role="img" aria-label="EAN-13 barcode ${esc(fmt(typed))}" class="${opts.reveal ? 'reveal' : ''}">${ghosts.join('')}${bars.join('')}${t.join('')}</svg>`;
}
function parityHTML(code) {
  const d = code.replace(/\D/g, '');
  const lead = d[0];
  const cells = [];
  for (let i = 0; i < 13; i++) {
    const ch = d[i] || (i === 12 && d.length === 12 ? String(check(d)) : '');
    const p = i === 0 ? '' : i <= 6 ? (lead != null ? PAR[+lead][i - 1] : '') : 'R';
    cells.push(`<span data-p="${i === 12 && d.length === 12 ? '#' : ch ? p : ''}" title="${i === 0 ? 'Leading digit sets the parity' : p ? p + ' code' : ''}">${ch || '·'}</span>`);
  }
  return `<div class="row" aria-hidden="true">${cells.join('')}</div>
    <div class="key"><span>Leading <b>${lead ?? '–'}</b> → <b>${lead != null ? PAR[+lead].split('').join(' ') : '– – – – – –'}</b></span><span><i style="background:var(--apo-scan-g)"></i>G even</span><span><i style="background:var(--apo-scan-r)"></i>R right</span>${d.length >= 12 ? `<span>check <b>${check(d.slice(0, 12))}</b></span>` : ''}</div>`;
}

/* ── lookup ── */
function setStatus(tone, html, fix) { S.status = { tone, html, fix }; }
function lookup(raw, how = 'typed') {
  const d = raw.replace(/\D/g, '');
  if (d.length < 12) { setStatus('warn', `${d.length} of 13 digits — keep typing`); S.item = null; renderAll(); return; }
  const code = d.length === 12 ? d + check(d) : d.slice(0, 13);
  const want = check(code.slice(0, 12));
  if (+code[12] !== want) {
    setStatus('bad', `Check digit ${code[12]} does not match — expected <b>${want}</b>`, code.slice(0, 12) + want);
    S.item = { bad: true, code };
    pushRecent({ code, name: 'Misread label', tone: 'bad' }); renderAll(); return;
  }
  const it = BY[code];
  S.code = code; $('#apo-scan-code').value = code;
  if (it) {
    setStatus('ok', `${how === 'scan' ? 'Decoded' : 'Found'} EAN-13 · ${esc(it.name)}`);
    S.item = it; S.tab = 'over';
    pushRecent({ code, name: it.name, price: it.clear || it.price });
  } else {
    setStatus('warn', 'Valid barcode, not in the Store 112 catalog');
    S.item = { unknown: true, code };
    pushRecent({ code, name: 'Not in catalog', tone: 'bad' });
  }
  if (S.view === 'scan' && root.dataset.narrow) S.view = 'item';
  renderAll();
}
function pushRecent(r) {
  const now = new Date();
  S.recent = S.recent.filter(x => x.code !== r.code);
  S.recent.unshift(Object.assign({ id: 'r' + (++uid), at: now.toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' }) }, r));
  S.recent = S.recent.slice(0, 12);
}

/* ── render ── */
function keep(fn) {
  const a = root.contains(document.activeElement) ? document.activeElement : null, k = a && a.dataset.k;
  fn();
  if (k) { const n = root.querySelector('[data-k="' + CSS.escape(k) + '"]'); if (n && n !== document.activeElement && !n.disabled) n.focus({ preventScroll: true }); }
}
function renderLabel(reveal) {
  const typed = $('#apo-scan-code').value.replace(/\D/g, '').slice(0, 13);
  $('.apo-scan-bars').innerHTML = barsSVG(typed, { reveal });
  $('[data-parity]').innerHTML = parityHTML(typed);
}
function renderStatus() {
  const st = $('[data-status]');
  const s = S.status || { tone: '', html: 'Scan a label or type its 13 digits. A 12-digit entry gets its check digit computed.' };
  st.dataset.tone = s.tone;
  st.innerHTML = `<i></i><span>${s.html}</span>${s.fix ? `<button type="button" data-act="fix" data-k="fix">Use ${s.fix[12]}</button>` : ''}`;
}
const avail = it => Math.max(0, it.shelf - (S.holds[it.code] || 0));
function itemHTML() {
  const it = S.item;
  if (!it) return `<div class="apo-scan-empty">${svg('q')}<b>No item yet</b><p>Scan a shelf label, type a barcode, or pick one from Recent. Try <b>S</b> to simulate a scan.</p></div>`;
  if (it.bad) return `<div class="apo-scan-empty">${svg('q')}<b>Label misread</b><p>${esc(fmt(it.code))} fails the EAN-13 check. Rescan the label, or accept the corrected check digit on the left if the printed digits are right.</p></div>`;
  if (it.unknown) return `<div class="apo-scan-empty">${svg('q')}<b>Not in this store's catalog</b><p>${esc(fmt(it.code))} is a valid in-store code but no item uses it at Store 112.</p>
      ${it.sent ? `<p class="apo-scan-chip" data-tone="ok">Request ${it.sent} sent to merchandising</p>` : `<form class="apo-scan-form" data-form="nir" novalidate>
        <label>What is it?<input name="desc" placeholder="e.g. Terracotta saucer 8 in" data-k="nir-desc"></label>
        <div class="two"><label>Shelf price<input name="price" inputmode="decimal" placeholder="0.00" data-k="nir-price"></label>
        <label>Department<select name="dept" data-k="nir-dept"><option>Pots &amp; planters</option><option>Garden tools</option><option>Soil &amp; feed</option><option>Watering</option></select></label></div>
        <p class="err" data-err></p><div class="row"><button type="submit" class="apo-scan-btn solid">${svg('send')}Request new item</button></div></form>`}</div>`;
  const cur = it.clear || it.price;
  const unitTxt = it.unit ? `${money(Math.round(it.unit[0] / it.unit[1]))} per ${it.unit[2]}` : 'Sold each';
  const held = S.holds[it.code] || 0;
  const chips = [`<span class="apo-scan-chip">${esc(it.dept)}</span>`,
    it.promo ? `<span class="apo-scan-chip" data-tone="promo">${esc(it.promo)}</span>` : '',
    it.clear ? `<span class="apo-scan-chip" data-tone="bad">Clearance −${Math.round((1 - it.clear / it.price) * 100)}%</span>` : '',
    it.disc ? `<span class="apo-scan-chip" data-tone="bad">Discontinued</span>` : '',
    held ? `<span class="apo-scan-chip" data-tone="ok">${held} on hold</span>` : ''].join('');
  const tabs = [['over', 'Overview', 1], ['stock', 'Stock', 2], ['hist', 'Price history', 3]].map(([id, lab, n]) =>
    `<button type="button" role="tab" data-act="tab" data-id="${id}" data-k="tab-${id}" aria-selected="${S.tab === id}" tabindex="${S.tab === id ? 0 : -1}">${lab}<kbd>${n}</kbd></button>`).join('');
  let pane = '';
  if (S.tab === 'over') {
    pane = `<dl class="apo-scan-facts">
      <div><dt>Location</dt><dd>${esc(it.loc)}</dd></div><div><dt>Available here</dt><dd>${avail(it)} on shelf · ${it.back} back</dd></div>
      <div><dt>Brand</dt><dd>${esc(it.brand)}</dd></div><div><dt>Unit price</dt><dd>${unitTxt}</dd></div>
      <div><dt>Barcode</dt><dd style="font-family:var(--apo-scan-mono);font-size:13px">${fmt(it.code)}</dd></div><div><dt>On order</dt><dd>${it.order ? it.order.qty + ' · ' + it.order.po + ' · ETA ' + it.order.eta : 'Nothing open'}</dd></div></dl>
      <div class="apo-scan-acts">
        <button type="button" class="apo-scan-btn solid" data-act="add" data-k="add" ${avail(it) + it.back ? '' : 'disabled title="None available in this store"'}>${svg('cart')}Add to sale <kbd>A</kbd></button>
        <button type="button" class="apo-scan-btn" data-act="label" data-k="label">${svg('tag')}Shelf label${S.labels[it.code] ? ' · ' + S.labels[it.code] + ' printed' : ''} <kbd>L</kbd></button>
        <button type="button" class="apo-scan-btn" data-act="hold" data-k="hold" ${avail(it) ? '' : 'disabled title="Nothing on the shelf to hold"'}>${svg('hold')}Hold for customer <kbd>H</kbd></button></div>
      ${(() => { const tot = it.wk.reduce((a, b) => a + b, 0), mx = Math.max(1, ...it.wk), on = avail(it) + it.back, cover = tot ? on / (tot / 7) : Infinity;
