  --apo-returns-tilt: 0deg;
  position: relative; width: 100%; height: var(--apo-returns-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apo-returns;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--apo-returns-line);
  background: var(--apo-returns-bg); color: var(--apo-returns-ink);
