  & .apo-returns-ghost { display: inline-flex; align-items: center; gap: 7px; height: 32px; padding: 0 11px; border-radius: 8px; font-size: 13px; font-weight: 650; border: 1px solid var(--apo-returns-line2); background: var(--apo-returns-panel); transition: border-color .2s, background .2s;
    & svg { width: 16px; height: 16px; }
