function tick(id) {
  const r = RC[S.rid], l = r.lines.find(x => x.id === id), st = cur();
  if (!l || blocked(r, l)) return;
  const s = st.sel[id];
  remember(s && s.qty ? 'unselect ' + l.name : 'select ' + l.name);
  if (s && s.qty) { delete st.sel[id]; st.exch = st.exch.filter(x => x.from !== id); }
  else st.sel[id] = { qty: 1, reason: l.sizes ? 0 : 2, cond: 'resell' };
  render();
}
function qty(id, d) {
  const r = RC[S.rid], l = r.lines.find(x => x.id === id), st = cur(), s = st.sel[id];
  if (!s) return;
  const n = s.qty + d;
  if (n <= 0) return tick(id);
  if (n > avail(l)) return;
  remember('quantity'); s.qty = n;
  const sw = st.exch.find(x => x.from === id); if (sw) sw.qty = n;
  render();
}
function finish() {
  const t = totals(); if (!t.units) return;
