  const ex = t.st.exch.map(x => `<li>${x.qty} × ${esc(x.name)} (${esc(x.vr)}) out</li>`).join('');
  const money2 = t.net < 0 ? t.route.map(x => `<li>${money(x.amt)} to ${esc(x.label)}</li>`).join('') : t.net > 0 ? `<li>${money(t.net)} collected by ${t.st.pay}</li>` : '<li>Even exchange, no money moved</li>';
