root.addEventListener('click', e => {
  const b = e.target.closest('[data-act]'); if (!b || !root.contains(b) || b.disabled) return;
  const a = b.dataset.act, id = b.dataset.id, st = cur();
  if (a === 'rc') { S.rid = +b.dataset.i; if (root.clientWidth < 960) S.view = 'items'; render(); }
  else if (a === 'tick') tick(id);
  else if (a === 'qty') qty(id, +b.dataset.d);
  else if (a === 'cond') { if (st.sel[id].cond !== b.dataset.v) { remember('condition'); st.sel[id].cond = b.dataset.v; render(); } }
  else if (a === 'swap') {
    const l = RC[S.rid].lines.find(x => x.id === id), had = st.exch.find(x => x.from === id);
    remember('size swap');
    st.exch = st.exch.filter(x => x.from !== id);
    if (!had || had.size !== b.dataset.z) st.exch.push(swapItem(l, b.dataset.z, st.sel[id].qty));
    render();
  }
  else if (a === 'xadd') {
    const [n, v, p] = CAT[+b.dataset.i]; remember('add ' + n);
    const ex = st.exch.find(x => !x.even && x.name === n);
    if (ex) ex.qty++; else st.exch.push({ id: 'x' + (++xid), name: n, vr: v, unit: p, tax: Math.round(p * TAXR), qty: 1, even: false });
    render(); toast(n + ' added to the exchange');
  }
  else if (a === 'xdel') { remember('remove exchange item'); st.exch = st.exch.filter(x => x.id !== b.dataset.x); render(); }
  else if (a === 'override') { remember('override'); st.override = !st.override; if (!st.override) { st.sel = {}; st.exch = st.exch.filter(x => !x.even); } render(); toast(st.override ? 'Override by M. Vega · refunds go to store credit' : 'Override removed'); }
  else if (a === 'credit') { remember('refund method'); st.credit = !st.credit; render(); }
  else if (a === 'pay') { st.pay = b.dataset.v; render(); }
  else if (a === 'complete') finish();
  else if (a === 'printret') { b.textContent = 'Slip printed'; b.disabled = true; b.title = 'Already printed'; toast('Return slip sent to the receipt printer'); }
  else if (a === 'next') { $('.apo-returns-sheet').hidden = true; S.view = 'find'; render(); const f = $('.apo-returns-search input'); f.focus({ preventScroll: true }); }
  else if (a === 'undo') undo();
  else if (a === 'view') { S.view = id; render(); }
});
root.addEventListener('change', e => {
