  const t = e.target, tag = t.tagName;
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z') { if (tag !== 'INPUT') { undo(); e.preventDefault(); } return; }
  if (tag === 'INPUT' || tag === 'SELECT' || e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key, li = t.closest('.apo-returns-line'), id = li && li.dataset.id;
  if (t.classList.contains('apo-returns-rc') && (k === 'ArrowDown' || k === 'ArrowUp' || k === 'Enter' || k === ' ')) {
    if (k === 'Enter' || k === ' ') { t.click(); e.preventDefault(); return; }
    const all = $$('.apo-returns-rc'), i = all.indexOf(t), n = all[Math.max(0, Math.min(all.length - 1, i + (k === 'ArrowDown' ? 1 : -1)))];
    if (n) { n.click(); const f = $('[data-k="' + n.dataset.k + '"]'); if (f) f.focus(); } e.preventDefault(); return;
  }
  if (k === 'ArrowDown' || k === 'ArrowUp') {
    const ticks = $$('.apo-returns-tick'); if (!ticks.length) return;
    const i = li ? ticks.indexOf($('.apo-returns-tick', li)) : -1;
    const n = ticks[Math.max(0, Math.min(ticks.length - 1, i + (k === 'ArrowDown' ? 1 : -1)))];
    n.focus(); n.scrollIntoView({ block: 'nearest' }); e.preventDefault(); return;
  }
  if (k === '/') { find.focus(); find.select(); e.preventDefault(); return; }
  if ((k === 's' || k === 'S')) { const sw = $('[data-act="credit"]'); if (sw) sw.click(); e.preventDefault(); return; }
  if (k === 'Enter' && tag !== 'BUTTON') { const g = $('[data-act="complete"]'); if (g && !g.disabled) g.click(); e.preventDefault(); return; }
  if (!id || !cur().sel[id]) return;
  if (k === '+' || k === '=') { qty(id, 1); e.preventDefault(); }
  else if (k === '-' || k === '_') { qty(id, -1); e.preventDefault(); }
  else if (/^[1-4]$/.test(k)) { remember('reason'); cur().sel[id].reason = +k - 1; if (k === '2') cur().sel[id].cond = 'damaged'; render(); e.preventDefault(); }
  else if (k === 'd' || k === 'D') { remember('condition'); const s = cur().sel[id]; s.cond = s.cond === 'damaged' ? 'resell' : 'damaged'; render(); e.preventDefault(); }
});

render();

