@keyframes apo-receive-flash { 0% { background: color-mix(in oklch, var(--apo-receive-accent) 26%, transparent); } 100% { background: transparent; } }
@keyframes apo-receive-shake { 20%, 60% { translate: -4px 0; } 40%, 80% { translate: 4px 0; } }
@keyframes apo-receive-shadow { to { box-shadow: 0 8px 12px -10px black; } }

@container apo-receive (width < 960px) {
  .apo-receive .apo-receive-app { grid-template-columns: minmax(0, 1fr) 260px; }
