  .apo-receive .apo-receive-keys { display: none; }
  .apo-receive .apo-receive-head { flex-wrap: wrap; gap: 8px 10px; }
  .apo-receive .apo-receive-brand { flex: 1 1 100%; }
  .apo-receive .apo-receive-brand span { display: none; }
  .apo-receive .apo-receive-head .apo-receive-ghost { margin-left: auto; }
  .apo-receive .apo-receive-nav { grid-area: nav; display: flex; gap: 4px; padding: 6px 12px; border-bottom: 1px solid var(--apo-receive-line);
    & button { flex: 1; height: 34px; border-radius: 9px; font-weight: 700; font-size: 13px; color: var(--apo-receive-mute); }
    & button[aria-selected="true"] { color: var(--apo-receive-bg); background: var(--apo-receive-ink); }
