const IC = { minus: '<path d="M6 12h12"/>', plus: '<path d="M12 6v12M6 12h12"/>', box: '<path d="M4 8.5 12 5l8 3.5v8L12 20l-8-3.5Z"/><path d="m4 8.5 8 3.5 8-3.5M12 12v8"/>', open: '<path d="M4 9 12 5l8 4M4 9v7.5L12 20l8-3.5V9M4 9l8 4 8-4M12 13v7"/><path d="M8 4.5 4 2.5M16 4.5l4-2"/>' };
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';

const LINES = [
  { sku: 'HP-1180', name: 'Dot Grid Notebook A5', vr: 'Sage cloth', pack: 12, ord: 48, cost: 640 },
  { sku: 'HP-1182', name: 'Dot Grid Notebook A5', vr: 'Rust cloth', pack: 12, ord: 36, cost: 640 },
  { sku: 'HP-2207', name: 'Gel Pen 0.5 mm', vr: 'Black ink', pack: 24, ord: 72, cost: 115 },
  { sku: 'HP-3310', name: 'Kraft Envelopes C6, 50', vr: 'Recycled', pack: 10, ord: 30, cost: 380 },
  { sku: 'HP-4402', name: 'Washi Tape Set', vr: 'Botanical, 6 rolls', pack: 8, ord: 24, cost: 425 },
  { sku: 'HP-5120', name: 'Linen Sketchbook 9×12', vr: 'Natural', pack: 6, ord: 18, cost: 1190 },
  { sku: 'HP-6001', name: 'Brass Bookmark', vr: 'Fern', pack: 20, ord: 40, cost: 210 },
  { sku: 'HP-7715', name: 'Leather Pencil Roll', vr: 'Shipped, not ordered', pack: 6, ord: 0, cost: 1450, extra: true }
];
const BY = Object.fromEntries(LINES.map(l => [l.sku, l]));
const CARTONS = [
  { id: 'C1', label: 'Carton 1', wt: '14.2 kg', items: [['HP-1180', 24], ['HP-1182', 12]] },
  { id: 'C2', label: 'Carton 2', wt: '14.0 kg', items: [['HP-1180', 24], ['HP-1182', 12]], dmg: { 'HP-1180': 1 }, note: { 'HP-1180': 'corner crushed' } },
  { id: 'C3', label: 'Carton 3', wt: '9.6 kg', items: [['HP-2207', 72], ['HP-6001', 44]] },
  { id: 'C4', label: 'Carton 4', wt: '11.1 kg', items: [['HP-3310', 30], ['HP-4402', 16]] },
  { id: 'C5', label: 'Carton 5', wt: '12.8 kg', items: [['HP-5120', 18], ['HP-1182', 12], ['HP-7715', 6]] }
];
const ORD_UNITS = LINES.reduce((a, l) => a + l.ord, 0), ORD_VALUE = LINES.reduce((a, l) => a + l.ord * l.cost, 0);

const S = { rec: {}, dmg: {}, done: {}, over: {}, extra: 'accept', short: {}, cur: 'HP-1180', posted: null, view: 'lines' };
LINES.forEach(l => { S.rec[l.sku] = 0; S.dmg[l.sku] = 0; S.short[l.sku] = 'backorder'; });
S.rec['HP-1180'] = 24; S.rec['HP-1182'] = 12; S.done.C1 = true;
const hist = [];
const snap = () => JSON.stringify({ rec: S.rec, dmg: S.dmg, done: S.done, over: S.over, extra: S.extra });
const remember = label => { if (S.posted) return; hist.push({ s: snap(), label }); if (hist.length > 50) hist.shift(); };

function stats() {
  let units = 0, short = 0, over = 0, dmg = 0, value = 0, extraUnits = 0;
  LINES.forEach(l => {
    const r = S.rec[l.sku], d = S.dmg[l.sku];
    dmg += d;
    if (l.extra) { extraUnits = r; if (S.extra === 'accept') value += (r - d) * l.cost; return; }
    units += r; short += Math.max(0, l.ord - r); over += Math.max(0, r - l.ord);
    const keepOver = S.over[l.sku] ? r : Math.min(r, l.ord);
