  return { units, short, over, dmg, value, extraUnits };
}

/* ── rows: built once, patched ── */
function rowShell(l) {
  const li = document.createElement('li');
  li.className = 'apo-receive-line'; li.dataset.sku = l.sku;
  li.innerHTML = `<div class="it" data-act="cur" data-sku="${l.sku}"><div class="sku">${l.sku}</div><div class="nm">${esc(l.name)}</div><div class="meta">${esc(l.vr)} · pack of ${l.pack} · ${money(l.cost)}</div></div>
    <div class="apo-receive-meter" role="meter" aria-label="${esc(l.name)} cases"></div>
    <div class="rc"><b class="r"></b><span class="o"></span><br><span class="badge"></span><div class="dec"></div></div>
    <div class="dm"><span class="apo-receive-step" role="group" aria-label="Damaged units"><button type="button" data-act="dmg" data-d="-1" data-sku="${l.sku}" data-k="dm-${l.sku}" aria-label="One fewer damaged">${svg('minus')}</button><b></b><button type="button" data-act="dmg" data-d="1" data-sku="${l.sku}" data-k="dp-${l.sku}" aria-label="Mark one damaged">${svg('plus')}</button></span></div>
    <div class="apo-receive-acts"></div>`;
  return li;
}
function patchRow(li, l) {
  const r = S.rec[l.sku], d = S.dmg[l.sku], locked = !!S.posted;
  const it = $('.it', li); it.setAttribute('aria-current', String(S.cur === l.sku));
  li.toggleAttribute('data-cur', S.cur === l.sku);
  // meter
  const m = $('.apo-receive-meter', li);
  const n = Math.max(1, Math.ceil(l.ord / l.pack), Math.ceil(r / l.pack));
  let segs = $$('i', m);
  while (segs.length < n) { const i = document.createElement('i'); m.insertBefore(i, m.querySelector('small')); segs = $$('i', m); }
  while (segs.length > n) { segs.pop().remove(); }
  segs.forEach((s, i) => {
    const u = Math.max(0, Math.min(l.pack, r - i * l.pack));
    s.style.setProperty('--f', (u / l.pack).toFixed(3)); s.style.setProperty('--i', i);
    s.toggleAttribute('data-over', i * l.pack >= l.ord); s.toggleAttribute('data-full', u === l.pack);
    s.title = `Case ${i + 1}: ${u}/${l.pack}`;
  });
  let sm = $('small', m); if (!sm) { sm = document.createElement('small'); m.appendChild(sm); }
  const cases = Math.floor(r / l.pack), loose = r % l.pack;
  sm.textContent = l.extra ? `${cases} case${cases === 1 ? '' : 's'} · not on PO` : `${cases} of ${Math.ceil(l.ord / l.pack)} cases${loose ? ' + ' + loose + ' loose' : ''}`;
  m.setAttribute('aria-valuenow', r); m.setAttribute('aria-valuemax', Math.max(l.ord, r));
  // received
  $('.r', li).textContent = r; $('.o', li).textContent = l.extra ? ' units' : ' / ' + l.ord;
  const b = $('.badge', li);
  const tone = l.extra ? (r ? 'new' : '') : r === 0 ? '' : r < l.ord ? 'short' : r > l.ord ? 'over' : 'ok';
  b.dataset.tone = tone;
  b.textContent = l.extra ? (r ? 'Not on PO' : 'Expected none') : r === 0 ? 'Awaiting' : r < l.ord ? 'Short ' + (l.ord - r) : r > l.ord ? 'Over ' + (r - l.ord) : 'Complete';
  // damaged
  const st = $('.apo-receive-step', li); st.toggleAttribute('data-on', d > 0);
  $('b', st).textContent = d;
  const [dm, dp] = $$('button', st);
  dm.disabled = locked || d <= 0; dm.title = locked ? 'Receipt posted' : d <= 0 ? 'No damaged units to clear' : '';
  dp.disabled = locked || d >= r; dp.title = locked ? 'Receipt posted' : d >= r ? 'Every received unit is already marked damaged' : 'Mark one unit damaged (D)';
  // actions
  const acts = $('.apo-receive-acts', li);
  const lockT = locked ? 'disabled title="Receipt posted"' : '';
  let extraCtl = '';
  if (l.extra && r) extraCtl = `<span class="apo-receive-seg" role="radiogroup" aria-label="Unexpected item">${[['accept', 'Keep'], ['rtv', 'Return']].map(([v, t]) => `<button type="button" role="radio" data-act="extra" data-v="${v}" data-k="ex-${v}" aria-checked="${S.extra === v}" ${lockT}>${t}</button>`).join('')}</span>`;
  else if (!l.extra && r > l.ord) extraCtl = `<button type="button" class="apo-receive-mini" data-act="over" data-sku="${l.sku}" data-k="ov-${l.sku}" aria-pressed="${!!S.over[l.sku]}" ${lockT} title="Keep the ${r - l.ord} extra units and bill them">${S.over[l.sku] ? 'Keeping over' : 'Keep over?'}</button>`;
  const dec = $('.dec', li);
  if (dec.__h !== extraCtl) { dec.innerHTML = extraCtl; dec.__h = extraCtl; }
  const html = `<button type="button" class="apo-receive-mini" data-act="unit" data-d="-1" data-sku="${l.sku}" data-k="um-${l.sku}" aria-label="Remove one unit" ${locked ? lockT : r <= 0 ? 'disabled title="Nothing received yet"' : ''}>${svg('minus')}</button>
    <button type="button" class="apo-receive-mini" data-act="unit" data-d="1" data-sku="${l.sku}" data-k="up-${l.sku}" aria-label="Receive one unit" ${lockT}>${svg('plus')}1</button>
    <button type="button" class="apo-receive-mini" data-act="case" data-sku="${l.sku}" data-k="cs-${l.sku}" ${lockT} title="Receive a full case of ${l.pack} (C)">${svg('plus')}${l.pack}</button>`;
  if (acts.__h !== html) { acts.innerHTML = html; acts.__h = html; }
}
function renderLines() {
  const ol = $('.apo-receive-lines');
  LINES.forEach(l => {
    let li = ol.querySelector('[data-sku="' + l.sku + '"]');
    const show = !l.extra || S.rec[l.sku] > 0;
    if (!show) { if (li) li.remove(); return; }
    if (!li) { li = rowShell(l); ol.appendChild(li); }
    patchRow(li, l);
  });
}
function renderDock() {
  const ul = $('.apo-receive-cartons');
  const left = CARTONS.filter(c => !S.done[c.id]).length;
  $('[data-ccount]').textContent = (CARTONS.length - left) + ' of ' + CARTONS.length + ' received';
  const html = CARTONS.map(c => {
    const done = !!S.done[c.id], units = c.items.reduce((a, x) => a + x[1], 0);
    return `<li class="apo-receive-carton" data-id="${c.id}" data-state="${done ? 'done' : 'sealed'}">
      <div class="top"><span class="box">${svg('box')}</span><span><b>${c.label} of 5</b><small>${c.wt} · ${units} units · ${c.items.length} SKU${c.items.length > 1 ? 's' : ''}</small></span><span class="st">${done ? 'Received' : 'Sealed'}</span></div>
      <ul>${c.items.map(([sku, q]) => `<li><span>${sku} ${esc(BY[sku].name.split(',')[0])}</span><b>${q}</b></li>${c.note && c.note[sku] ? `<li class="flag"><span>${c.dmg[sku]} × ${c.note[sku]}</span></li>` : ''}`).join('')}</ul>
      ${done ? '' : `<button type="button" class="apo-receive-open" data-act="carton" data-id="${c.id}" data-k="ct-${c.id}" ${S.posted ? 'disabled title="Receipt posted"' : ''}>${svg('open')}Open &amp; receive</button>`}</li>`;
  }).join('');
  if (ul.__h !== html) { ul.innerHTML = html; ul.__h = html; }
  const st = stats();
  $('.apo-receive-sum').innerHTML = `<div data-tone="short"><span>Short</span><b>${st.short}</b></div><div data-tone="over"><span>Over</span><b>${st.over}</b></div>
    <div data-tone="dmg"><span>Damaged</span><b>${st.dmg}</b></div><div><span>Not on PO</span><b>${st.extraUnits}</b></div>
    <div class="wide"><span>Value received at cost</span><b>${money(st.value)}</b></div>`;
}
function renderHead() {
  const st = stats();
  $('.apo-receive-prog').innerHTML = `<div class="t"><span><b>${st.units}</b> of ${ORD_UNITS} units</span><span>${money(st.value)} of ${money(ORD_VALUE)}</span></div><div class="bar"><i style="--p:${Math.min(1, st.units / ORD_UNITS).toFixed(3)}"></i></div>`;
  const u = $('[data-act="undo"]'); u.disabled = !hist.length || !!S.posted; u.title = S.posted ? 'Receipt posted' : hist.length ? 'Undo ' + hist[hist.length - 1].label + ' (' + MOD + 'Z)' : 'Nothing to undo yet';
  const p = $('[data-act="post"]');
  p.disabled = !!S.posted || st.units === 0;
  p.title = S.posted ? 'Posted as ' + S.posted : st.units ? 'Review exceptions and post (P)' : 'Receive something first';
  $('span', p).textContent = S.posted ? 'Posted · ' + S.posted : 'Post receipt';
  $('kbd', p).hidden = !!S.posted;
  root.toggleAttribute('data-posted', !!S.posted);
  const inp = $('.apo-receive-scan input'); inp.disabled = !!S.posted;
  $('.apo-receive-scan button').disabled = !!S.posted;
  $('.apo-receive-nav').innerHTML = [['lines', 'Lines · ' + st.units + '/' + ORD_UNITS], ['dock', 'Dock · ' + CARTONS.filter(c => !S.done[c.id]).length + ' sealed']].map(([id, l]) =>
    `<button type="button" role="tab" data-act="view" data-id="${id}" data-k="nv-${id}" aria-selected="${S.view === id}">${l}</button>`).join('');
}
function keep(fn) {
  const a = root.contains(document.activeElement) ? document.activeElement : null, k = a && a.dataset.k;
  fn();
  if (k) { const n = root.querySelector('[data-k="' + CSS.escape(k) + '"]'); if (n && n !== document.activeElement && !n.disabled) n.focus({ preventScroll: true }); }
}
function render() { keep(() => { root.dataset.view = S.view; renderLines(); renderDock(); renderHead(); }); }
function flash(sku) { const li = root.querySelector('.apo-receive-line[data-sku="' + sku + '"]'); if (!li) return; li.removeAttribute('data-flash'); void li.offsetWidth; li.setAttribute('data-flash', ''); }
let tt = 0;
function toast(m) { const t = $('.apo-receive-toast'); t.textContent = m; t.setAttribute('data-on', ''); clearTimeout(tt); tt = setTimeout(() => t.removeAttribute('data-on'), 2800); }

/* ── actions ── */
function add(sku, n, why) {
  const l = BY[sku]; if (!l || S.posted) return;
  remember(why || ('receive ' + sku));
  S.rec[sku] = Math.max(0, S.rec[sku] + n);
  S.dmg[sku] = Math.min(S.dmg[sku], S.rec[sku]);
  S.cur = sku; render(); flash(sku);
}
function openCarton(id) {
  const c = CARTONS.find(x => x.id === id); if (!c || S.done[id] || S.posted) return;
  remember('open ' + c.label);
  const from = root.querySelector('.apo-receive-carton[data-id="' + id + '"] .box');
  c.items.forEach(([sku, q]) => { S.rec[sku] += q; if (c.dmg && c.dmg[sku]) S.dmg[sku] += c.dmg[sku]; });
  S.done[id] = true;
  const fr = from && from.getBoundingClientRect();
  S.cur = c.items[0][0];
  render();
  c.items.forEach(([sku], k) => flash(sku));
  const dmgN = c.dmg ? Object.values(c.dmg).reduce((a, b) => a + b, 0) : 0;
  toast(`${c.label}: ${c.items.reduce((a, x) => a + x[1], 0)} units received${dmgN ? ' · ' + dmgN + ' damaged' : ''}${c.items.some(x => BY[x[0]].extra) ? ' · 1 SKU not on PO' : ''}`);
  if (!fr || RM.matches || root.clientWidth < 760) return;
  const fly = $('.apo-receive-fly'), base = root.getBoundingClientRect();
  c.items.forEach(([sku], k) => {
    const row = root.querySelector('.apo-receive-line[data-sku="' + sku + '"] .apo-receive-meter');
    if (!row) return;
    const to = row.getBoundingClientRect();
    for (let j = 0; j < 3; j++) {
      const chip = document.createElement('i'); fly.appendChild(chip);
      const x0 = fr.left - base.left + 6, y0 = fr.top - base.top + 8, x1 = to.left - base.left + to.width * (.25 + j * .2), y1 = to.top - base.top + 1;
      const mx = (x0 + x1) / 2, my = Math.min(y0, y1) - 70;
      chip.animate([{ transform: `translate(${x0}px,${y0}px) scale(.6) rotate(-8deg)`, opacity: 0 }, { opacity: 1, offset: .15 }, { transform: `translate(${mx}px,${my}px) scale(1) rotate(6deg)`, offset: .55 }, { transform: `translate(${x1}px,${y1}px) scale(.5) rotate(0)`, opacity: .2 }],
        { duration: 720, delay: k * 110 + j * 60, easing: 'cubic-bezier(.3,.1,.25,1)', fill: 'both' }).finished.then(() => chip.remove(), () => chip.remove());
    }
  });
}
function undo() { const h = hist.pop(); if (!h || S.posted) return; Object.assign(S, JSON.parse(h.s)); render(); toast('Undid ' + h.label); }

function postSheet() {
  const st = stats(); if (S.posted || !st.units) return;
  const shorts = LINES.filter(l => !l.extra && S.rec[l.sku] < l.ord);
  const rows = [];
  shorts.forEach(l => rows.push(`<tr><td>${l.sku} short</td><td class="n">${l.ord - S.rec[l.sku]}</td><td><span class="apo-receive-seg" role="radiogroup" aria-label="${l.sku} shortage">${[['backorder', 'Backorder'], ['close', 'Close short']].map(([v, t]) => `<button type="button" role="radio" data-act="short" data-sku="${l.sku}" data-v="${v}" data-k="sh-${l.sku}-${v}" aria-checked="${S.short[l.sku] === v}">${t}</button>`).join('')}</span></td></tr>`));
  LINES.filter(l => !l.extra && S.rec[l.sku] > l.ord).forEach(l => rows.push(`<tr><td>${l.sku} over</td><td class="n">${S.rec[l.sku] - l.ord}</td><td>${S.over[l.sku] ? 'Keep and bill' : 'Return to vendor'}</td></tr>`));
  LINES.filter(l => S.dmg[l.sku]).forEach(l => rows.push(`<tr><td>${l.sku} damaged</td><td class="n">${S.dmg[l.sku]}</td><td>Vendor claim, ${money(S.dmg[l.sku] * l.cost)}</td></tr>`));
  if (st.extraUnits) rows.push(`<tr><td>HP-7715 not on PO</td><td class="n">${st.extraUnits}</td><td>${S.extra === 'accept' ? 'Keep, add to PO' : 'Return to vendor'}</td></tr>`);
  const sh = $('.apo-receive-sheet');
  sh.innerHTML = `<div role="dialog" aria-modal="true" aria-label="Post receipt"><h3>Post goods received</h3><p>${st.units} of ${ORD_UNITS} ordered units counted, ${money(st.value)} at cost goes into stock. ${rows.length ? 'Resolve the exceptions below.' : 'No exceptions.'}</p>
    ${rows.length ? `<table><thead><tr><th>Exception</th><th class="n">Units</th><th>Action</th></tr></thead><tbody>${rows.join('')}</tbody></table>` : ''}
    <div class="row"><button type="button" class="apo-receive-ghost" data-act="close" data-k="close">Keep counting</button><button type="button" class="apo-receive-post" data-act="confirm" data-k="confirm">Post GRN</button></div></div>`;
  sh.hidden = false;
  $('[data-act="confirm"]', sh).focus({ preventScroll: true });
}
function closeSheet() { const sh = $('.apo-receive-sheet'); sh.hidden = true; sh.innerHTML = ''; const p = $('[data-act="post"]'); if (p && !p.disabled) p.focus({ preventScroll: true }); }

root.addEventListener('click', e => {
  const b = e.target.closest('[data-act]'); if (!b || !root.contains(b) || b.disabled) return;
  const a = b.dataset.act, sku = b.dataset.sku;
  if (a === 'cur') { S.cur = sku; render(); }
  else if (a === 'unit') add(sku, +b.dataset.d, (+b.dataset.d > 0 ? 'add' : 'remove') + ' one ' + sku);
  else if (a === 'case') add(sku, BY[sku].pack, 'case of ' + sku);
  else if (a === 'dmg') { remember('damaged ' + sku); S.dmg[sku] = Math.max(0, Math.min(S.rec[sku], S.dmg[sku] + +b.dataset.d)); S.cur = sku; render(); }
  else if (a === 'over') { remember('over decision'); S.over[sku] = !S.over[sku]; render(); }
  else if (a === 'extra') { remember('unexpected item'); S.extra = b.dataset.v; render(); }
  else if (a === 'carton') openCarton(b.dataset.id);
  else if (a === 'post') postSheet();
  else if (a === 'close') closeSheet();
  else if (a === 'short') { S.short[sku] = b.dataset.v; keep(postSheet); }
  else if (a === 'confirm') {
    const st = stats(), bo = LINES.filter(l => !l.extra && S.rec[l.sku] < l.ord && S.short[l.sku] === 'backorder').length;
    S.posted = 'GRN-58213'; hist.length = 0; closeSheet(); render();
    toast(`Posted GRN-58213 · ${money(st.value)} into stock${bo ? ' · ' + bo + ' backorder' + (bo > 1 ? 's' : '') + ' raised' : ''}`);
  }
  else if (a === 'undo') undo();
  else if (a === 'view') { S.view = b.dataset.id; render(); }
});
$('.apo-receive-sheet').addEventListener('click', e => { if (e.target === e.currentTarget) closeSheet(); });
const scan = $('.apo-receive-scan'), inp = $('input', scan);
scan.addEventListener('submit', e => {
  e.preventDefault();
  const v = inp.value.trim().toUpperCase().replace(/\s+/g, '');
  const m = /^(?:HP-?)?(\d{4})(?:[*X](\d{1,3}))?$/.exec(v);
  const sku = m && 'HP-' + m[1];
  if (!m || !BY[sku]) {
    scan.setAttribute('data-flash', 'bad'); setTimeout(() => scan.removeAttribute('data-flash'), 400);
    toast(v ? v + ' is not on PO-2417 or ASN 88-0417' : 'Type or scan a SKU first'); return;
  }
  const n = m[2] ? +m[2] : 1;
  add(sku, n, 'scan ' + sku);
  inp.value = '';
  toast('+' + n + ' ' + sku + ' · ' + BY[sku].name);
  const row = root.querySelector('.apo-receive-line[data-sku="' + sku + '"]'); if (row) row.scrollIntoView({ block: 'nearest', behavior: RM.matches ? 'auto' : 'smooth' });
});
root.addEventListener('keydown', e => {
  const sh = $('.apo-receive-sheet');
  if (!sh.hidden) { if (e.key === 'Escape') { closeSheet(); e.preventDefault(); } return; }
  const tag = e.target.tagName;
  if ((e.metaKey || e.ctrlKey) && e.key.toLowerCase() === 'z') { if (tag !== 'INPUT') { undo(); e.preventDefault(); } return; }
  if (tag === 'INPUT') { if (e.key === 'Escape') { inp.value = ''; inp.blur(); root.focus(); } return; }
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  const k = e.key, vis = LINES.filter(l => !l.extra || S.rec[l.sku] > 0), i = vis.findIndex(l => l.sku === S.cur);
  if (k === 'ArrowDown' || k === 'ArrowUp') {
    S.cur = vis[Math.max(0, Math.min(vis.length - 1, i + (k === 'ArrowDown' ? 1 : -1)))].sku; render();
    const row = root.querySelector('.apo-receive-line[data-sku="' + S.cur + '"]'); if (row) row.scrollIntoView({ block: 'nearest' });
    e.preventDefault();
  }
  else if (k === '/') { inp.focus(); e.preventDefault(); }
  else if (S.posted) return;
  else if (k === '+' || k === '=') { add(S.cur, 1); e.preventDefault(); }
  else if (k === '-' || k === '_') { if (S.rec[S.cur] > 0) add(S.cur, -1); e.preventDefault(); }
  else if (k === 'c' || k === 'C') { add(S.cur, BY[S.cur].pack, 'case of ' + S.cur); e.preventDefault(); }
  else if (k === 'd' || k === 'D') { const d = e.shiftKey ? -1 : 1; if (S.dmg[S.cur] + d >= 0 && S.dmg[S.cur] + d <= S.rec[S.cur]) { remember('damaged'); S.dmg[S.cur] += d; render(); } e.preventDefault(); }
  else if (k === 'o' || k === 'O') { const c = CARTONS.find(x => !S.done[x.id]); if (c) openCarton(c.id); else toast('Every carton is received'); e.preventDefault(); }
  else if (k === 'p' || k === 'P') { postSheet(); e.preventDefault(); }
});

render();

css:
.apo-count {
  --apo-count-bg: oklch(0.952 0.024 84);
