  position: relative; width: 100%; height: var(--apo-count-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apo-count;
  overflow: clip; isolation: isolate; border-radius: 14px; border: 1px solid var(--apo-count-line2);
  background: var(--apo-count-bg); color: var(--apo-count-ink);
