  & kbd { font: 600 10px/1 var(--apo-count-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apo-count-line2); border-bottom-width: 2px; color: var(--apo-count-mute); background: var(--apo-count-panel); }
  & .apo-count-ghost { display: inline-flex; align-items: center; justify-content: center; gap: 7px; height: 34px; padding: 0 12px; border-radius: 9px; font-size: 13px; font-weight: 650; border: 1px solid var(--apo-count-line2); background: var(--apo-count-panel); transition: border-color .2s;
    & svg { width: 16px; height: 16px; }
