  }
  & .apo-count-solid { display: inline-flex; align-items: center; justify-content: center; gap: 9px; height: 42px; padding: 0 16px; border-radius: 11px; font-weight: 800; color: var(--apo-count-panel); background: var(--apo-count-ink); transition: background .2s, transform .14s var(--apo-count-ease);
    & kbd { color: inherit; background: transparent; border-color: color-mix(in oklch, white 35%, transparent); }
    &:hover:not(:disabled) { background: color-mix(in oklch, var(--apo-count-ink), var(--apo-count-accent) 40%); }
    &:active:not(:disabled) { transform: scale(.98); }
  }

  & .apo-count-app { height: 100%; display: grid; grid-template: "head head head" auto "map sheet var" minmax(0, 1fr) "keys keys keys" auto / clamp(168px, 17cqi, 200px) minmax(0, 1fr) clamp(290px, 31cqi, 360px); }

  & .apo-count-head { grid-area: head; display: flex; align-items: center; gap: 18px; padding: 12px 16px; border-bottom: 1px solid var(--apo-count-line); }
  & .apo-count-title { min-width: 0; margin-right: auto;
