  }
  & .apo-count-phases { list-style: none; margin: 0; padding: 0; display: flex; gap: 2px; counter-reset: ph;
    & li { counter-increment: ph; display: flex; align-items: center; gap: 7px; padding: 6px 12px 6px 6px; font-size: 12.5px; font-weight: 650; color: var(--apo-count-mute); border-radius: 99px; }
