    & .t { display: flex; justify-content: space-between; align-items: baseline; font-size: 12px; font-weight: 750; }
    & .t span { font-weight: 600; color: var(--apo-count-mute); font-variant-numeric: tabular-nums; }
    & .shelf { display: grid; grid-auto-flow: column; grid-auto-columns: 1fr; gap: 3px; padding-bottom: 3px; border-bottom: 3px solid color-mix(in oklch, var(--apo-count-ink) 70%, var(--apo-count-bg)); }
    & .shelf i { height: 22px; border-radius: 3px 3px 1px 1px; background: var(--apo-count-sunk); box-shadow: inset 0 0 0 1px var(--apo-count-line); transition: background .3s, height .4s var(--apo-count-spring); }
    & .shelf i[data-s="done"] { background: color-mix(in oklch, var(--apo-count-ink) 72%, var(--apo-count-bg)); }
    & .shelf i[data-s="ok"] { background: var(--apo-count-good); }
