    &:hover { border-color: var(--apo-count-line2); transform: translateY(-1px); }
    &[aria-selected="true"] { border-color: var(--apo-count-ink); box-shadow: 0 0 0 1px var(--apo-count-ink); }
    &[data-all] .t { font-size: 12.5px; }
  }
  & .apo-count-who { display: grid; gap: 1px; font-size: 12px; color: var(--apo-count-mute); padding-top: 10px; border-top: 1px dashed var(--apo-count-line2);
    & b { color: var(--apo-count-ink); font-size: 13px; }
  }

  /* sheet */
  & .apo-count-sheet { grid-area: sheet; min-height: 0; overflow: auto; display: grid; grid-auto-rows: max-content; align-content: start; padding: 0 16px 16px; scrollbar-width: thin;
    grid-template-columns: [bin] 52px [item] minmax(140px, 1fr) [counted] 128px [sys] 64px [var] minmax(96px, 128px); column-gap: 12px;
    background: repeating-linear-gradient(transparent 0 37px, color-mix(in oklch, var(--apo-count-accent) 7%, transparent) 37px 38px); background-attachment: local; }
  & .apo-count-cols { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; position: sticky; top: 0; z-index: 2; padding: 12px 8px 8px; margin: 0 -8px; background: var(--apo-count-bg); border-bottom: 2px solid var(--apo-count-ink);
    font-size: 10.5px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apo-count-mute);
    & span:nth-child(n+3) { text-align: right; }
  }
  & .apo-count-rows { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; list-style: none; margin: 0; padding: 0; }
  & .apo-count-row { grid-column: 1 / -1; display: grid; grid-template-columns: subgrid; align-items: center; padding: 8px; margin: 0 -8px; border-bottom: 1px solid var(--apo-count-line); border-radius: 8px; transition: background .3s;
    &:focus-within { background: var(--apo-count-panel); }
    &[data-flag] { background: color-mix(in oklch, var(--apo-count-hi) 38%, transparent); }
    &[data-flag]:focus-within { background: color-mix(in oklch, var(--apo-count-hi) 55%, var(--apo-count-panel)); }
    & .bin { font: 700 12px/1 var(--apo-count-mono); color: var(--apo-count-mute); }
    & .nm { font-weight: 650; font-size: 13.5px; line-height: 1.2; }
    & .sk { font: 500 11px/1.3 var(--apo-count-mono); color: var(--apo-count-mute); }
    & .sk b { font-family: system-ui, sans-serif; font-weight: 750; font-size: 10px; letter-spacing: .06em; text-transform: uppercase; padding: 1px 5px; border-radius: 4px; color: var(--apo-count-ink); background: var(--apo-count-hi); margin-left: 4px; }
