    & .ct svg { width: 13px; height: 13px; stroke-width: 2.4; }
    & input { width: 58px; height: 32px; text-align: right; padding: 0 8px; border-radius: 7px; border: 1px solid var(--apo-count-line2); background: var(--apo-count-panel); font: 700 15px/1 var(--apo-count-mono); font-variant-numeric: tabular-nums; outline: none; transition: border-color .2s, box-shadow .2s; }
    & input:focus-visible { border-color: var(--apo-count-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apo-count-accent) 18%, transparent); }
    & input:placeholder-shown { background: repeating-linear-gradient(135deg, var(--apo-count-sunk) 0 4px, var(--apo-count-panel) 4px 8px); }
    & input:disabled { background: transparent; border-color: transparent; opacity: 1; }
    & .sys { text-align: right; font: 700 15px/1 var(--apo-count-mono); font-variant-numeric: tabular-nums; perspective: 300px; }
    & .sys span { display: inline-block; transform-origin: 50% 50%; }
    & .sys .blind { color: var(--apo-count-mute); letter-spacing: .1em; font-weight: 500; }
    & .sys .flip { animation: apo-count-flip .6s var(--apo-count-ease) both; animation-delay: calc(var(--i) * 55ms); }
    & .vr { display: grid; justify-items: end; gap: 1px; font-variant-numeric: tabular-nums; }
    & .vr b { font: 750 13px/1.1 var(--apo-count-mono); }
    & .vr small { font-size: 11.5px; color: var(--apo-count-mute); }
    & .vr[data-s="neg"] b { color: var(--apo-count-short); } & .vr[data-s="pos"] b { color: var(--apo-count-accent); } & .vr[data-s="zero"] b { color: var(--apo-count-good); }
    & .vr .pend { font-size: 11.5px; color: var(--apo-count-mute); }
  }

  /* variance panel */
  & .apo-count-var { grid-area: var; min-height: 0; overflow: auto; display: grid; grid-auto-rows: max-content; align-content: start; gap: 14px; padding: 14px 16px 16px; border-left: 1px solid var(--apo-count-line); background: var(--apo-count-panel); scrollbar-width: thin; }
  & .apo-count-lock { display: grid; justify-items: center; gap: 12px; text-align: center; padding: 18px 10px 6px;
    & .ring { position: relative; width: 120px; height: 120px; border-radius: 50%; display: grid; place-items: center;
      background: conic-gradient(var(--apo-count-ink) calc(var(--apo-count-p) * 1turn), var(--apo-count-sunk) 0); transition: --apo-count-p .7s var(--apo-count-spring); }
    & .ring::before { content: ""; position: absolute; inset: 9px; border-radius: 50%; background: var(--apo-count-panel); }
    & .ring b { position: relative; font-size: 28px; font-weight: 800; letter-spacing: -.03em; font-variant-numeric: tabular-nums; line-height: 1; }
