  }
  & .apo-count-acts { display: grid; gap: 8px; }
  & .apo-count-stats { display: grid; grid-template-columns: repeat(3, 1fr); gap: 1px; border-radius: 12px; overflow: hidden; background: var(--apo-count-line); border: 1px solid var(--apo-count-line);
    & div { padding: 10px; background: var(--apo-count-panel); }
