    & b { font-size: clamp(14px, 1.5cqi, 17px); font-weight: 800; letter-spacing: -.02em; font-variant-numeric: tabular-nums; white-space: nowrap; }
    & [data-s="neg"] b { color: var(--apo-count-short); }
  }
  & .apo-count-tol { display: grid; gap: 8px; padding: 10px 12px; border-radius: 12px; background: var(--apo-count-sunk);
    & label { display: grid; grid-template-columns: 1fr auto; gap: 2px 8px; align-items: center; font-size: 12px; font-weight: 650; }
    & output { font: 700 12px/1 var(--apo-count-mono); }
    & input { grid-column: 1 / -1; width: 100%; margin: 0; }
    & p { font-size: 11.5px; color: var(--apo-count-mute); }
  }
  & .apo-count-chart { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; position: relative;
    & li { display: grid; grid-template-columns: minmax(0, 8.5em) minmax(0, 1fr) 4.6em; align-items: center; gap: 8px; font-size: 12px; padding: 3px 4px; border-radius: 6px; }
    & li[data-flag] { background: color-mix(in oklch, var(--apo-count-hi) 45%, transparent); }
