    & .v[data-s="neg"] { color: var(--apo-count-short); } & .v[data-s="pos"] { color: var(--apo-count-accent); }
  }
  & .apo-count-axis { display: grid; grid-template-columns: minmax(0, 8.5em) minmax(0, 1fr) 4.6em; gap: 8px; font-size: 10.5px; color: var(--apo-count-mute); padding: 0 4px;
