    & .stamp { justify-self: start; font: 800 11px/1 var(--apo-count-mono); letter-spacing: .14em; padding: 6px 9px; border-radius: 6px; color: white; background: var(--apo-count-good); }
    & p { font-size: 13px; }
  }

  & .apo-count-keys { grid-area: keys; display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 8px 16px; font-size: 11.5px; color: var(--apo-count-mute); border-top: 1px solid var(--apo-count-line);
    & span { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
  }
  & .apo-count-toast { position: absolute; left: 50%; bottom: 46px; z-index: 9; padding: 10px 14px; border-radius: 10px; color: var(--apo-count-panel); background: var(--apo-count-ink); font-size: 13px; font-weight: 600; white-space: nowrap; max-width: calc(100% - 24px); overflow: hidden; text-overflow: ellipsis;
