    & .apo-count-cols { animation: apo-count-shadow linear both; animation-timeline: scroll(nearest); animation-range: 0 30px; }
  }
}

@property --apo-count-p { syntax: "<number>"; inherits: true; initial-value: 0; }
@keyframes apo-count-flip { from { transform: rotateX(90deg); opacity: 0; } to { transform: none; opacity: 1; } }
@keyframes apo-count-grow { from { scale: 0 1; } }
@keyframes apo-count-shadow { to { box-shadow: 0 10px 12px -12px color-mix(in oklch, black 50%, transparent); } }

@container apo-count (width < 960px) {
  .apo-count .apo-count-app { grid-template: "head head" auto "map var" auto "sheet var" minmax(0, 1fr) "keys keys" auto / minmax(0, 1fr) clamp(270px, 36cqi, 320px); }
  .apo-count .apo-count-map { display: block; overflow: visible; padding: 10px 16px 2px; border-right: 0; }
  .apo-count .apo-count-bays { grid-auto-flow: column; grid-auto-columns: minmax(84px, 1fr); gap: 6px; overflow-x: auto; scrollbar-width: none; padding: 2px; }
  .apo-count .apo-count-bay { padding: 6px 8px 7px; gap: 5px; }
  .apo-count .apo-count-bay .shelf i { height: 12px; }
  .apo-count .apo-count-bay .shelf i[data-s="flag"] { height: 14px; }
  .apo-count .apo-count-who { display: none; }
  .apo-count .apo-count-phases li { padding-right: 6px; font-size: 0; gap: 0; }
  .apo-count .apo-count-sheet { grid-template-columns: [bin] 44px [item] minmax(110px, 1fr) [counted] 120px [sys] 52px [var] 84px; column-gap: 8px; }
}
@container apo-count (width < 760px) {
  .apo-count .apo-count-app { grid-template: "head" auto "nav" auto "map" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
