  .apo-count[data-view="var"] .apo-count-map { display: none; }
  .apo-count .apo-count-keys, .apo-count .apo-count-phases { display: none; }
  .apo-count .apo-count-nav { grid-area: nav; display: flex; gap: 4px; padding: 6px 12px; border-bottom: 1px solid var(--apo-count-line);
    & button { flex: 1; height: 34px; border-radius: 9px; font-weight: 700; font-size: 13px; color: var(--apo-count-mute); }
    & button[aria-selected="true"] { color: var(--apo-count-panel); background: var(--apo-count-ink); }
  }
