  .apo-count[data-view="sheet"] .apo-count-var, .apo-count[data-view="var"] .apo-count-sheet { display: none; }
  .apo-count .apo-count-sheet { padding: 0 12px 12px; grid-template-columns: [bin] 0 [item] minmax(0, 1fr) [counted] auto; column-gap: 8px; }
  .apo-count .apo-count-cols { display: none; }
