}

@media (prefers-reduced-motion: reduce) {
  .apo-count *, .apo-count *::before, .apo-count *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-delay: 0s !important; }
  .apo-count .apo-count-cols { animation: none; }
}

js:
/* Cycle count CC-1043. Blind until submitted: system quantities stay masked so the count is
   not anchored to the screen. On submit they flip in row by row, the variance bars grow out of
   the zero line, and the chart re-sorts by value impact with a FLIP. Recounts go blind again. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const usd = (c, sign) => (c < 0 ? '−' : sign && c > 0 ? '+' : '') + '$' + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const IC = { minus: '<path d="M6 12h12"/>', plus: '<path d="M12 6v12M6 12h12"/>', lock: '<rect x="5" y="10.5" width="14" height="9.5" rx="2"/><path d="M8.5 10.5V8a3.5 3.5 0 0 1 7 0v2.5"/>', redo: '<path d="M4 12a8 8 0 1 0 2.4-5.7L4 8.5"/><path d="M4 4v4.5h4.5"/>' };
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';

const ROWS = [
  ['7A-1', 'TW-30112', 'Salmon Pâté 3 oz can', 96, 88, 91], ['7A-2', 'TW-30240', 'Chicken & Rice Kibble 4 lb', 14, 710, 14], ['7A-3', 'TW-30118', 'Turkey Stew 5.5 oz can', 72, 105, 75], ['7A-4', 'TW-30255', 'Grain-Free Kibble 12 lb', 8, 2140, 6],
  ['7B-1', 'TW-41020', 'Clumping Litter 20 lb', 22, 960, 22], ['7B-2', 'TW-41034', 'Pine Pellet Litter 30 lb', 9, 825, 11], ['7B-3', 'TW-41101', 'Litter Liners, 10', 31, 240, 31],
  ['7C-1', 'TW-52007', 'Catnip Mice, 3-pack', 40, 170, 38], ['7C-2', 'TW-52015', 'Feather Wand Toy', 18, 320, 18], ['7C-3', 'TW-52040', 'Sisal Scratch Pad', 12, 690, 12], ['7C-4', 'TW-52066', 'Dental Treats 3 oz', 55, 195, 49],
  ['7D-1', 'TW-63002', 'Ceramic Bowl, Speckled', 16, 480, 16], ['7D-2', 'TW-63019', 'Fountain Filters, 4-pack', 23, 360, 24], ['7D-3', 'TW-63044', 'Tuna Flake Topper 1 oz', 64, 125, null]
].map(([bin, sku, name, sys, cost, count], i) => ({ i, bin, sku, name, sys, cost, count, re: 0, first: null, pending: false }));
const BAYS = ['7A', '7B', '7C', '7D'];

const S = { phase: 'count', bay: 'all', tolP: 5, tolD: 2000, view: 'sheet', adj: null };
const hist = [];
const remember = label => { hist.push({ s: JSON.stringify(ROWS.map(r => [r.count, r.re, r.first, r.pending])), label }); if (hist.length > 60) hist.shift(); };

const v = r => r.count == null || r.pending ? null : r.count - r.sys;
const vd = r => v(r) == null ? null : v(r) * r.cost;
const flagged = r => { const u = v(r); if (!u) return false; const pct = Math.abs(u) / Math.max(1, r.sys) * 100; return pct > S.tolP || Math.abs(u * r.cost) > S.tolD; };
const uncounted = () => ROWS.filter(r => r.count == null);
let syncSku = null; // a +/- while the field has focus must still rewrite its value

/* ── sheet rows: keyed, patched in place so inputs keep focus and caret ── */
function rowShell(r) {
  const li = document.createElement('li');
  li.className = 'apo-count-row'; li.dataset.sku = r.sku; li.style.setProperty('--i', r.i);
  li.innerHTML = `<span class="bin">${r.bin}</span><div class="it"><div class="nm">${esc(r.name)}</div><div class="sk">${r.sku} · ${usd(r.cost)} cost<span data-tag></span></div></div>
    <div class="ct"><button type="button" data-act="adj" data-d="-1" data-sku="${r.sku}" data-k="m-${r.sku}" aria-label="One fewer ${esc(r.name)}">${svg('minus')}</button>
    <input inputmode="numeric" autocomplete="off" placeholder=" " aria-label="Counted ${esc(r.name)}" data-sku="${r.sku}" data-k="in-${r.sku}">
    <button type="button" data-act="adj" data-d="1" data-sku="${r.sku}" data-k="p-${r.sku}" aria-label="One more ${esc(r.name)}">${svg('plus')}</button></div>
    <div class="sys"></div><div class="vr"></div>`;
  return li;
}
function patchRow(li, r, reveal) {
  const posted = S.phase === 'posted', blind = S.phase === 'count' || r.pending;
  const inp = $('input', li);
  const want = r.count == null ? '' : String(r.count);
  if (inp.value !== want && (document.activeElement !== inp || syncSku === r.sku)) inp.value = want;
  inp.disabled = posted;
  const [mb, pb] = $$('.ct button', li);
  mb.disabled = posted || !r.count; mb.title = posted ? 'Adjustments posted' : !r.count ? 'Count is already zero or blank' : '';
  pb.disabled = posted; pb.title = posted ? 'Adjustments posted' : '';
  $('[data-tag]', li).innerHTML = r.pending ? '<b>Recount</b>' : r.re ? `<b style="background:var(--apo-count-sunk)">1st ${r.first}</b>` : '';
  const sys = $('.sys', li);
  const sysHTML = blind ? '<span class="blind" title="Hidden during a blind count">•••</span>' : `<span class="${reveal ? 'flip' : ''}">${r.sys}</span>`;
  if (sys.__h !== (blind ? 'b' : 's') || reveal) { sys.innerHTML = sysHTML; sys.__h = blind ? 'b' : 's'; }
  const vr = $('.vr', li), u = v(r);
  let vh, s = '';
  if (blind) vh = `<span class="pend">${r.pending ? (r.count == null ? 'recount' : 'Enter to reveal') : r.count == null ? 'not counted' : 'counted'}</span>`;
  else if (u == null) vh = '<span class="pend">—</span>';
  else { s = u < 0 ? 'neg' : u > 0 ? 'pos' : 'zero'; vh = `<b>${u > 0 ? '+' : u < 0 ? '−' : '±'}${Math.abs(u)}</b><small>${u ? usd(u * r.cost, true) : 'match'}</small>${S.phase === 'review' && flagged(r) ? `<button type="button" class="apo-count-ghost" style="height:24px;padding:0 8px;font-size:11.5px;margin-top:3px" data-act="recount" data-sku="${r.sku}" data-k="rc-${r.sku}">${svg('redo')}Recount</button>` : ''}`; }
  vr.dataset.s = s;
  if (vr.__h !== vh) { vr.innerHTML = vh; vr.__h = vh; }
  li.toggleAttribute('data-flag', S.phase !== 'count' && !r.pending && flagged(r));
  li.hidden = S.bay !== 'all' && !r.bin.startsWith(S.bay);
}
function renderRows(reveal) {
  const ol = $('.apo-count-rows');
  ROWS.forEach(r => {
    let li = ol.querySelector('[data-sku="' + r.sku + '"]');
    if (!li) { li = rowShell(r); ol.appendChild(li); }
    patchRow(li, r, reveal);
  });
}
function renderBays() {
  const box = $('.apo-count-bays');
  const tile = (id, rows) => {
    const done = rows.filter(r => r.count != null && !r.pending).length;
    return `<button type="button" class="apo-count-bay" role="tab" data-act="bay" data-id="${id}" data-k="bay-${id}" aria-selected="${S.bay === id}" ${id === 'all' ? 'data-all' : ''}>
      <span class="t">${id === 'all' ? 'All of aisle 7' : 'Bay ' + id}<span>${done}/${rows.length}</span></span>
      <span class="shelf">${rows.map(r => `<i data-s="${r.pending ? 're' : r.count == null ? '' : S.phase === 'count' ? 'done' : flagged(r) ? 'flag' : 'ok'}" title="${r.bin} ${esc(r.name)}"></i>`).join('')}</span></button>`;
  };
  const html = tile('all', ROWS) + BAYS.map(b => tile(b, ROWS.filter(r => r.bin.startsWith(b)))).join('');
  if (box.__h !== html) { box.innerHTML = html; box.__h = html; }
}

/* ── variance panel ── */
function stats() {
  const c = ROWS.filter(r => v(r) != null);
  const net = c.reduce((a, r) => a + vd(r), 0), gross = c.reduce((a, r) => a + Math.abs(vd(r)), 0);
  const ok = c.filter(r => !flagged(r)).length;
  return { counted: c.length, net, gross, acc: c.length ? Math.round(ok / c.length * 1000) / 10 : 0, flags: c.filter(flagged).length, pending: ROWS.filter(r => r.pending).length, exact: c.filter(r => v(r) === 0).length };
}
function renderVar(reveal) {
  const box = $('.apo-count-var');
  if (S.phase === 'count') {
    const n = ROWS.length - uncounted().length;
    if (!box.querySelector('.apo-count-lock')) box.innerHTML = `<div class="apo-count-lock"><div class="ring"><b><span data-n></span><small>of ${ROWS.length} counted</small></b></div>
      <h3>${svg('lock')}Blind count</h3><p>System quantities stay hidden until you submit, so nobody counts toward the number on screen.</p></div>
      <div class="apo-count-acts"><button type="button" class="apo-count-ghost" data-act="zero" data-k="zero"></button><button type="button" class="apo-count-solid" data-act="submit" data-k="submit">Submit count <kbd>F</kbd></button></div>`;
    $('.ring', box).style.setProperty('--apo-count-p', (n / ROWS.length).toFixed(3));
    $('[data-n]', box).textContent = n;
    const z = $('[data-act="zero"]', box), left = uncounted().length;
    z.textContent = left ? `Count 0 for the ${left} left` : 'Every item is counted';
    z.disabled = !left; z.title = left ? 'Record zero on hand for items you could not find' : 'Nothing left to count';
    const sb = $('[data-act="submit"]', box); sb.disabled = !!left; sb.title = left ? left + ' item' + (left > 1 ? 's' : '') + ' still to count' : 'Reveal system quantities and variances (F)';
    return;
  }
  const st = stats();
  if (!box.querySelector('.apo-count-stats')) box.innerHTML = `<div class="apo-count-stats"><div data-st="net"><span>Net</span><b></b></div><div><span>Gross</span><b data-st="gross"></b></div><div><span>Accuracy</span><b data-st="acc"></b></div></div>
    <div class="apo-count-tol"><label>Recount if off by more than<output data-o="p"></output><input type="range" min="0" max="25" step="1" data-tol="p" aria-label="Percent tolerance"></label>
      <label>or by more than<output data-o="d"></output><input type="range" min="500" max="5000" step="250" data-tol="d" aria-label="Dollar tolerance"></label><p data-st="note"></p></div>
    <div class="apo-count-axis" aria-hidden="true"><span>Variance at cost</span><span><span data-ax="lo"></span><span>0</span><span data-ax="hi"></span></span><span></span></div>
    <ol class="apo-count-chart" aria-label="Variance by item, largest value first"></ol><div class="apo-count-acts" data-acts></div>`;
  const pin = $('[data-tol="p"]', box), din = $('[data-tol="d"]', box);
  if (document.activeElement !== pin) pin.value = S.tolP; if (document.activeElement !== din) din.value = S.tolD;
  $('[data-o="p"]', box).textContent = S.tolP + '%'; $('[data-o="d"]', box).textContent = usd(S.tolD);
  const nb = $('[data-st="net"]', box); nb.dataset.s = st.net < 0 ? 'neg' : ''; $('b', nb).textContent = usd(st.net, true);
  $('[data-st="gross"]', box).textContent = usd(st.gross); $('[data-st="acc"]', box).textContent = st.acc + '%';
  $('[data-st="note"]', box).textContent = `${st.flags} flagged · ${st.exact} exact · ${st.counted - st.exact - st.flags} within tolerance${st.pending ? ' · ' + st.pending + ' awaiting recount' : ''}`;
  // chart: keyed rows, re-sorted by |value| with a FLIP
  const ol = $('.apo-count-chart', box);
  const list = ROWS.filter(r => vd(r)).sort((a, b) => Math.abs(vd(b)) - Math.abs(vd(a)));
  const max = Math.max(1, ...list.map(r => Math.abs(vd(r))));
  $('[data-ax="lo"]', box).textContent = usd(-max).replace('.00', ''); $('[data-ax="hi"]', box).textContent = usd(max, true).replace('.00', '');
  const first = new Map($$(':scope > li', ol).map(li => [li.dataset.sku, li.getBoundingClientRect().top]));
  const want = new Set(list.map(r => r.sku));
  $$(':scope > li', ol).forEach(li => { if (!want.has(li.dataset.sku)) li.remove(); });
  list.forEach((r, k) => {
    let li = ol.querySelector(':scope > li[data-sku="' + r.sku + '"]');
    if (!li) { li = document.createElement('li'); li.dataset.sku = r.sku; li.innerHTML = `<span class="lb"></span><span class="tr"><i></i></span><span class="v"></span>`; }
    const s = vd(r) < 0 ? 'neg' : 'pos', i = $('i', li);
    $('.lb', li).textContent = r.name; $('.lb', li).title = r.bin + ' ' + r.name;
    i.dataset.s = s; i.style.setProperty('--w', (Math.abs(vd(r)) / max).toFixed(3)); i.style.setProperty('--i', k);
    $('.v', li).textContent = usd(vd(r), true); $('.v', li).dataset.s = s;
    li.toggleAttribute('data-flag', flagged(r));
    if (ol.children[k] !== li) ol.insertBefore(li, ol.children[k] || null);
  });
  if (!RM.matches) $$(':scope > li', ol).forEach(li => {
    const y0 = first.get(li.dataset.sku); if (y0 == null) return;
    const dy = y0 - li.getBoundingClientRect().top;
    if (Math.abs(dy) > 1) li.animate([{ transform: `translateY(${dy}px)` }, { transform: 'none' }], { duration: 520, easing: 'cubic-bezier(.2,.8,.2,1)' });
  });
  const acts = $('[data-acts]', box);
  const ah = S.phase === 'posted'
    ? `<div class="apo-count-posted"><span class="stamp">${S.adj}</span><p>Stock adjusted by <b>${usd(st.net, true)}</b> at cost across ${st.counted - st.exact} items. Gross variance ${usd(st.gross)}, accuracy ${st.acc}%.</p></div>
       <button type="button" class="apo-count-ghost" data-act="print" data-k="print">Print variance report</button><button type="button" class="apo-count-solid" data-act="restart" data-k="restart">Start a new count</button>`
    : `<button type="button" class="apo-count-ghost" data-act="recountall" data-k="recountall" ${st.flags ? '' : 'disabled title="Nothing is outside tolerance"'}>${svg('redo')}Recount ${st.flags} flagged</button>
       <button type="button" class="apo-count-solid" data-act="approve" data-k="approve" ${st.pending ? `disabled title="${st.pending} recount${st.pending > 1 ? 's' : ''} still open"` : ''}>Approve ${usd(st.net, true)} adjustment</button>`;
  if (acts.__h !== ah) { acts.innerHTML = ah; acts.__h = ah; }
}
function renderHead() {
  root.dataset.phase = S.phase; root.dataset.view = S.view;
  const u = $('[data-act="undo"]');
  u.disabled = !hist.length || S.phase === 'posted';
  u.title = S.phase === 'posted' ? 'Adjustments are posted' : hist.length ? 'Undo ' + hist[hist.length - 1].label + ' (' + MOD + 'Z)' : 'Nothing to undo yet';
  const st = stats();
  $('.apo-count-nav').innerHTML = [['sheet', 'Count sheet · ' + (ROWS.length - uncounted().length) + '/' + ROWS.length], ['var', S.phase === 'count' ? 'Variances · locked' : 'Variances · ' + st.flags + ' flagged']].map(([id, l]) =>
    `<button type="button" role="tab" data-act="view" data-id="${id}" data-k="nv-${id}" aria-selected="${S.view === id}">${l}</button>`).join('');
}
function keep(fn) {
  const a = root.contains(document.activeElement) ? document.activeElement : null, k = a && a.dataset.k;
  fn();
  if (k) { const n = root.querySelector('[data-k="' + CSS.escape(k) + '"]'); if (n && n !== document.activeElement && !n.disabled) n.focus({ preventScroll: true }); }
}
function render(reveal) { keep(() => { renderRows(reveal); renderBays(); renderVar(reveal); renderHead(); }); }
let tt = 0;
function toast(m) { const t = $('.apo-count-toast'); t.textContent = m; t.setAttribute('data-on', ''); clearTimeout(tt); tt = setTimeout(() => t.removeAttribute('data-on'), 2800); }

/* ── actions ── */
const row = sku => ROWS.find(r => r.sku === sku);
function setCount(r, n, label) {
  if (S.phase === 'posted') return;
  remember(label || 'count ' + r.sku);
  r.count = n == null ? null : Math.max(0, Math.min(9999, n));
  if (S.phase === 'review' && r.pending && r.count != null && label !== 'typing') r.pending = false;
  syncSku = r.sku; render(); syncSku = null;
}
function submit() {
  if (S.phase !== 'count' || uncounted().length) return;
  S.phase = 'review'; hist.length = 0; render(true);
  const st = stats();
  toast(`Count submitted · ${st.flags} item${st.flags === 1 ? '' : 's'} outside tolerance`);
  if (root.clientWidth < 760) { S.view = 'var'; render(); }
}
function recount(r) {
  if (S.phase !== 'review' || r.pending) return;
  remember('recount ' + r.sku);
  r.first = r.count; r.count = null; r.re++; r.pending = true;
  render();
}
function undo() { const h = hist.pop(); if (!h || S.phase === 'posted') return; JSON.parse(h.s).forEach((x, i) => { [ROWS[i].count, ROWS[i].re, ROWS[i].first, ROWS[i].pending] = x; }); render(); toast('Undid ' + h.label); }

root.addEventListener('click', e => {
  const b = e.target.closest('[data-act]'); if (!b || !root.contains(b) || b.disabled) return;
  const a = b.dataset.act;
  if (a === 'adj') { const r = row(b.dataset.sku); setCount(r, (r.count || 0) + +b.dataset.d, 'adjust ' + r.sku); }
  else if (a === 'bay') { S.bay = b.dataset.id; render(); }
  else if (a === 'zero') { remember('zero remaining'); uncounted().forEach(r => { r.count = 0; }); render(); toast('Recorded 0 on hand for the remaining items'); }
  else if (a === 'submit') submit();
  else if (a === 'recount') recount(row(b.dataset.sku));
  else if (a === 'recountall') { remember('recount flagged'); ROWS.filter(r => flagged(r) && !r.pending).forEach(r => { r.first = r.count; r.count = null; r.re++; r.pending = true; }); render(); const f = ROWS.find(r => r.pending); if (f) { const i = root.querySelector('[data-k="in-' + f.sku + '"]'); if (i) i.focus(); } }
  else if (a === 'approve') { const st = stats(); if (st.pending) return; S.phase = 'posted'; S.adj = 'ADJ-7741'; render(); toast('Posted ADJ-7741 · ' + usd(st.net, true) + ' at cost'); }
  else if (a === 'print') { b.textContent = 'Report sent to the back-office printer'; b.disabled = true; b.title = 'Already printed'; }
  else if (a === 'restart') { ROWS.forEach(r => { r.count = null; r.re = 0; r.first = null; r.pending = false; }); S.phase = 'count'; S.adj = null; hist.length = 0; $('.apo-count-var').innerHTML = ''; render(); toast('CC-1044 started · aisle 7 blind count'); const f = root.querySelector('.apo-count-row input'); if (f) f.focus(); }
  else if (a === 'undo') undo();
  else if (a === 'view') { S.view = b.dataset.id; render(); }
});
root.addEventListener('input', e => {
  const t = e.target;
  if (t.dataset.tol) { if (t.dataset.tol === 'p') S.tolP = +t.value; else S.tolD = +t.value; render(); return; }
  if (!t.dataset.sku) return;
  const clean = t.value.replace(/\D/g, '').slice(0, 4);
  if (clean !== t.value) t.value = clean;
  const r = row(t.dataset.sku);
  const n = clean === '' ? null : +clean;
  if (n === r.count) return;
  if (S.phase === 'count') { remember('count ' + r.sku); r.count = n; render(); }
  else if (S.phase === 'review') { r.count = n; if (!r.pending) render(); else { renderBays(); renderVar(); } }
});
root.addEventListener('change', e => {
  const t = e.target; if (!t.dataset || !t.dataset.sku || t.tagName !== 'INPUT') return;
  const r = row(t.dataset.sku);
  if (S.phase === 'review' && r.pending && r.count != null) { r.pending = false; keep(() => { renderRows(); const li = root.querySelector('.apo-count-row[data-sku="' + r.sku + '"]'); patchRow(li, r, true); renderBays(); renderVar(); renderHead(); }); toast(`${r.name}: recount ${r.count}, first count ${r.first}, system ${r.sys}`); }
});
root.addEventListener('keydown', e => {
  const t = e.target, k = e.key;
  if ((e.metaKey || e.ctrlKey) && k.toLowerCase() === 'z') { undo(); e.preventDefault(); return; }
  if (e.altKey && /^[1-4]$/.test(k)) { S.bay = BAYS[+k - 1]; render(); e.preventDefault(); return; }
  if (e.altKey && k === '0') { S.bay = 'all'; render(); e.preventDefault(); return; }
  const inRow = t.tagName === 'INPUT' && t.dataset.sku;
  if (inRow) {
    const vis = $$('.apo-count-row:not([hidden]) input'), i = vis.indexOf(t);
    if (k === 'Enter' || k === 'ArrowDown' || k === 'ArrowUp') {
      t.dispatchEvent(new Event('change', { bubbles: true }));
      const n = vis[i + (k === 'ArrowUp' ? -1 : 1)];
      if (n) { n.focus(); n.select(); n.closest('li').scrollIntoView({ block: 'nearest' }); }
      else if (k === 'Enter' && S.phase === 'count' && !uncounted().length) { const sb = $('[data-act="submit"]'); if (sb) sb.focus(); }
      e.preventDefault(); return;
    }
    if (k === '+' || k === '-') { const r = row(t.dataset.sku); setCount(r, (r.count || 0) + (k === '+' ? 1 : -1), 'adjust ' + r.sku); e.preventDefault(); return; }
    if ((k === 'r' || k === 'R') && S.phase === 'review') { recount(row(t.dataset.sku)); e.preventDefault(); return; }
    return;
  }
  if (t.tagName === 'INPUT' || e.metaKey || e.ctrlKey || e.altKey) return;
  if (k === 'f' || k === 'F') { submit(); e.preventDefault(); }
  else if (k === 'ArrowDown' || k === 'ArrowUp') { const f = $('.apo-count-row:not([hidden]) input:not(:disabled)'); if (f) { f.focus(); f.select(); } e.preventDefault(); }
  else if ((k === 'r' || k === 'R') && S.phase === 'review') { const li = t.closest && t.closest('.apo-count-row'); if (li) recount(row(li.dataset.sku)); }
});

render();

css:
.apo-shift {
  --apo-shift-bg: oklch(0.205 0.02 42);
  --apo-shift-ink: oklch(0.94 0.016 75);
  --apo-shift-accent: oklch(0.8 0.12 168);
  --apo-shift-brass: oklch(0.79 0.1 82);
  --apo-shift-warn: oklch(0.7 0.16 32);
  --apo-shift-panel: color-mix(in oklch, var(--apo-shift-bg), black 18%);
  --apo-shift-card: color-mix(in oklch, var(--apo-shift-bg), var(--apo-shift-ink) 7%);
  --apo-shift-line: color-mix(in oklch, var(--apo-shift-ink) 10%, transparent);
  --apo-shift-line2: color-mix(in oklch, var(--apo-shift-ink) 20%, transparent);
