/* Bramble Street front register, closing count. The drawer is drawn from above: each
   compartment is a button whose bill stack or coin pile grows with its count. Expected cash is
   float + cash sales − refunds − paid-outs − safe drops, and stays hidden until the count is
   submitted. The timeline is the same ledger drawn as a level over the day. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const MOD = /Mac|iP/.test(navigator.platform || navigator.userAgent) ? '⌘' : 'Ctrl';
$$('[data-mod]').forEach(k => { k.textContent = MOD; });
const usd = (c, sign) => (c < 0 ? '−' : sign && c > 0 ? '+' : '') + '$' + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const clock = m => { const h = Math.floor(m / 60), mm = String(m % 60).padStart(2, '0'); return ((h + 11) % 12 + 1) + ':' + mm + (h < 12 ? ' AM' : ' PM'); };
const IC = { minus: '<path d="M6 12h12"/>', plus: '<path d="M12 6v12M6 12h12"/>', x: '<path d="M7 7l10 10M17 7 7 17"/>' };
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';

const DEN = [
  { k: 'b100', lab: '$100', v: 10000, row: 'under', step: 1 }, { k: 'b1', lab: '$1', v: 100, row: 'bills', step: 25 }, { k: 'b5', lab: '$5', v: 500, row: 'bills', step: 5 }, { k: 'b10', lab: '$10', v: 1000, row: 'bills', step: 5 },
  { k: 'b20', lab: '$20', v: 2000, row: 'bills', step: 5 }, { k: 'b50', lab: '$50', v: 5000, row: 'bills', step: 1 },
