/* ── ledger ── */
function salesTo(t) { // cash sales booked by minute t, spread evenly across each half hour
  let s = 0;
  SALES.forEach((a, i) => { const t0 = OPEN + i * 30, t1 = Math.min(t0 + 30, S.now), dur = Math.min(30, 881 - t0); if (t <= t0) return; s += a * Math.min(1, (Math.min(t, t1) - t0) / dur); });
