/* ── tray ── */
function coinPos(n, d) { const out = []; for (let i = 0; i < n; i++) { const a = i * 2.39996, r = Math.sqrt(i) * d * .42; out.push([Math.cos(a) * r, Math.sin(a) * r * .8]); } return out; }
