/* ── timeline ── */
function renderChart() {
  const W = 360, H = 168, P = { l: 34, r: 8, t: 10, b: 20 };
  const pts = [], steps = new Set([OPEN, ...SALES.map((_, i) => OPEN + i * 30), S.now, ...S.events.map(e => e.t)]);
  [...steps].filter(t => t <= S.now).sort((a, b) => a - b).forEach(t => { pts.push([t, level(t, false)]); pts.push([t, level(t, true)]); });
  const max = Math.max(LIMIT * 1.35, ...pts.map(p => p[1])) * 1.05;
  const X = t => P.l + (t - OPEN) / (END - OPEN) * (W - P.l - P.r), Y = v => H - P.b - v / max * (H - P.t - P.b);
  const line = pts.map((p, i) => (i ? 'L' : 'M') + X(p[0]).toFixed(1) + ' ' + Y(p[1]).toFixed(1)).join(' ');
  const area = line + ` L${X(S.now).toFixed(1)} ${Y(0)} L${X(OPEN)} ${Y(0)} Z`;
  let over = 0, bands = [], st = null;
  for (let t = OPEN; t <= S.now; t++) { const o = level(t) > LIMIT; if (o) over++; if (o && st == null) st = t; if ((!o || t === S.now) && st != null) { bands.push([st, t]); st = null; } }
  const grid = [20000, 40000, 60000].filter(v => v < max).map(v => `<line class="grid" x1="${P.l}" x2="${W - P.r}" y1="${Y(v)}" y2="${Y(v)}"/><text x="${P.l - 5}" y="${Y(v) + 3}" text-anchor="end">$${v / 100}</text>`).join('');
  const hours = [420, 540, 660, 780, 900].map(t => `<text x="${X(t)}" y="${H - 5}" text-anchor="middle">${clock(t).replace(':00', '').replace(' AM', 'a').replace(' PM', 'p')}</text>`).join('');
  const marks = S.events.map(e => `<g class="mk" role="button" tabindex="0" data-act="ev" data-id="${e.id}" aria-pressed="${S.ev === e.id}" aria-label="${clock(e.t)} ${esc(e.label)}" style="--c:${COL[e.kind]}"><circle cx="${X(e.t)}" cy="${Y(level(e.t))}" r="4.5"/></g>`).join('');
  $('.apo-shift-chart').innerHTML = `<h3><span>Drawer level today</span><b>${over ? Math.floor(over / 60) + ' h ' + over % 60 + ' min over the $' + LIMIT / 100 + ' drop limit' : 'Never over the drop limit'}</b></h3>
    <svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Cash in drawer from 7 AM to now">
      <defs><linearGradient id="${gid}" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="oklch(0.8 0.12 168)" stop-opacity=".32"/><stop offset="1" stop-color="oklch(0.8 0.12 168)" stop-opacity="0"/></linearGradient></defs>
      ${bands.map(([a, b]) => `<rect class="over" x="${X(a)}" y="${P.t}" width="${Math.max(1, X(b) - X(a))}" height="${H - P.t - P.b}"/>`).join('')}
      ${grid}<path d="${area}" fill="url(#${gid})" stroke="none"/><path class="lvl" d="${line}" pathLength="1"/>
      <line class="lim" x1="${P.l}" x2="${W - P.r}" y1="${Y(LIMIT)}" y2="${Y(LIMIT)}"/><text x="${W - P.r}" y="${Y(LIMIT) - 4}" text-anchor="end" style="fill:var(--apo-shift-warn)">drop limit</text>
      <line class="now" x1="${X(S.now)}" x2="${X(S.now)}" y1="${P.t}" y2="${H - P.b}"/><text x="${X(S.now)}" y="${P.t - 2}" text-anchor="middle" style="fill:var(--apo-shift-brass)">now</text>
      ${hours}${marks}</svg>`;
}
