/* ── counting ── */
function commit() { if (S.buf === '') return; S.counts[S.sel] = Math.min(9999, +S.buf); S.buf = ''; S.fresh = true; }
function select(k) { commit(); S.sel = k; S.buf = ''; S.fresh = true; render(false); }
function nextCell() { const order = DEN.map(d => d.k); const after = order.slice(order.indexOf(S.sel) + 1).concat(order); select(after.find(k => S.counts[k] == null && k !== S.sel) || order[(order.indexOf(S.sel) + 1) % order.length]); }
function typeKey(k) {
  if (S.phase !== 'count') return;
  if (k === 'Next') { commit(); nextCell(); return; }
  if (S.fresh && k !== '⌫') remember('count ' + D[S.sel].lab);
  if (k === '⌫') { S.buf = S.buf.slice(0, -1); S.fresh = !S.buf; }
  else { S.buf = (S.fresh ? '' : S.buf) + k; S.buf = S.buf.replace(/^0+(?=\d)/, '').slice(0, 4); S.fresh = false; }
  if (S.buf !== '') { S.counts[S.sel] = +S.buf; }
  render(false);
}
function bump(d) { commit(); remember('adjust ' + D[S.sel].lab); S.counts[S.sel] = Math.max(0, (S.counts[S.sel] || 0) + d); render(false); }
function move(dir) {
  const r = LAYOUT.findIndex(row => row.includes(S.sel)), c = LAYOUT[r].indexOf(S.sel);
  if (dir === 'ArrowLeft' || dir === 'ArrowRight') { const row = LAYOUT[r]; select(row[(c + (dir === 'ArrowRight' ? 1 : -1) + row.length) % row.length]); return; }
  const nr = Math.max(0, Math.min(LAYOUT.length - 1, r + (dir === 'ArrowDown' ? 1 : -1))); if (nr === r) return;
  const frac = LAYOUT[r].length > 1 ? c / (LAYOUT[r].length - 1) : .5;
  select(LAYOUT[nr][Math.round(frac * (LAYOUT[nr].length - 1))]);
}
function undo() { const h = hist.pop(); if (!h || S.phase !== 'count') return; Object.assign(S, JSON.parse(h.s)); S.buf = ''; S.fresh = true; render(); toast('Undid ' + h.label); }

/* ── sheets ── */
const sheetEl = $('.apo-shift-sheet');
function openSheet(html, focus) { sheetEl.innerHTML = html; sheetEl.hidden = false; const f = sheetEl.querySelector(focus || 'input, select, button'); if (f) f.focus({ preventScroll: true }); }
function closeSheet(ret) { sheetEl.hidden = true; sheetEl.innerHTML = ''; const n = ret && $('[data-k="' + ret + '"]'); if (n && !n.disabled) n.focus({ preventScroll: true }); }
let drop = { n: {}, bag: '', focus: '' };
function dropSheet() {
  if (S.phase !== 'count') return;
  commit();
  openSheet(`<form data-form="drop" novalidate><h3>Safe drop</h3><p>Pull large bills into a sealed bag for the safe. They come off the drawer count and the expected cash together.</p>
    <div class="dens">${['b100', 'b50', 'b20'].map(k => `<div><span>${D[k].lab}</span><span class="stp"><button type="button" data-act="dq" data-den="${k}" data-d="-1" data-k="dq-${k}" aria-label="One fewer ${D[k].lab}">${svg('minus')}</button><b data-n="${k}">0</b><button type="button" data-act="dq" data-den="${k}" data-d="1" data-k="dq+${k}" aria-label="One more ${D[k].lab}">${svg('plus')}</button></span><small>${S.counts[k] || 0} in drawer</small></div>`).join('')}</div>
    <div class="two"><label>Bag number<input name="bag" inputmode="numeric" maxlength="5" placeholder="5 digits" autocomplete="off" data-k="bag"></label><label>Total<input data-tot readonly tabindex="-1"></label></div>
    <p class="err" data-err></p><div class="row"><button type="button" class="apo-shift-ghost" data-act="cancel">Cancel</button><button type="submit" class="apo-shift-solid" data-go></button></div></form>`, '[data-k="dq+b20"]:not(:disabled), input[name="bag"]');
  patchDrop();
}
function patchDrop() {
  const f = sheetEl.querySelector('form[data-form="drop"]'); if (!f) return;
  ['b100', 'b50', 'b20'].forEach(k => {
    const have = S.counts[k] || 0, n = drop.n[k] || 0;
    f.querySelector('[data-n="' + k + '"]').textContent = n;
    const mb = f.querySelector('[data-k="dq-' + k + '"]'), pb = f.querySelector('[data-k="dq+' + k + '"]');
    mb.disabled = !n; mb.title = n ? '' : 'None selected';
    pb.disabled = n >= have; pb.title = n < have ? '' : have ? 'All counted ' + D[k].lab + ' bills are in the bag' : 'No counted ' + D[k].lab + ' bills in the drawer';
  });
  const tot = Object.entries(drop.n).reduce((a, [k, n]) => a + n * D[k].v, 0);
