}
function paidSheet() {
  if (S.phase !== 'count') return;
  commit();
  openSheet(`<form data-form="paid" novalidate><h3>Paid out</h3><p>Cash leaves the drawer for a store expense. Keep the receipt with the drawer.</p>
    <div class="two"><label>Reason<select name="why"><option>Postage</option><option>Store supplies</option><option>Delivery tip</option><option>Window cleaning</option></select></label><label>Amount<input name="amt" inputmode="decimal" placeholder="0.00" autocomplete="off"></label></div>
    <label>Voucher number<input name="ref" placeholder="e.g. PV-1186" autocomplete="off"></label>
    <p class="err" data-err></p><div class="row"><button type="button" class="apo-shift-ghost" data-act="cancel">Cancel</button><button type="submit" class="apo-shift-solid">Record paid out</button></div></form>`, 'input[name="amt"]');
}
function takeChange(cents) { // greedy from what is counted in the drawer
  const take = {}; let left = cents;
  [...DEN].sort((a, b) => b.v - a.v).forEach(d => { const have = S.counts[d.k] || 0, n = Math.min(have, Math.floor(left / d.v)); if (n) { take[d.k] = n; left -= n * d.v; } });
