    & ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 6px; }
    & li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 0 10px; font-size: 13px; }
    & li small { grid-column: 1; color: var(--apo-loyalty-mute); font-size: 11.5px; }
    & li b { font-variant-numeric: tabular-nums; }
    & li.disc { color: var(--apo-loyalty-accent); transition: opacity .3s, translate .4s var(--apo-loyalty-spring); @starting-style { opacity: 0; translate: 8px 0; } }
    & li.disc button { justify-self: start; font-size: 11.5px; font-weight: 650; color: var(--apo-loyalty-mute); text-decoration: underline; text-underline-offset: 2px; }
    & dl { margin: 0; display: grid; grid-template-columns: 1fr auto; gap: 3px 10px; font-size: 13px; padding-top: 10px; border-top: 1px solid var(--apo-loyalty-line); }
    & dt { color: var(--apo-loyalty-mute); } & dd { margin: 0; text-align: right; font-variant-numeric: tabular-nums; font-weight: 600; }
    & .tot { color: var(--apo-loyalty-ink); font-weight: 800; font-size: 17px; }
  }
  & .apo-loyalty-earn { display: grid; gap: 3px; padding: 12px; border-radius: 12px; background: color-mix(in oklch, var(--apo-loyalty-tier) 12%, var(--apo-loyalty-panel)); border: 1px solid color-mix(in oklch, var(--apo-loyalty-tier) 35%, transparent);
    & b { font-size: 22px; font-weight: 800; letter-spacing: -.02em; color: color-mix(in oklch, var(--apo-loyalty-tier), black 20%); font-variant-numeric: tabular-nums; }
    & small { font-size: 12px; color: var(--apo-loyalty-mute); }
  }

  & .apo-loyalty-keys { grid-area: keys; display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 8px 16px; font-size: 11.5px; color: var(--apo-loyalty-mute); border-top: 1px solid var(--apo-loyalty-line); background: var(--apo-loyalty-panel);
    & span { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
  }
  & .apo-loyalty-sheet { position: absolute; inset: 0; z-index: 8; display: grid; place-items: center; padding: 16px; background: color-mix(in oklch, var(--apo-loyalty-ink) 30%, transparent);
    transition: opacity .25s; @starting-style { opacity: 0; }
    & form { width: min(420px, 100%); max-height: 100%; overflow: auto; display: grid; gap: 12px; padding: 20px; border-radius: 16px; background: var(--apo-loyalty-panel); box-shadow: 0 30px 60px -20px color-mix(in oklch, var(--apo-loyalty-ink) 55%, transparent);
      transition: scale .45s var(--apo-loyalty-spring), opacity .25s; @starting-style { scale: .94; opacity: 0; } }
    & h3 { font-size: 19px; letter-spacing: -.01em; }
    & p { font-size: 12.5px; color: var(--apo-loyalty-mute); }
    & label { display: grid; gap: 4px; font-size: 12px; font-weight: 650; color: var(--apo-loyalty-mute); }
    & input:not([type="checkbox"]) { height: 38px; padding: 0 10px; border-radius: 8px; border: 1px solid var(--apo-loyalty-line2); background: var(--apo-loyalty-bg); outline: none; font-size: 14px; }
    & input:focus-visible { border-color: var(--apo-loyalty-accent); }
    & input[aria-invalid="true"] { border-color: var(--apo-loyalty-accent); background: color-mix(in oklch, var(--apo-loyalty-accent) 6%, var(--apo-loyalty-bg)); }
    & .chk { display: flex; align-items: flex-start; gap: 8px; font-weight: 500; color: var(--apo-loyalty-ink); }
    & .chk input { margin-top: 2px; width: 16px; height: 16px; }
    & .two { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
    & .err { color: var(--apo-loyalty-accent); font-size: 12.5px; font-weight: 650; min-height: 1.1em; }
    & .row { display: flex; justify-content: flex-end; gap: 8px; }
  }
  & .apo-loyalty-toast { position: absolute; left: 50%; bottom: 46px; z-index: 9; padding: 10px 14px; border-radius: 10px; color: var(--apo-loyalty-panel); background: var(--apo-loyalty-ink); font-size: 13px; font-weight: 600; white-space: nowrap; max-width: calc(100% - 24px); overflow: hidden; text-overflow: ellipsis;
    opacity: 0; translate: -50% 10px; pointer-events: none; transition: opacity .25s, translate .45s var(--apo-loyalty-spring);
    &[data-on] { opacity: 1; translate: -50% 0; }
  }
}

@keyframes apo-loyalty-glow { 0%, 100% { box-shadow: 0 0 0 0 color-mix(in oklch, var(--apo-loyalty-gold) 0%, transparent); } 50% { box-shadow: 0 0 0 5px color-mix(in oklch, var(--apo-loyalty-gold) 25%, transparent); } }

@container apo-loyalty (width < 960px) {
  .apo-loyalty .apo-loyalty-app { grid-template: "head head" auto "nav nav" auto "find right" minmax(0, 1fr) "keys keys" auto / clamp(230px, 32cqi, 270px) minmax(0, 1fr); }
  .apo-loyalty .apo-loyalty-nav { grid-area: nav; display: flex; gap: 4px; padding: 6px 12px; border-bottom: 1px solid var(--apo-loyalty-line); background: var(--apo-loyalty-panel);
    & button { flex: 0 1 auto; height: 30px; padding: 0 14px; border-radius: 8px; font-weight: 700; font-size: 12.5px; color: var(--apo-loyalty-mute); }
    & button[aria-selected="true"] { color: white; background: var(--apo-loyalty-ink); }
    & button[data-id="find"] { display: none; }
  }
  .apo-loyalty .apo-loyalty-profile, .apo-loyalty .apo-loyalty-basket { grid-area: right; border-left: 0; }
  .apo-loyalty:not([data-view="sale"]) .apo-loyalty-basket, .apo-loyalty[data-view="sale"] .apo-loyalty-profile { display: none; }
}
@container apo-loyalty (width < 760px) {
  .apo-loyalty .apo-loyalty-app { grid-template: "head" auto "nav" auto "main" minmax(0, 1fr) / minmax(0, 1fr); }
  .apo-loyalty .apo-loyalty-keys { display: none; }
  .apo-loyalty .apo-loyalty-brand span { display: none; }
  .apo-loyalty .apo-loyalty-head .apo-loyalty-ghost kbd { display: none; }
  .apo-loyalty .apo-loyalty-nav {
    & button { flex: 1; height: 34px; }
    & button[data-id="find"] { display: block; }
  }
  .apo-loyalty .apo-loyalty-head .apo-loyalty-ghost span { display: none; }
  .apo-loyalty .apo-loyalty-find, .apo-loyalty .apo-loyalty-profile, .apo-loyalty .apo-loyalty-basket { grid-area: main; border: 0; }
  .apo-loyalty[data-view="find"] .apo-loyalty-profile, .apo-loyalty[data-view="find"] .apo-loyalty-basket,
  .apo-loyalty[data-view="member"] .apo-loyalty-find, .apo-loyalty[data-view="member"] .apo-loyalty-basket,
  .apo-loyalty[data-view="sale"] .apo-loyalty-find, .apo-loyalty[data-view="sale"] .apo-loyalty-profile { display: none; }
  .apo-loyalty .apo-loyalty-profile { padding: 14px; }
  .apo-loyalty .apo-loyalty-who { grid-template-columns: 1fr; justify-items: center; text-align: center; }
  .apo-loyalty .apo-loyalty-name { justify-items: center; }
  .apo-loyalty .apo-loyalty-name .tier, .apo-loyalty .apo-loyalty-name .up { justify-self: center; }
}

@media (prefers-reduced-motion: reduce) {
  .apo-loyalty *, .apo-loyalty *::before, .apo-loyalty *::after { transition-duration: .01ms !important; animation-duration: .01ms !important; animation-iteration-count: 1 !important; }
}

js:
/* Saltmarsh members. The keypad narrows members digit by digit, matching anywhere in the number
   (so a last-four lookup works) and marking the matched run. The tier ring is a conic gradient
   driven by two registered numbers: --apo-loyalty-p is progress this year, --apo-loyalty-q is
   where this basket's points will take it. Rewards re-price the basket and the projection together. */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const usd = (c, neg) => (neg && c ? '−' : '') + '$' + (Math.abs(c) / 100).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pts = n => n.toLocaleString('en-US');
const fmtPhone = d => d.length === 10 ? `(${d.slice(0, 3)}) ${d.slice(3, 6)}-${d.slice(6)}` : d;
const IC = {
  leaf: '<path d="M5 19c0-8 5-13 14-14-1 9-6 14-14 14Z"/><path d="M5 19 13 11"/>', user: '<circle cx="12" cy="8.5" r="3.5"/><path d="M5 20a7 7 0 0 1 14 0"/>',
  star: '<path d="m12 4 2.3 4.8 5.2.7-3.8 3.6.9 5.2L12 15.8l-4.6 2.5.9-5.2-3.8-3.6 5.2-.7Z"/>'
};
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const TIERS = [{ id: 'Tidepool', min: 0, x: 1, c: 'oklch(0.58 0.08 228)' }, { id: 'Kelp', min: 500, x: 1.25, c: 'oklch(0.55 0.11 152)' }, { id: 'Saltmarsh', min: 1500, x: 1.5, c: 'oklch(0.66 0.13 70)' }];
const tierOf = ytd => [...TIERS].reverse().find(t => ytd >= t.min);
const TAX = 0.065;
const BASKET = [['Sea Fennel Hand Cream', '75 ml', 2400, 1], ['Bergamot Lip Balm', '4.5 g', 950, 2], ['Kelp & Clay Mask', '100 ml', 3800, 1]];
const SUB = BASKET.reduce((a, l) => a + l[2] * l[3], 0);
const RW = {
  r10: { title: '$10 off', sub: 'Any purchase', cost: 500, value: 1000 },
  r25: { title: '$25 off', sub: 'Purchases over $60', cost: 1200, value: 2500, min: 6000 },
  bday: { title: 'Birthday gift', sub: 'Travel hand cream, 30 ml', cost: 0, value: 0, gift: true },
  welcome: { title: '15% off today', sub: 'New member welcome', cost: 0, pct: 15 }
};
const M = [
  { id: 'm1', first: 'Ines', last: 'Okonkwo', phone: '5550142297', ytd: 1310, bal: 860, since: 'Mar 2022', bday: true, visits: [['Sep 26', 'Neroli face oil, cotton pads', 5850, 73], ['Aug 30', 'Kelp & Clay Mask', 3800, 47], ['Aug 2', 'Sea salt bath soak ×2', 3600, 45], ['Jul 11', 'Gift set, Harbor collection', 8800, 110]], prefs: { email: true, ff: true, sms: false } },
  { id: 'm2', first: 'Wren', last: 'Albright', phone: '5550132297', ytd: 140, bal: 140, since: 'Jun 2026', visits: [['Sep 3', 'Bergamot Lip Balm ×2', 1900, 19], ['Jun 18', 'Rosemary hair rinse', 2200, 22]], prefs: { email: false, ff: false, sms: true } },
  { id: 'm3', first: 'Priya', last: 'Natarajan', phone: '5550127781', ytd: 2140, bal: 1640, since: 'Jan 2020', visits: [['Sep 29', 'Night balm, toner', 7400, 111], ['Sep 12', 'Hand cream ×3', 7200, 108]], prefs: { email: true, ff: false, sms: true } },
  { id: 'm4', first: 'Ana Sofía', last: 'Ruiz', phone: '5550110429', ytd: 465, bal: 465, since: 'Feb 2026', visits: [['Sep 20', 'Sea salt bath soak', 1800, 18], ['Aug 8', 'Kelp & Clay Mask, balm', 4750, 47]], prefs: { email: true, ff: false, sms: false } },
  { id: 'm5', first: 'Hollis', last: 'Grey', phone: '5550172290', ytd: 720, bal: 220, since: 'Oct 2023', visits: [['Sep 1', 'Beard oil', 2600, 32]], prefs: { email: false, ff: true, sms: false } },
  { id: 'm6', first: 'Theo', last: 'Marchetti', phone: '5550185521', ytd: 1720, bal: 940, since: 'May 2021', visits: [['Sep 24', 'Cedar candle ×2', 6400, 96]], prefs: { email: true, ff: false, sms: false } },
  { id: 'm7', first: 'Dev', last: 'Chandrasekar', phone: '5550169922', ytd: 610, bal: 610, since: 'Nov 2024', visits: [['Sep 17', 'Shave soap, brush', 4900, 61]], prefs: { email: true, ff: false, sms: true } }
];
const S = { q: '2297', sel: 'm1', hi: 0, applied: [], attached: false, view: 'find', uid: 8 };

function matches() {
  const q = S.q;
  if (!q) return M.slice(0, 4).map(m => ({ m, at: -1 }));
  return M.map(m => ({ m, at: m.phone.lastIndexOf(q) })).filter(x => x.at >= 0)
    .sort((a, b) => ((b.at + q.length === 10) - (a.at + q.length === 10)) || a.m.last.localeCompare(b.m.last));
}
const cur = () => M.find(m => m.id === S.sel) || null;
function rewardsFor(m) {
  const r = ['r10', 'r25'];
  if (m.bday) r.unshift('bday');
  if (m.isNew) r.unshift('welcome');
  return r;
}
function quote() {
  const m = cur();
  let disc = 0, spent = 0;
  const lines = [];
  S.applied.forEach(id => {
    const r = RW[id];
    const v = r.pct ? Math.round(SUB * r.pct / 100) : r.value;
    disc += v; spent += r.cost;
    lines.push({ id, label: r.gift ? 'Birthday gift · travel hand cream' : r.title + ' reward', v, cost: r.cost });
  });
  disc = Math.min(disc, SUB);
  const net = SUB - disc, tax = Math.round(net * TAX), total = net + tax;
  const t = m ? tierOf(m.ytd) : TIERS[0];
  const earn = m ? Math.floor(Math.floor(net / 100) * t.x) : 0;
  return { lines, disc, net, tax, total, earn, spent, t };
}
function canApply(m, id) {
  const r = RW[id], q = quote();
  if (S.applied.includes(id)) return '';
  if (r.cost > m.bal - q.spent) return 'Needs ' + pts(r.cost) + ' points; ' + pts(m.bal - q.spent) + ' available';
  if (r.min && SUB < r.min) return 'Basket must be over ' + usd(r.min);
  if (!r.gift && !r.pct && q.disc + r.value > SUB) return 'Would exceed the basket';
  return '';
}

/* ── render ── */
function keep(fn) {
  const a = root.contains(document.activeElement) ? document.activeElement : null, k = a && a.dataset.k;
  fn();
  if (k) { const n = root.querySelector('[data-k="' + CSS.escape(k) + '"]'); if (n && n !== document.activeElement && !n.disabled) n.focus({ preventScroll: true }); }
}
const LET = { 2: 'ABC', 3: 'DEF', 4: 'GHI', 5: 'JKL', 6: 'MNO', 7: 'PQRS', 8: 'TUV', 9: 'WXYZ' };
function renderFind() {
  const pad = $('.apo-loyalty-pad');
  if (!pad.firstChild) pad.innerHTML = ['1', '2', '3', '4', '5', '6', '7', '8', '9', 'C', '0', '⌫'].map(k =>
    `<button type="button" data-act="key" data-key="${k}" data-k="key-${k}" class="${k === 'C' || k === '⌫' ? 'fn' : ''}" aria-label="${k === 'C' ? 'Clear' : k === '⌫' ? 'Delete digit' : k}">${k === 'C' ? 'Clear' : k}${LET[k] ? `<small>${LET[k]}</small>` : ''}</button>`).join('');
  $$('button', pad).forEach(b => { if (b.dataset.key === 'C' || b.dataset.key === '⌫') { b.disabled = !S.q; b.title = S.q ? '' : 'Nothing typed'; } });
  const out = $('[data-phone]');
  out.innerHTML = S.q ? esc(fmtPhone(S.q)) + (S.q.length < 10 ? '<i>' + '·'.repeat(Math.min(3, 10 - S.q.length)) + '</i>' : '') : '<i>Type digits</i>';
  const list = matches();
  if (S.hi >= list.length) S.hi = 0;
  $('.apo-loyalty-cands').innerHTML = list.length ? list.map(({ m, at }, i) => {
    const ph = fmtPhone(m.phone);
    let shown = esc(ph);
    if (at >= 0) { // map digit index to formatted index
      const idx = []; [...ph].forEach((ch, j) => { if (/\d/.test(ch)) idx.push(j); });
      const a = idx[at], b = idx[at + S.q.length - 1] + 1;
      shown = esc(ph.slice(0, a)) + '<mark>' + esc(ph.slice(a, b)) + '</mark>' + esc(ph.slice(b));
    }
    const t = tierOf(m.ytd);
    return `<li class="apo-loyalty-cand" role="option" data-act="pick" data-id="${m.id}" data-k="c-${m.id}" aria-selected="${S.sel === m.id}" tabindex="${i === S.hi ? 0 : -1}" style="--t:${t.c}">
      <span class="av">${esc(m.first[0] + m.last[0])}</span><b>${esc(m.first + ' ' + m.last)}</b><span class="tr">${t.id}</span><span class="ph">${shown}</span></li>`;
  }).join('') : `<li class="apo-loyalty-none">No member uses ${esc(fmtPhone(S.q))}. <button type="button" class="apo-loyalty-ghost" style="margin-top:8px" data-act="enroll" data-k="enroll2">Enroll this number</button></li>`;
  if (!S.q) $('.apo-loyalty-cands').insertAdjacentHTML('afterbegin', '<li class="apo-loyalty-none" style="text-align:left;padding:2px 4px" role="none">Recent members</li>');
}
function renderProfile() {
  const box = $('.apo-loyalty-profile'), m = cur();
  if (!m) { box.innerHTML = `<div class="apo-loyalty-empty">${svg('user')}<b>No member on this sale</b><p>Type a phone number or the last four digits, then pick the member.</p></div>`; box.__id = null; return; }
  const q = quote(), t = q.t, nx = TIERS[TIERS.indexOf(t) + 1];
  if (box.__id !== m.id) {
    box.__id = m.id;
    box.innerHTML = `<article class="apo-loyalty-card"><div class="apo-loyalty-who"><div class="apo-loyalty-ringwrap"><div class="apo-loyalty-ring" role="img"></div><div class="mid"></div></div><div class="apo-loyalty-name"></div></div>
      <div class="apo-loyalty-bal"></div><section class="apo-loyalty-sec"><h3><span>Rewards</span><span data-avail></span></h3><div class="apo-loyalty-rewards"></div></section>
      <section class="apo-loyalty-sec"><h3><span>Recent visits</span><span>${m.visits.length}</span></h3><ul class="apo-loyalty-hist">${m.visits.length ? m.visits.map(v => `<li><time>${v[0]}</time><span class="it">${esc(v[1])}</span><b class="apo-loyalty-num">${usd(v[2])}</b><span class="pt">+${v[3]}</span></li>`).join('') : '<li><span class="it" style="color:var(--apo-loyalty-mute)">First visit today</span></li>'}</ul></section>
      <section class="apo-loyalty-sec"><h3><span>Preferences</span></h3><div class="apo-loyalty-prefs"></div></section></article>`;
  }
  root.style.setProperty('--apo-loyalty-tier', t.c);
  const ring = $('.apo-loyalty-ring', box);
  const span = nx ? nx.min - t.min : 1, p = nx ? (m.ytd - t.min) / span : 1, qv = nx ? Math.min(1, (m.ytd + q.earn - t.min) / span) : 1;
  ring.style.setProperty('--apo-loyalty-p', p.toFixed(4)); ring.style.setProperty('--apo-loyalty-q', qv.toFixed(4));
  ring.setAttribute('aria-label', nx ? `${pts(m.ytd)} of ${pts(nx.min)} points toward ${nx.id}, ${pts(q.earn)} more with this sale` : 'Top tier');
  $('.mid', box).innerHTML = nx ? `<b>${pts(nx.min - m.ytd)}</b><span>points to ${nx.id}</span><em>+${pts(q.earn)} today</em>` : `<b>${pts(m.ytd)}</b><span>points this year</span><em>Top tier</em>`;
  const up = nx && m.ytd + q.earn >= nx.min;
  $('.apo-loyalty-name', box).innerHTML = `<span class="tier">${svg(t.id === 'Saltmarsh' ? 'star' : 'leaf')}${t.id}${t.x > 1 ? ' · ' + t.x + '× points' : ''}</span><h2>${esc(m.first + ' ' + m.last)}</h2>
    <span class="meta">${fmtPhone(m.phone)} · member since ${m.since}${m.bday ? ' · birthday this month' : ''}</span>${up ? `<span class="up">Reaches ${nx.id} with this sale</span>` : ''}`;
  $('.apo-loyalty-bal', box).innerHTML = `<div><span>Points</span><b>${pts(m.bal - q.spent)}</b></div><div><span>This year</span><b>${pts(m.ytd)}</b></div><div><span>After sale</span><b>${pts(m.bal - q.spent + q.earn)}</b></div>`;
  const rws = rewardsFor(m);
  $('[data-avail]', box).textContent = rws.filter(id => !canApply(m, id) && !S.applied.includes(id)).length + ' available';
  const rh = rws.map(id => { const r = RW[id], why = canApply(m, id), on = S.applied.includes(id);
    return `<button type="button" class="apo-loyalty-rw" data-act="rw" data-id="${id}" data-k="rw-${id}" aria-pressed="${on}" ${r.gift ? 'data-gift' : ''} ${why ? `disabled title="${why}"` : `title="${on ? 'Remove from this sale' : 'Apply to this sale'}"`}>
      <span class="cost">${r.cost ? pts(r.cost) + ' pts' : 'free'}</span><b>${r.title}</b><small>${r.sub}</small></button>`; }).join('');
  const rbox = $('.apo-loyalty-rewards', box); if (rbox.__h !== rh) { rbox.innerHTML = rh; rbox.__h = rh; }
  const ph = [['email', 'Email receipts', 'Send receipts to the address on file'], ['ff', 'Fragrance-free', 'Suggest unscented products first'], ['sms', 'Text offers', 'Up to two messages a month']].map(([k, l, d]) =>
    `<div class="apo-loyalty-pref"><span>${l}<small>${d}</small></span><button type="button" class="apo-loyalty-switch" role="switch" data-act="pref" data-id="${k}" data-k="pf-${k}" aria-checked="${!!m.prefs[k]}" aria-label="${l}"></button></div>`).join('');
  const pbox = $('.apo-loyalty-prefs', box); if (pbox.__h !== ph) { pbox.innerHTML = ph; pbox.__h = ph; }
}
function renderBasket() {
  const m = cur(), q = quote();
  $('.apo-loyalty-basket').innerHTML = `<h3>Sale #3-2214 · Register 3</h3>
    <ul>${BASKET.map(l => `<li><span>${esc(l[0])}${l[3] > 1 ? ' × ' + l[3] : ''}</span><b>${usd(l[2] * l[3])}</b><small>${l[1]}</small></li>`).join('')}
    ${q.lines.map(l => `<li class="disc"><span>${esc(l.label)}</span><b>${l.v ? usd(l.v, true) : usd(0)}</b><button type="button" data-act="rw" data-id="${l.id}" data-k="rm-${l.id}">Remove${l.cost ? ' · refund ' + pts(l.cost) + ' pts' : ''}</button></li>`).join('')}</ul>
    <dl><dt>Subtotal</dt><dd>${usd(SUB)}</dd>${q.disc ? `<dt>Rewards</dt><dd style="color:var(--apo-loyalty-accent)">${usd(q.disc, true)}</dd>` : ''}<dt>Tax 6.5%</dt><dd>${usd(q.tax)}</dd><dt class="tot">Total</dt><dd class="tot">${usd(q.total)}</dd></dl>
    ${m ? `<div class="apo-loyalty-earn"><small>Points this sale</small><b>+${pts(q.earn)}</b><small>${Math.floor(q.net / 100)} eligible dollars × ${q.t.x} (${q.t.id})${q.spent ? ' · ' + pts(q.spent) + ' redeemed' : ''}</small></div>
      <button type="button" class="apo-loyalty-solid" data-act="attach" data-k="attach" aria-pressed="${S.attached}">${S.attached ? 'Attached · detach' : 'Attach ' + esc(m.first) + ' to sale'}</button>`
    : '<p style="font-size:12.5px;color:var(--apo-loyalty-mute)">No member attached. Points can still be added later from the receipt.</p>'}`;
}
function renderNav() {
  const m = cur(), v = S.view === 'find' && root.clientWidth >= 760 ? 'member' : S.view;
  $('.apo-loyalty-nav').innerHTML = [['find', 'Find'], ['member', m ? m.first : 'Member'], ['sale', 'Sale · ' + usd(quote().total)]].map(([id, l]) =>
    `<button type="button" role="tab" data-act="view" data-id="${id}" data-k="nv-${id}" aria-selected="${v === id}">${esc(l)}</button>`).join('');
}
function render() { keep(() => { root.dataset.view = S.view; renderFind(); renderProfile(); renderBasket(); renderNav(); }); }
let tt = 0;
function toast(msg) { const t = $('.apo-loyalty-toast'); t.textContent = msg; t.setAttribute('data-on', ''); clearTimeout(tt); tt = setTimeout(() => t.removeAttribute('data-on'), 2800); }

/* ── actions ── */
function key(k) {
  if (k === 'C') S.q = '';
  else if (k === '⌫') S.q = S.q.slice(0, -1);
  else if (S.q.length < 10) S.q += k;
  S.hi = 0;
  const list = matches();
  if (S.q.length === 10 && list.length === 1) pick(list[0].m.id, true); else render();
}
function pick(id, auto) {
  if (S.sel !== id) { S.sel = id; S.applied = []; S.attached = false; }
  if (root.clientWidth < 760) S.view = 'member';
  render();
  if (auto) toast('Found ' + cur().first + ' ' + cur().last);
}
function toggleReward(id) {
  const m = cur(); if (!m) return;
  if (S.applied.includes(id)) { S.applied = S.applied.filter(x => x !== id); render(); toast(RW[id].title + ' removed' + (RW[id].cost ? ', ' + pts(RW[id].cost) + ' points returned' : '')); return; }
  const why = canApply(m, id); if (why) { toast(why); return; }
  S.applied.push(id); render(); toast(RW[id].gift ? 'Birthday gift added at $0.00' : RW[id].title + ' applied to the sale');
}
function enrollSheet() {
  const sh = $('.apo-loyalty-sheet');
  sh.innerHTML = `<form novalidate data-form="enroll"><h3>New member</h3><p>Members earn a point for every dollar and get 15% off today. We only text if they opt in.</p>
    <div class="two"><label>First name<input name="first" autocomplete="off" data-k="f-first"></label><label>Last name<input name="last" autocomplete="off" data-k="f-last"></label></div>
    <label>Mobile number<input name="phone" inputmode="tel" autocomplete="off" placeholder="(555) 010-0000" value="${S.q.length === 10 ? fmtPhone(S.q) : ''}" data-k="f-phone"></label>
    <label>Email <small style="font-weight:500">optional, for receipts</small><input name="email" type="email" autocomplete="off" data-k="f-email"></label>
    <label class="chk"><input type="checkbox" name="sms"> Text me offers (up to two a month)</label>
    <p class="err" data-err></p><div class="row"><button type="button" class="apo-loyalty-ghost" data-act="cancel">Cancel</button><button type="submit" class="apo-loyalty-solid">Create member</button></div></form>`;
  sh.hidden = false; $('input', sh).focus({ preventScroll: true });
}
function closeSheet() { const sh = $('.apo-loyalty-sheet'); sh.hidden = true; sh.innerHTML = ''; const n = $('[data-k="enroll"]'); if (n) n.focus({ preventScroll: true }); }

root.addEventListener('click', e => {
  if (e.target.classList.contains('apo-loyalty-sheet')) { closeSheet(); return; }
  const b = e.target.closest('[data-act]'); if (!b || !root.contains(b) || b.disabled) return;
  const a = b.dataset.act, id = b.dataset.id;
  if (a === 'key') key(b.dataset.key);
  else if (a === 'pick') pick(id);
  else if (a === 'rw') toggleReward(id);
  else if (a === 'pref') { const m = cur(); m.prefs[id] = !m.prefs[id]; render(); toast({ email: 'Email receipts', ff: 'Fragrance-free suggestions', sms: 'Text offers' }[id] + (m.prefs[id] ? ' on' : ' off') + ' for ' + m.first); }
  else if (a === 'attach') { S.attached = !S.attached; render(); const q = quote(), m = cur(); toast(S.attached ? `${m.first} ${m.last} attached · +${pts(q.earn)} points pending` : 'Member detached from the sale'); }
  else if (a === 'enroll') enrollSheet();
  else if (a === 'cancel') closeSheet();
  else if (a === 'view') { S.view = id; render(); }
});
root.addEventListener('submit', e => {
  e.preventDefault();
  const f = e.target, F = n => f.elements.namedItem(n), err = m => { f.querySelector('[data-err]').textContent = m; };
  $$('input', f).forEach(i => i.removeAttribute('aria-invalid'));
  const first = F('first').value.trim(), last = F('last').value.trim(), phone = F('phone').value.replace(/\D/g, '').replace(/^1(?=\d{10}$)/, ''), email = F('email').value.trim();
  if (!first || !last) { (first ? F('last') : F('first')).setAttribute('aria-invalid', 'true'); return err('First and last name are both needed.'); }
  if (phone.length !== 10) { F('phone').setAttribute('aria-invalid', 'true'); return err('Mobile number needs 10 digits.'); }
  const dupe = M.find(m => m.phone === phone);
  if (dupe) { F('phone').setAttribute('aria-invalid', 'true'); return err('That number already belongs to ' + dupe.first + ' ' + dupe.last[0] + '.'); }
  if (email && !/^[^\s@]+@[^\s@]+\.[a-z]{2,}$/i.test(email)) { F('email').setAttribute('aria-invalid', 'true'); return err('Check the email address.'); }
  const m = { id: 'm' + (S.uid++), first, last, phone, ytd: 0, bal: 50, since: 'today', isNew: true, visits: [], prefs: { email: !!email, ff: false, sms: F('sms').checked } };
  M.unshift(m); S.q = phone.slice(-4); closeSheet(); pick(m.id); toast(first + ' enrolled · 50 welcome points');
});
root.addEventListener('keydown', e => {
  const sh = $('.apo-loyalty-sheet');
  if (!sh.hidden) { if (e.key === 'Escape') { closeSheet(); e.preventDefault(); } return; }
  const t = e.target, k = e.key;
  if (t.tagName === 'INPUT' || e.metaKey || e.ctrlKey || e.altKey) return;
  if (/^[0-9]$/.test(k)) { key(k); e.preventDefault(); }
  else if (k === 'Backspace') { key('⌫'); e.preventDefault(); }
  else if (k === 'Escape') { key('C'); e.preventDefault(); }
  else if (k === 'ArrowDown' || k === 'ArrowUp') {
    const list = matches(); if (!list.length) return;
    S.hi = t.classList.contains('apo-loyalty-cand') ? Math.max(0, Math.min(list.length - 1, list.findIndex(x => x.m.id === t.dataset.id) + (k === 'ArrowDown' ? 1 : -1))) : 0;
    render(); const n = $$('.apo-loyalty-cand')[S.hi]; if (n) n.focus(); e.preventDefault();
  }
  else if (k === 'Enter' && t.tagName !== 'BUTTON') { const n = t.classList.contains('apo-loyalty-cand') ? t : $$('.apo-loyalty-cand')[S.hi]; if (n) pick(n.dataset.id); e.preventDefault(); }
  else if (k === ' ' && t.classList.contains('apo-loyalty-cand')) { pick(t.dataset.id); e.preventDefault(); }
  else if (k === 'a' || k === 'A') { const m = cur(); if (m) { const id = rewardsFor(m).find(x => !S.applied.includes(x) && !canApply(m, x)); if (id) toggleReward(id); else toast('No reward can be applied'); } e.preventDefault(); }
  else if (k === 'n' || k === 'N') { enrollSheet(); e.preventDefault(); }
});

render();

css:
.apo-receipt {
  --apo-receipt-bg: oklch(0.205 0.012 262);
  --apo-receipt-ink: oklch(0.94 0.008 250);
  --apo-receipt-accent: oklch(0.72 0.15 42);
  --apo-receipt-paper: oklch(0.985 0.004 95);
  --apo-receipt-print: oklch(0.27 0.012 260);
  --apo-receipt-panel: color-mix(in oklch, var(--apo-receipt-bg), black 16%);
  --apo-receipt-card: color-mix(in oklch, var(--apo-receipt-bg), var(--apo-receipt-ink) 6%);
  --apo-receipt-line: color-mix(in oklch, var(--apo-receipt-ink) 10%, transparent);
  --apo-receipt-line2: color-mix(in oklch, var(--apo-receipt-ink) 20%, transparent);
  --apo-receipt-mute: color-mix(in oklch, var(--apo-receipt-ink) 56%, var(--apo-receipt-bg));
  --apo-receipt-mono: ui-monospace, "SF Mono", Menlo, Consolas, monospace;
  --apo-receipt-ease: cubic-bezier(.2, .8, .2, 1);
  --apo-receipt-spring: linear(0, .09 4%, .32 10%, .65 17%, .9 25%, 1.03 32%, 1.06 38%, 1.04 46%, 1.01 58%, .998 75%, 1);
  position: relative; width: 100%; height: var(--apo-receipt-h, 680px); box-sizing: border-box;
  container-type: inline-size; container-name: apo-receipt;
  overflow: clip; isolation: isolate; border-radius: 14px;
  background: var(--apo-receipt-bg); color: var(--apo-receipt-ink);
  font: 14px/1.4 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  color-scheme: dark; accent-color: var(--apo-receipt-accent);

  & *, & *::before, & *::after { box-sizing: border-box; }
  &:focus { outline: none; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; border: 0; background: none; padding: 0; }
  & button:disabled { cursor: not-allowed; opacity: .4; }
  & svg { display: block; fill: none; stroke: currentColor; stroke-width: 1.75; stroke-linecap: round; stroke-linejoin: round; }
  & [hidden] { display: none !important; }
  & :focus-visible { outline: 2px solid var(--apo-receipt-accent); outline-offset: 2px; }
  & h2, & h3 { margin: 0; text-wrap: balance; }
  & p { margin: 0; text-wrap: pretty; }
  & kbd { font: 600 10px/1 var(--apo-receipt-mono); padding: 3px 5px 2px; border-radius: 4px; border: 1px solid var(--apo-receipt-line2); border-bottom-width: 2px; color: var(--apo-receipt-mute); }
  & .apo-receipt-btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; height: 38px; padding: 0 14px; border-radius: 10px; font-size: 13px; font-weight: 700; border: 1px solid var(--apo-receipt-line2); transition: border-color .2s, background .2s, transform .12s var(--apo-receipt-ease);
    & svg { width: 17px; height: 17px; }
    &:hover:not(:disabled) { border-color: var(--apo-receipt-ink); }
    &:active:not(:disabled) { transform: scale(.97); }
    &.solid { color: var(--apo-receipt-bg); background: var(--apo-receipt-accent); border-color: var(--apo-receipt-accent); }
    &.solid kbd { color: var(--apo-receipt-bg); border-color: color-mix(in oklch, var(--apo-receipt-bg) 40%, transparent); }
    &.solid:hover:not(:disabled) { background: color-mix(in oklch, var(--apo-receipt-accent), white 10%); }
  }

  & .apo-receipt-app { height: 100%; display: grid; grid-template: "head head head" auto "jour stage opts" minmax(0, 1fr) "keys keys keys" auto / clamp(250px, 26cqi, 300px) minmax(0, 1fr) clamp(230px, 23cqi, 270px); }
  & .apo-receipt-head { grid-area: head; display: flex; align-items: center; gap: 14px; padding: 10px 16px; border-bottom: 1px solid var(--apo-receipt-line); background: var(--apo-receipt-panel); }
  & .apo-receipt-brand { display: flex; align-items: center; gap: 10px; min-width: 0; margin-right: auto;
    & svg { width: 32px; height: 32px; padding: 5px; border-radius: 8px; color: var(--apo-receipt-bg); background: var(--apo-receipt-accent); flex: none; }
    & b { display: block; font-size: 15px; font-weight: 800; letter-spacing: -.01em; white-space: nowrap; }
    & span { display: block; font-size: 12px; color: var(--apo-receipt-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  }
  & .apo-receipt-chip { display: inline-flex; align-items: center; gap: 7px; font-size: 12px; font-weight: 700; padding: 5px 10px; border-radius: 99px; background: var(--apo-receipt-card); white-space: nowrap;
    & i { width: 8px; height: 8px; border-radius: 50%; background: oklch(0.78 0.14 155); box-shadow: 0 0 0 3px color-mix(in oklch, oklch(0.78 0.14 155) 22%, transparent); }
    &[data-busy] i { background: var(--apo-receipt-accent); animation: apo-receipt-blink .6s steps(2) infinite; }
  }
  & .apo-receipt-nav { display: none; }

  /* journal */
  & .apo-receipt-journal { grid-area: jour; min-height: 0; display: grid; grid-template-rows: auto auto minmax(0, 1fr); gap: 10px; padding: 14px 12px 0; border-right: 1px solid var(--apo-receipt-line); background: var(--apo-receipt-panel); }
  & .apo-receipt-search { display: flex; align-items: center; gap: 8px; height: 38px; padding: 0 8px 0 10px; border-radius: 10px; background: var(--apo-receipt-bg); border: 1px solid var(--apo-receipt-line2);
    & svg { width: 17px; height: 17px; color: var(--apo-receipt-mute); flex: none; }
    & input { flex: 1; min-width: 0; border: 0; outline: none; background: none; height: 100%; font-size: 13.5px; }
    & input::-webkit-search-cancel-button { appearance: none; }
    &:has(input:focus-visible) { border-color: var(--apo-receipt-accent); box-shadow: 0 0 0 3px color-mix(in oklch, var(--apo-receipt-accent) 20%, transparent); }
  }
  & .apo-receipt-filters { display: flex; flex-wrap: wrap; gap: 4px;
    & button { height: 26px; padding: 0 9px; border-radius: 99px; font-size: 12px; font-weight: 650; color: var(--apo-receipt-mute); border: 1px solid var(--apo-receipt-line); transition: color .2s, background .2s; }
    & button span { font-variant-numeric: tabular-nums; opacity: .7; margin-left: 3px; }
    & button:hover { color: var(--apo-receipt-ink); }
    & button[aria-selected="true"] { color: var(--apo-receipt-bg); background: var(--apo-receipt-ink); border-color: var(--apo-receipt-ink); }
  }
  & .apo-receipt-list { list-style: none; margin: 0 -4px; padding: 0 4px 12px; overflow: auto; display: grid; grid-auto-rows: max-content; align-content: start; gap: 3px; scrollbar-width: thin; }
  & .apo-receipt-row { --c: var(--apo-receipt-mute); display: grid; grid-template-columns: 3px minmax(0, 1fr) auto; gap: 1px 10px; padding: 9px 10px 9px 8px; border-radius: 10px; cursor: pointer; transition: background .2s;
    & .bar { grid-row: span 2; border-radius: 2px; background: var(--c); }
    & .no { font: 650 12.5px/1.25 var(--apo-receipt-mono); }
    & .amt { font: 700 13px/1.25 var(--apo-receipt-mono); font-variant-numeric: tabular-nums; text-align: right; }
    & .meta { font-size: 11.5px; color: var(--apo-receipt-mute); display: flex; gap: 6px; flex-wrap: wrap; }
    & .tag { font-size: 10px; font-weight: 800; letter-spacing: .06em; text-transform: uppercase; color: var(--c); }
    & .rp { font-size: 10.5px; font-weight: 700; color: var(--apo-receipt-accent); }
    &[data-type="sale"] { --c: oklch(0.78 0.12 155); } &[data-type="return"] { --c: oklch(0.76 0.12 230); } &[data-type="void"] { --c: oklch(0.68 0.18 25); } &[data-type="nosale"] { --c: oklch(0.8 0.1 85); }
    &:hover { background: var(--apo-receipt-card); }
    &[aria-selected="true"] { background: color-mix(in oklch, var(--apo-receipt-accent) 14%, var(--apo-receipt-panel)); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--apo-receipt-accent) 40%, transparent); }
  }
  & .apo-receipt-none { padding: 18px 8px; font-size: 12.5px; color: var(--apo-receipt-mute); text-align: center; }

  /* stage */
  & .apo-receipt-stage { grid-area: stage; position: relative; min-height: 0; overflow: auto; padding: 0 20px 32px; display: grid; justify-items: center; align-content: start; scrollbar-width: thin;
    background: radial-gradient(120% 60% at 50% 0%, color-mix(in oklch, var(--apo-receipt-bg), white 6%), var(--apo-receipt-bg) 70%); }
  & .apo-receipt-feed { width: max-content; max-width: 100%; display: grid; filter: drop-shadow(0 16px 16px color-mix(in oklch, black 45%, transparent)); }
  & .apo-receipt-slot { position: sticky; top: 0; z-index: 2; height: 16px; margin: 0 -18px -6px; border-radius: 0 0 10px 10px;
    background: linear-gradient(color-mix(in oklch, var(--apo-receipt-bg), black 50%), color-mix(in oklch, var(--apo-receipt-bg), black 25%)); box-shadow: 0 6px 10px -4px black, inset 0 -2px 0 color-mix(in oklch, white 8%, transparent); }
  & .apo-receipt-paper { --pad: 16px; position: relative; width: max-content; max-width: 100%; padding: 22px var(--pad) 34px; margin-top: 0; color: var(--apo-receipt-print); background: var(--apo-receipt-paper);
    font: 500 var(--fsz, 12.5px)/1.42 var(--apo-receipt-mono); font-variant-numeric: tabular-nums; letter-spacing: 0;
    mask: conic-gradient(from -45deg at bottom, #0000, #000 1deg 89deg, #0000 90deg) 50% / 14px 100%;
    overflow-x: auto; scrollbar-width: none;
    & .ln { white-space: pre; min-height: 1.42em; }
    & .b { font-weight: 800; }
    & .dw { font-size: 2em; line-height: 1.15; font-weight: 800; letter-spacing: 0; }
    & .rule { white-space: pre; color: color-mix(in oklch, var(--apo-receipt-print) 55%, transparent); }
    & .inv { background: var(--apo-receipt-print); color: var(--apo-receipt-paper); }
    & .bc { display: flex; justify-content: center; padding: 6px 0 2px; }
    & .bc svg { height: 46px; width: auto; max-width: 100%; }
    & .bc rect { fill: var(--apo-receipt-print); stroke: none; }
    & .head { position: absolute; left: 0; right: 0; top: 0; height: 3px; background: color-mix(in oklch, var(--apo-receipt-accent) 70%, transparent); box-shadow: 0 0 10px var(--apo-receipt-accent); opacity: 0; pointer-events: none; }
    &[data-fade] .ln { color: color-mix(in oklch, var(--apo-receipt-print) 75%, var(--apo-receipt-paper)); }
  }
  & .apo-receipt-paper.swap { animation: apo-receipt-swap .45s var(--apo-receipt-ease); }

  /* options */
  & .apo-receipt-opts { grid-area: opts; min-height: 0; overflow: auto; display: grid; grid-auto-rows: max-content; align-content: start; gap: 14px; padding: 14px 14px 16px; border-left: 1px solid var(--apo-receipt-line); background: var(--apo-receipt-panel); scrollbar-width: thin;
    & h3 { font-size: 11px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; color: var(--apo-receipt-mute); margin-bottom: 6px; }
  }
  & .apo-receipt-seg { display: grid; grid-template-columns: repeat(3, 1fr); gap: 2px; padding: 2px; border-radius: 10px; background: var(--apo-receipt-bg);
    & button { display: grid; gap: 0; padding: 6px 4px; border-radius: 8px; font-size: 12px; font-weight: 750; color: var(--apo-receipt-mute); text-align: center; transition: background .2s, color .2s; }
    & button small { font: 500 10.5px var(--apo-receipt-mono); }
    & button[aria-checked="true"] { color: var(--apo-receipt-bg); background: var(--apo-receipt-ink); }
    & button:hover:not([aria-checked="true"]) { color: var(--apo-receipt-ink); }
  }
  & .apo-receipt-tog { display: flex; align-items: center; gap: 10px; font-size: 13px; padding: 3px 0;
    & span { flex: 1; } & small { display: block; font-size: 11.5px; color: var(--apo-receipt-mute); }
  }
  & .apo-receipt-switch { flex: none; width: 40px; height: 24px; border-radius: 99px; background: var(--apo-receipt-line2); position: relative; transition: background .25s;
    &::after { content: ""; position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%; background: white; box-shadow: 0 1px 3px color-mix(in oklch, black 40%, transparent); transition: translate .35s var(--apo-receipt-spring); }
    &[aria-checked="true"] { background: var(--apo-receipt-accent); }
    &[aria-checked="true"]::after { translate: 16px 0; }
  }
  & .apo-receipt-acts { display: grid; gap: 8px; }
  & .apo-receipt-roll { display: grid; gap: 6px; padding: 11px 12px; border-radius: 12px; background: var(--apo-receipt-bg); font-size: 12px;
    & .t { display: flex; justify-content: space-between; color: var(--apo-receipt-mute); }
    & .t b { color: var(--apo-receipt-ink); font-variant-numeric: tabular-nums; }
    & .bar { height: 6px; border-radius: 3px; background: var(--apo-receipt-card); overflow: hidden; }
    & .bar i { display: block; height: 100%; width: calc(var(--p) * 100%); border-radius: inherit; background: linear-gradient(90deg, var(--apo-receipt-accent), oklch(0.82 0.11 75)); transition: width .8s var(--apo-receipt-spring); }
  }
  & .apo-receipt-log { list-style: none; margin: 0; padding: 0; display: grid; gap: 4px; font-size: 12px;
    & li { display: flex; justify-content: space-between; gap: 8px; color: var(--apo-receipt-mute); padding: 5px 0; border-bottom: 1px solid var(--apo-receipt-line); transition: opacity .3s, translate .4s var(--apo-receipt-spring); @starting-style { opacity: 0; translate: 0 -6px; } }
    & b { color: var(--apo-receipt-ink); font-weight: 650; }
  }

  & .apo-receipt-keys { grid-area: keys; display: flex; flex-wrap: wrap; gap: 6px 16px; padding: 8px 16px; font-size: 11.5px; color: var(--apo-receipt-mute); border-top: 1px solid var(--apo-receipt-line); background: var(--apo-receipt-panel);
    & span { display: inline-flex; align-items: center; gap: 4px; white-space: nowrap; }
  }
