/* Marrow & Vine electronic journal. Receipts are laid out the way a thermal printer does it:
   fixed-width text columns (32, 42 or 48 characters), names wrapped to the space left after
   the amount column, double-width lines formatted at half the columns. Changing paper width
   re-flows every line; printing reveals the paper one text line at a time with steps(). */
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => [...el.querySelectorAll(s)];
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s).replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
