const amt = c => (c < 0 ? '-' : '') + (Math.abs(c) / 100).toFixed(2);
const IC = { print: '<path d="M7 9V3.5h10V9M7 17H4.5V9.5h15V17H17"/><rect x="7" y="13.5" width="10" height="7"/>', mail: '<rect x="3" y="5.5" width="18" height="13" rx="2"/><path d="m3.5 7 8.5 6.5L20.5 7"/>' };
const svg = k => '<svg viewBox="0 0 24 24" aria-hidden="true">' + IC[k] + '</svg>';
const TAXR = 0.0825;
const WIDTHS = [{ w: 32, mm: '58 mm', note: 'Font A', fs: '12.5px' }, { w: 42, mm: '80 mm', note: 'Font A', fs: '12.5px' }, { w: 48, mm: '80 mm', note: 'Font B', fs: '11px' }];
const ROLL = 80000, LINE_MM = 4.23, CUT_MM = 18;

// [name, qty, unit cents | {w, ppl}, tax F|T, plu, {pct, label}?]
const J = [
  { no: '1-08843', t: '10:34 AM', type: 'sale', who: 'Kemi O.', items: [['Espresso, double', 1, 350, 'T', '3301'], ['Almond Croissant', 1, 425, 'F', '1120']], tenders: [['DEBIT ••3007', null, 'TAP · AUTH 3J8812']] },
  { no: '1-08842', t: '10:21 AM', type: 'void', who: 'Kemi O.', mgr: 'K. Osei', items: [['Smoked Trout Pâté', 1, 899, 'F', '2470'], ['Seeded Crackers', 1, 549, 'F', '3122']] },
  { no: '1-08841', t: '10:15 AM', type: 'sale', who: 'Rafa D.', member: 'Marrow Club ••5521', items: [['Heirloom Tomatoes', 1, { w: 1.42, ppl: 399 }, 'F', '4087'], ['Sourdough Batard', 1, 650, 'F', '1104'], ['Aged Gouda', 1, { w: 0.48, ppl: 1899 }, 'F', '2318'], ['Castelvetrano Olives', 1, 725, 'F', '2402'], ['Sparkling Water, 12 pack', 1, 699, 'T', '3350'], ['Beeswax Food Wrap Set of Three', 1, 1800, 'T', '5502', { pct: 10, label: 'Club 10% off' }], ['Dark Chocolate, Sea Salt', 2, 375, 'T', '3378']], tenders: [['CASH', 2000], ['VISA ••4417', null, 'CHIP · AUTH 0K93TZ']] },
  { no: '1-08840', t: '10:02 AM', type: 'return', who: 'Kemi O.', ref: '1-08791', items: [['Ceramic Pour-Over Cone', -1, 2400, 'T', '5120']], tenders: [['VISA ••7762 REFUND', null, 'AUTH R55K02']] },
  { no: '1-08839', t: '9:40 AM', type: 'sale', who: 'Rafa D.', member: 'Marrow Club ••2210', items: [['Roast Chicken, whole', 1, 1299, 'F', '2501', { pct: 10, label: 'Club 10% off deli' }], ['Lemon Herb Potatoes', 1, { w: 0.86, ppl: 899 }, 'F', '2506'], ['Ginger Kombucha', 2, 399, 'T', '3361']], tenders: [['MASTERCARD ••5520', null, 'TAP · AUTH 8H2C10']] },
  { no: '1-08838', t: '9:26 AM', type: 'nosale', who: 'Rafa D.', reason: 'Change for bank run' },
  { no: '1-08837', t: '9:11 AM', type: 'sale', who: 'Rafa D.', items: [['Honeycrisp Apples', 1, { w: 1.86, ppl: 249 }, 'F', '4011'], ['Free-Range Eggs, dozen', 1, 649, 'F', '2214'], ['Kraft Paper Bag', 1, 10, 'T', '9001']], tenders: [['CASH', 2000]] },
  { no: '1-08836', t: '9:04 AM', type: 'sale', who: 'Rafa D.', items: [['Rustic Baguette', 1, 375, 'F', '1101'], ['Oat Milk, 1 L', 2, 429, 'F', '2290'], ['Cold Brew, 12 oz', 1, 450, 'T', '3310']], tenders: [['VISA ••1093', null, 'CHIP · AUTH 4Q7731']] }
].map(e => Object.assign({ reprints: 0, emailed: '' }, e));
J.find(e => e.no === '1-08841').reprints = 1;

function totals(e) {
  if (!e.items) return null;
  let sub = 0, disc = 0, taxable = 0;
  const rows = e.items.map(([name, qty, u, tax, plu, d]) => {
    const line = typeof u === 'object' ? Math.round(u.w * u.ppl) * Math.sign(qty) : qty * u;
    const off = d ? Math.round(line * d.pct / 100) : 0;
    sub += line; disc += off; if (tax === 'T') taxable += line - off;
    return { name, qty, u, tax, plu, d, line, off };
  });
  const tax = Math.round(taxable * TAXR), total = sub - disc + tax;
  let left = total;
  const tenders = (e.tenders || []).map(([label, given, note]) => {
    if (given == null) { const a = left; left = 0; return { label, a, note }; }
    const a = Math.min(given, left); left -= a; return { label, a, given, note, change: given - a };
  });
  return { rows, sub, disc, taxable, tax, total, tenders, units: rows.reduce((a, r) => a + Math.abs(r.qty), 0) };
}

/* ── fixed-width layout ── */
const center = (s, w) => s.length >= w ? s.slice(0, w) : ' '.repeat(Math.floor((w - s.length) / 2)) + s;
const lr = (l, r, w) => { const g = w - l.length - r.length; return g >= 1 ? l + ' '.repeat(g) + r : l.slice(0, Math.max(0, w - r.length - 1)) + ' ' + r; };
function wrap(s, w) { const out = []; let cur = ''; s.split(' ').forEach(word => { while (word.length > w) { if (cur) { out.push(cur); cur = ''; } out.push(word.slice(0, w)); word = word.slice(w); } if ((cur ? cur.length + 1 : 0) + word.length > w) { out.push(cur); cur = word; } else cur = cur ? cur + ' ' + word : word; }); if (cur) out.push(cur); return out; }
function layout(e, W, gift, codes) {
  const L = [], T = totals(e), half = Math.floor(W / 2);
  const add = (s, cls = '') => L.push({ s, cls });
  const rule = ch => add(ch.repeat(W), 'rule');
  add(center('MARROW & VINE', half), 'dw');
  add(center('M A R K E T', W), 'b');
  wrap('1180 Tannery Row, Ashford', W).forEach(x => add(center(x, W)));
  add(center('(555) 018-4400', W)); add('');
  add(center('*** REPRINT #' + (e.reprints + 1) + ' ***', W), 'b');
  if (gift) add(center('GIFT RECEIPT', half), 'dw');
  if (e.type === 'return') add(center('RETURN', half), 'dw');
  if (e.type === 'void') add(center('VOID', half), 'dw');
  if (e.type === 'nosale') add(center('NO SALE', half), 'dw');
  add(lr('Receipt ' + e.no, e.t, W)); add(lr('Oct 2, 2026', 'Reg 1 · ' + e.who, W));
  if (e.ref) add(lr('Original', e.ref, W));
  rule('-');
  if (e.type === 'nosale') {
    add(lr('Drawer opened', e.t, W)); wrap('Reason: ' + e.reason, W).forEach(x => add(x)); add(''); add(center('No items · no tender', W));
  } else {
    const nameW = W - (gift ? 4 : 11);
    T.rows.forEach(r => {
      const nm = wrap(r.name, nameW);
      nm.forEach((x, i) => add(i === 0 && !gift ? lr(x, amt(r.line) + ' ' + (r.tax === 'T' ? 'T' : ' '), W) : (i === 0 && gift ? lr(x, String(Math.abs(r.qty)), W) : x)));
      if (!gift) {
        if (typeof r.u === 'object') add('  ' + r.u.w.toFixed(2) + ' lb @ ' + amt(r.u.ppl) + '/lb');
        else if (Math.abs(r.qty) > 1) add('  ' + Math.abs(r.qty) + ' @ ' + amt(r.u));
        if (r.off) add(lr('  ' + r.d.label, amt(-r.off) + ' ' + (r.tax === 'T' ? 'T' : ' '), W));
      }
      if (codes) add('  PLU ' + r.plu);
    });
    rule('-');
    if (gift) {
      add(lr('Items', String(T.units), W)); add('');
      wrap('Return by Nov 1, 2026 for an exchange or store credit. Prices are not shown on gift receipts.', W).forEach(x => add(x));
    } else {
      add(lr('SUBTOTAL', amt(T.sub), W - 2));
      if (T.disc) add(lr('DISCOUNTS', amt(-T.disc), W - 2));
      add(lr('TAX 8.25% ON ' + amt(T.taxable), amt(T.tax), W - 2));
      add(lr(e.type === 'return' ? 'REFUND' : 'TOTAL', (T.total < 0 ? '-$' : '$') + amt(Math.abs(T.total)), half), 'dw');
      if (e.type === 'void') { add(''); add(center('TRANSACTION VOIDED', W), 'b inv'); add(center('Approved by ' + e.mgr, W)); }
      else {
        add('');
        T.tenders.forEach(t => { add(lr(t.label, amt(t.given != null ? t.given : t.a), W - 2)); if (t.note) add('  ' + t.note); });
        const ch = T.tenders.reduce((a, t) => a + (t.change || 0), 0);
        if (T.tenders.some(t => t.given != null)) add(lr('CHANGE', amt(ch), W - 2));
      }
      if (e.member) { add(''); add(lr(e.member, '+' + Math.max(0, Math.floor((T.total - T.tax) / 100)) + ' pts', W)); }
      add(''); add(center(T.units + ' item' + (T.units === 1 ? '' : 's') + ' · T = taxable', W));
    }
  }
  rule('=');
  wrap(e.type === 'nosale' ? 'Drawer events are logged to the journal and reviewed at close.' : 'Returns within 30 days with this receipt. Perishables are final sale.', W).forEach(x => add(center(x, W)));
  L.push({ bc: e.no });
  add(center(e.no, W));
  add(''); add(center('Thank you for shopping local', W));
  return L;
}
const C39 = { '0': '000110100', '1': '100100001', '2': '001100001', '3': '101100000', '4': '000110001', '5': '100110000', '6': '001110000', '7': '000100101', '8': '100100100', '9': '001100100', '-': '010000101', '*': '010010100' };
function code39(text) {
  let x = 0; const bars = [];
  ('*' + text + '*').split('').forEach(ch => {
    [...C39[ch]].forEach((b, i) => { const w = b === '1' ? 3 : 1; if (i % 2 === 0) bars.push(`<rect x="${x}" y="0" width="${w}" height="40"/>`); x += w; });
    x += 1;
  });
  return `<svg viewBox="0 0 ${x - 1} 40" role="img" aria-label="Code 39 barcode ${text}" preserveAspectRatio="none" style="width:${(x - 1) * 1.6}px">${bars.join('')}</svg>`;
}

/* ── state ── */
const S = { sel: '1-08841', filter: 'all', q: '', wi: 1, gift: false, codes: false, used: 22760, log: [['1-08841', 'reprint #1', '10:19 AM']], busy: false, view: 'receipt' };
const TYPES = [['all', 'All'], ['sale', 'Sales'], ['return', 'Returns'], ['void', 'Voids'], ['nosale', 'No sale']];
const entry = () => J.find(e => e.no === S.sel);
function visible() {
  const q = S.q.trim().toLowerCase().replace('$', '');
  return J.filter(e => {
    if (S.filter !== 'all' && e.type !== S.filter) return false;
    if (!q) return true;
    const T = totals(e);
    return e.no.includes(q) || (e.tenders || []).some(t => t[0].toLowerCase().includes(q)) || (T && (amt(T.total).includes(q) || T.tenders.some(t => amt(t.a).includes(q))));
  });
}
function keep(fn) {
  const a = root.contains(document.activeElement) ? document.activeElement : null, k = a && a.dataset.k;
  fn();
  if (k) { const n = root.querySelector('[data-k="' + CSS.escape(k) + '"]'); if (n && n !== document.activeElement && !n.disabled) n.focus({ preventScroll: true }); }
}
function renderJournal() {
  $('.apo-receipt-filters').innerHTML = TYPES.map(([id, l]) => `<button type="button" role="tab" data-act="filter" data-id="${id}" data-k="f-${id}" aria-selected="${S.filter === id}">${l}<span>${id === 'all' ? J.length : J.filter(e => e.type === id).length}</span></button>`).join('');
  const list = visible();
  $('.apo-receipt-list').innerHTML = list.length ? list.map(e => {
    const T = totals(e);
    const ten = (e.tenders || []).map(t => t[0].split(' ')[0].toLowerCase()).join(' + ');
    return `<li class="apo-receipt-row" role="option" data-act="pick" data-id="${e.no}" data-k="r-${e.no}" data-type="${e.type}" aria-selected="${S.sel === e.no}" tabindex="${S.sel === e.no ? 0 : -1}">
      <span class="bar"></span><span class="no">${e.no}</span><span class="amt">${T ? usd(T.total) : '—'}</span>
      <span class="meta"><span class="tag">${{ sale: 'Sale', return: 'Return', void: 'Void', nosale: 'No sale' }[e.type]}</span><span>${e.t}</span>${ten ? `<span>${esc(ten)}</span>` : ''}${e.reprints ? `<span class="rp">reprinted ×${e.reprints}</span>` : ''}${e.emailed ? '<span class="rp">emailed</span>' : ''}</span></li>`;
  }).join('') : `<li class="apo-receipt-none">Nothing in today's journal matches “${esc(S.q)}”.</li>`;
}
function renderOpts() {
  const e = entry(), noItems = !e.items, pl = layout(e, WIDTHS[S.wi].w, S.gift, S.codes).length;
  const left = ROLL - S.used, per = pl * LINE_MM + CUT_MM;
  const box = $('.apo-receipt-opts');
  box.innerHTML = `<div><h3>Paper</h3><div class="apo-receipt-seg" role="radiogroup" aria-label="Paper width">${WIDTHS.map((w, i) => `<button type="button" role="radio" data-act="width" data-i="${i}" data-k="w-${i}" aria-checked="${S.wi === i}">${w.mm}<small>${w.w} col · ${w.note.slice(-1)}</small></button>`).join('')}</div></div>
    <div><div class="apo-receipt-tog"><span>Gift receipt<small>Hide prices, add a return-by date</small></span><button type="button" class="apo-receipt-switch" role="switch" data-act="gift" data-k="gift" aria-checked="${S.gift}" aria-label="Gift receipt" ${noItems || e.type !== 'sale' ? `disabled title="Only sales have gift receipts"` : ''}></button></div>
      <div class="apo-receipt-tog"><span>Item codes<small>Print the PLU under each line</small></span><button type="button" class="apo-receipt-switch" role="switch" data-act="codes" data-k="codes" aria-checked="${S.codes}" aria-label="Item codes" ${noItems ? 'disabled title="No items on this entry"' : ''}></button></div></div>
    <div class="apo-receipt-acts"><button type="button" class="apo-receipt-btn solid" data-act="print" data-k="print" ${S.busy ? 'disabled title="Printer is busy"' : ''}>${svg('print')}${S.busy ? 'Printing…' : 'Reprint #' + (e.reprints + 1)}<kbd>P</kbd></button>
      <button type="button" class="apo-receipt-btn" data-act="email" data-k="email" ${noItems ? 'disabled title="Nothing to send for a no-sale"' : ''}>${svg('mail')}${e.emailed ? 'Email again' : 'Email copy'}<kbd>E</kbd></button></div>
    <div class="apo-receipt-rollwrap"><h3>Printer · Front 1</h3><div class="apo-receipt-roll"><div class="t"><span>Paper left</span><b>${(left / 1000).toFixed(1)} m · ${Math.round(left / ROLL * 100)}%</b></div><div class="bar"><i style="--p:${(left / ROLL).toFixed(4)}"></i></div><div class="t"><span>This receipt</span><b>${pl} lines · ${Math.round(per)} mm</b></div><div class="t"><span>Enough for</span><b>~${Math.floor(left / per)} more</b></div></div></div>
    <div class="apo-receipt-logwrap"><h3>Print log</h3><ul class="apo-receipt-log">${S.log.slice().reverse().slice(0, 6).map(([no, what, t]) => `<li><span><b>${no}</b> ${esc(what)}</span><span>${t}</span></li>`).join('')}</ul></div>`;
  $('[data-printer]').innerHTML = `<i></i>${S.busy ? 'Printing…' : 'Printer ready · ' + Math.round(left / ROLL * 100) + '% paper'}`;
  $('[data-printer]').toggleAttribute('data-busy', S.busy);
}
let lastSig = '';
function renderPaper(force) {
  const e = entry(), W = WIDTHS[S.wi];
  const sig = [e.no, S.wi, S.gift, S.codes, e.reprints].join('|');
  const p = $('.apo-receipt-paper');
  if (sig === lastSig && !force) return;
  const changed = lastSig && lastSig.split('|')[0] !== e.no;
  lastSig = sig;
  p.style.setProperty('--fsz', W.fs);
  p.setAttribute('aria-label', 'Receipt ' + e.no + ', ' + W.w + ' columns');
  p.innerHTML = layout(e, W.w, S.gift, S.codes).map(l => l.bc ? `<div class="bc">${code39(l.bc)}</div>` : `<div class="ln ${l.cls}">${esc(l.s)}</div>`).join('') + '<i class="head"></i>';
  if (changed && !RM.matches) { p.classList.remove('swap'); void p.offsetWidth; p.classList.add('swap'); }
}
function renderNav() {
  $('.apo-receipt-nav').innerHTML = [['journal', 'Journal · ' + visible().length], ['receipt', 'Receipt ' + S.sel]].map(([id, l]) => `<button type="button" role="tab" data-act="view" data-id="${id}" data-k="nv-${id}" aria-selected="${S.view === id}">${l}</button>`).join('');
}
function render() { keep(() => { root.dataset.view = S.view; if (S.gift && entry().type !== 'sale') S.gift = false; renderJournal(); renderOpts(); renderPaper(); renderNav(); }); }
let tt = 0;
function toast(m) { const t = $('.apo-receipt-toast'); t.textContent = m; t.setAttribute('data-on', ''); clearTimeout(tt); tt = setTimeout(() => t.removeAttribute('data-on'), 2800); }
const nowStr = () => new Date().toLocaleTimeString('en-US', { hour: 'numeric', minute: '2-digit' });

/* ── print: reveal one text line per step ── */
function print() {
  if (S.busy) return;
